import { createHash, createHmac, randomBytes, timingSafeEqual } from 'node:crypto';

export type OidcState = {
  state: string;
  nonce: string;
  verifier: string;
  returnTo: string;
};

export function identitySettings(origin: string) {
  const issuer = (process.env.BHD_IDENTITY_ISSUER ?? 'https://id.bhd-om.com').replace(/\/$/, '');
  const clientId =
    process.env.BHD_OAUTH_CLIENT_ID ?? process.env.BHD_IDENTITY_CLIENT_ID ?? 'bhd-r';
  const clientSecret =
    process.env.BHD_OAUTH_CLIENT_SECRET ?? process.env.BHD_IDENTITY_CLIENT_SECRET ?? '';
  const redirectUri =
    process.env.BHD_OAUTH_REDIRECT_URI ??
    process.env.BHD_IDENTITY_REDIRECT_URI ??
    `${origin.replace(/\/$/, '')}/api/auth/bhd/callback`;
  return { issuer, clientId, clientSecret, redirectUri };
}

function cookieSecret(): string {
  return process.env.BHD_R_SESSION_SECRET ?? 'development-session-secret-at-least-32-characters';
}

export function sealOidcState(value: OidcState): string {
  const payload = Buffer.from(JSON.stringify(value)).toString('base64url');
  const signature = createHmac('sha256', cookieSecret()).update(payload).digest('base64url');
  return `${payload}.${signature}`;
}

export function openOidcState(value: string): OidcState {
  const [payload, supplied, extra] = value.split('.');
  if (!payload || !supplied || extra) throw new Error('Malformed OIDC state');
  const expected = createHmac('sha256', cookieSecret()).update(payload).digest('base64url');
  const left = Buffer.from(supplied);
  const right = Buffer.from(expected);
  if (left.length !== right.length || !timingSafeEqual(left, right)) {
    throw new Error('OIDC state signature mismatch');
  }
  return JSON.parse(Buffer.from(payload, 'base64url').toString('utf8')) as OidcState;
}

export function createPkce(): { state: string; nonce: string; verifier: string; challenge: string } {
  const state = randomBytes(24).toString('base64url');
  const nonce = randomBytes(24).toString('base64url');
  const verifier = randomBytes(48).toString('base64url');
  const challenge = createHash('sha256').update(verifier).digest('base64url');
  return { state, nonce, verifier, challenge };
}

export function safeReturnTo(raw: string | null | undefined, fallback = '/ar/portal'): string {
  if (!raw) return fallback;
  if (!raw.startsWith('/') || raw.startsWith('//') || raw.includes('://') || raw.includes('\\')) {
    return fallback;
  }
  return raw;
}

export function secureCookies(): boolean {
  return (
    process.env.COOKIE_SECURE === 'true' ||
    (process.env.COOKIE_SECURE !== 'false' && process.env.NODE_ENV === 'production')
  );
}

import { NextResponse } from 'next/server';
import { createPkce, identitySettings, safeReturnTo, sealOidcState, secureCookies } from '@/lib/bhd/oauth';

export const runtime = 'nodejs';

/** GET /api/auth/bhd/start — required by BHD-PRODUCT-SSO-ADMIN §3.1 */
export async function GET(request: Request) {
  const url = new URL(request.url);
  const { issuer, clientId, redirectUri } = identitySettings(url.origin);
  const returnTo = safeReturnTo(url.searchParams.get('returnTo'));
  const { state, nonce, verifier, challenge } = createPkce();

  const authorization = new URL(`${issuer}/oauth/authorize`);
  authorization.search = new URLSearchParams({
    response_type: 'code',
    client_id: clientId,
    redirect_uri: redirectUri,
    scope: 'openid profile email',
    state,
    nonce,
    code_challenge: challenge,
    code_challenge_method: 'S256',
  }).toString();

  if (!authorization.hostname.endsWith('bhd-om.com') && authorization.hostname !== 'localhost') {
    return NextResponse.json({ error: 'Unsafe identity host' }, { status: 500 });
  }

  const response = NextResponse.redirect(authorization.toString(), 302);
  response.cookies.set({
    name: 'bhd_oauth_state',
    value: sealOidcState({ state, nonce, verifier, returnTo }),
    httpOnly: true,
    secure: secureCookies(),
    sameSite: 'lax',
    path: '/api/auth/bhd',
    maxAge: 300,
  });
  return response;
}

