export default async function LoginPage({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const { locale } = await params;
  const query = await searchParams;
  setRequestLocale(locale);
  const t = await getTranslations();
  const ar = locale === 'ar';
  const local = query.local === '1';
  const bhdCode = typeof query.bhd === 'string' ? query.bhd : undefined;
  const nextRaw = typeof query.next === 'string' ? query.next : '';
  const returnTo =
    typeof query.returnTo === 'string' &&
    query.returnTo.startsWith('/') &&
    !query.returnTo.startsWith('//')
      ? query.returnTo
      : `/${locale}/portal`;

  // BHD-PRODUCT-SSO-ADMIN §3.2 — admin must never use local password login
  if (
    local &&
    (nextRaw.startsWith('/admin') ||
      nextRaw.startsWith('/platform') ||
      returnTo.startsWith('/admin') ||
      returnTo.startsWith('/platform') ||
      returnTo.includes('/platform'))
  ) {
    redirect(
      `/api/auth/admin-entry?next=${encodeURIComponent(
        nextRaw.startsWith('/') ? nextRaw : '/platform',
      )}`,
    );
  }

  if (!local && !bhdCode) {
    redirect(`/api/auth/bhd/start?returnTo=${encodeURIComponent(returnTo)}`);
  }

  const errorCopy = bhdCode
    ? (bhdErrors[bhdCode] ?? {
        ar: 'تعذّر إكمال الدخول الموحّد.',
        en: 'Unified sign-in could not be completed.',
      })
    : null;

  return (
    <section className="login-screen">
      <div className="login-shell">
        <header className="login-top">
          <Link href="/" className="login-logo" aria-label={ar ? 'BHD R الرئيسية' : 'BHD R home'}>
            <Logo descriptor={t('Brand.descriptor')} />
          </Link>
          <Link
            href="/login"
            locale={ar ? 'en' : 'ar'}
            className="login-language"
            hrefLang={ar ? 'en' : 'ar'}
          >
            {ar ? 'English' : 'العربية'}
          </Link>
        </header>

        <div className="login-stage">
          <aside className="login-brand-panel">
            <span className="login-brand-kicker">{ar ? 'بوابة BHD R' : 'BHD R Gateway'}</span>
            <h1>
              {ar ? 'من هنا تبدأ إدارة عقار أوضح' : 'Clearer property management starts here'}
            </h1>
            <p>
              {ar
                ? 'سجّل دخولك إلى منظومة بن حمود للتطوير بهوية رقمية واحدة.'
                : 'Sign in to the Bin Hamood Development ecosystem with one digital identity.'}
            </p>
            <strong className="login-brand-promise">Build Higher Dreams</strong>
          </aside>

          <div className="login-card">
            <span className="login-card__eyebrow">{ar ? 'الدخول الموحد' : 'Unified sign in'}</span>
            <h2>{ar ? 'مرحباً بك في BHD R' : 'Welcome to BHD R'}</h2>

            {errorCopy ? (
              <>
                <p role="alert">{ar ? errorCopy.ar : errorCopy.en}</p>
                <a
                  className="login-submit"
                  href={`/api/auth/bhd/start?returnTo=${encodeURIComponent(returnTo)}`}
                >
                  <span className="login-submit__mark" aria-hidden="true">
                    B
                  </span>
                  {t('Auth.action')}
                </a>
              </>
            ) : (
              <>
                <p>
                  {ar
                    ? 'طوارئ فقط: حساب مستأجر محلي مُنح مع عقد الإيجار.'
                    : 'Emergency only: local tenant account issued with a lease.'}
                </p>
                <div className="login-local__form">
                  <PasswordLoginForm />
                  <p className="muted">{t('Auth.activation')}</p>
                  <Link href="/forgot-password">
                    {ar ? 'نسيت كلمة المرور؟' : 'Forgot password?'}
                  </Link>
                </div>
                <p className="login-footnote">
                  <a href={`/api/auth/bhd/start?returnTo=${encodeURIComponent(returnTo)}`}>
                    {ar ? 'العودة إلى الدخول الموحّد' : 'Back to unified sign-in'}
                  </a>
                </p>
              </>
            )}

            <p className="login-footnote">
              {ar ? 'بالمتابعة فإنك توافق على ' : 'By continuing, you agree to the '}
              <Link href="/privacy">{ar ? 'الخصوصية' : 'privacy policy'}</Link>
              {ar ? ' و' : ' and '}
              <Link href="/terms">{ar ? 'الشروط' : 'terms'}</Link>.
            </p>
          </div>
        </div>
      </div>
    </section>
  );
}

'use client';

import { useEffect, useId, useRef, useState } from 'react';
import { BHD_APPS, type BhdApp } from '@/lib/bhd/apps';
import type { Viewer } from '@/lib/types';

type Panel = 'apps' | 'account' | null;

function isCurrentApp(app: BhdApp): boolean {
  return app.id === 'bhd-r' || app.clientId === 'bhd-r';
}

function hrefForApp(app: BhdApp, locale: 'ar' | 'en'): string {
  if (app.id === 'account') return 'https://id.bhd-om.com/account';
  if (isCurrentApp(app)) return `/${locale}`;
  if (app.mode === 'sso' && app.startUrl) return app.startUrl;
  return `${app.origin.replace(/\/$/, '')}/`;
}

export function BhdAppSwitcher({ viewer, locale }: { viewer: Viewer; locale: 'ar' | 'en' }) {
  const [panel, setPanel] = useState<Panel>(null);
  const rootRef = useRef<HTMLDivElement>(null);
  const appsId = useId();
  const accountId = useId();
  const initial = viewer.displayName.trim().slice(0, 1) || 'B';
  const ar = locale === 'ar';
  const apps = BHD_APPS.filter((app) => app.enabled);

  useEffect(() => {
    if (!panel) return;
    const closeOnEscape = (event: KeyboardEvent) => {
      if (event.key === 'Escape') setPanel(null);
    };
    const closeOnOutsideClick = (event: MouseEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) setPanel(null);
    };
    document.addEventListener('keydown', closeOnEscape);
    document.addEventListener('mousedown', closeOnOutsideClick);
    return () => {
      document.removeEventListener('keydown', closeOnEscape);
      document.removeEventListener('mousedown', closeOnOutsideClick);
    };
  }, [panel]);

  function signOut() {
    window.location.assign('/api/auth/bhd/logout');
  }

  return (
    <div className="bhd-switcher-slot" ref={rootRef}>
      <button
        type="button"
        className="bhd-switcher-grid"
        aria-label={ar ? 'تطبيقات BHD' : 'BHD apps'}
        aria-haspopup="dialog"
        aria-expanded={panel === 'apps'}
        aria-controls={panel === 'apps' ? appsId : undefined}
        onClick={() => setPanel((current) => (current === 'apps' ? null : 'apps'))}
      >
        <span aria-hidden="true">
          {Array.from({ length: 9 }).map((_, index) => (
            <i key={index} />
          ))}
        </span>
      </button>
      <button
        type="button"
        className="bhd-switcher-avatar"
        aria-label={ar ? 'الحساب' : 'Account'}
        aria-haspopup="dialog"
        aria-expanded={panel === 'account'}
        aria-controls={panel === 'account' ? accountId : undefined}
        onClick={() => setPanel((current) => (current === 'account' ? null : 'account'))}
      >
        <span>{initial}</span>
      </button>

      {panel === 'apps' ? (
        <div
          className="bhd-switcher-card"
          id={appsId}
          role="dialog"
          aria-label={ar ? 'تطبيقات BHD' : 'BHD apps'}
        >
          <div className="bhd-switcher-card__head">
            <strong>{ar ? 'تطبيقات BHD' : 'BHD apps'}</strong>
            <small>{ar ? 'حساب واحد · منتجات مستقلة' : 'One account · independent products'}</small>
          </div>
          <div className="bhd-switcher-apps">
            {apps.map((app) => {
              const current = isCurrentApp(app);
              return (
                <a
                  key={app.id}
                  className={current ? 'bhd-switcher-app is-current' : 'bhd-switcher-app'}
                  href={hrefForApp(app, locale)}
                  aria-current={current ? 'page' : undefined}
                  onClick={() => setPanel(null)}
                >
                  <span
                    className="bhd-app-mark"
                    style={{ background: app.soft, color: app.accent }}
                  >
                    {app.mark}
                  </span>
                  <span>{ar ? app.nameAr : app.nameEn}</span>
                </a>
              );
            })}
          </div>
        </div>
      ) : null}

      {panel === 'account' ? (
        <div
          className="bhd-switcher-card bhd-switcher-account"
          id={accountId}
          role="dialog"
          aria-label={ar ? 'الحساب' : 'Account'}
        >
          <div className="bhd-switcher-account__user">
            <span className="bhd-switcher-account__initial">{initial}</span>
            <div>
              <strong>{viewer.displayName}</strong>
              <small>{viewer.email ?? viewer.username ?? (ar ? 'حساب BHD' : 'BHD account')}</small>
            </div>
          </div>
          <a href={`/${locale}/portal`}>{ar ? 'مساحتي في BHD R' : 'My BHD R workspace'}</a>
          <a href="https://id.bhd-om.com/account">{ar ? 'إدارة حساب BHD' : 'Manage BHD account'}</a>
          <button type="button" onClick={signOut}>
            {ar ? 'تسجيل الخروج' : 'Sign out'}
          </button>
        </div>
      ) : null}
    </div>
  );
}

