const fs = require("fs");
const crypto = require("crypto");
const path = require("path");

const envPath = path.join(__dirname, ".env.local");
const env = Object.fromEntries(
  fs
    .readFileSync(envPath, "utf8")
    .split(/\r?\n/)
    .filter((line) => line && !line.startsWith("#"))
    .map((line) => {
      const i = line.indexOf("=");
      let value = line.slice(i + 1);
      if (
        (value.startsWith('"') && value.endsWith('"')) ||
        (value.startsWith("'") && value.endsWith("'"))
      ) {
        value = value.slice(1, -1);
      }
      return [line.slice(0, i), value];
    }),
);

const root = env.AUTH_SECRET;
if (!root) {
  console.error("no AUTH_SECRET");
  process.exit(1);
}

const secret = crypto.createHmac("sha256", root).update("bhd-oauth:bhd-r").digest("base64url");
const out = path.join(process.env.TEMP || ".", "bhd-r-oauth-secret.txt");
fs.writeFileSync(out, secret, { encoding: "utf8" });
console.log(`DERIVED_LEN=${secret.length}`);
console.log(`OUT=${out}`);

const { execFileSync } = require("child_process");
const fs = require("fs");
const path = require("path");

const secret = fs.readFileSync(path.join(process.env.TEMP, "bhd-r-oauth-secret.txt"), "utf8").trim();
const cwd = process.cwd();

function run(args, input) {
  console.log(`> vercel ${args.join(" ")}`);
  execFileSync("npx", ["--yes", "vercel", ...args], {
    cwd,
    input,
    stdio: ["pipe", "inherit", "inherit"],
    env: process.env,
  });
}

for (const name of ["BHD_OAUTH_CLIENT_SECRET", "BHD_OAUTH_REDIRECT_URI", "BHD_IDENTITY_CLIENT_SECRET", "BHD_IDENTITY_REDIRECT_URI"]) {
  try {
    run(["env", "rm", name, "production", "--yes"]);
  } catch {}
  try {
    run(["env", "rm", name, "preview", "--yes"]);
  } catch {}
}

const redirect = "https://bhd-r-api-phi.vercel.app/api/auth/bhd/callback";
for (const env of ["production", "preview"]) {
  run(["env", "add", "BHD_OAUTH_CLIENT_SECRET", env], `${secret}\n`);
  run(["env", "add", "BHD_OAUTH_REDIRECT_URI", env], `${redirect}\n`);
  run(["env", "add", "BHD_IDENTITY_CLIENT_SECRET", env], `${secret}\n`);
  run(["env", "add", "BHD_IDENTITY_REDIRECT_URI", env], `${redirect}\n`);
}

console.log("done");

