import { createHash, randomBytes, randomUUID } from 'node:crypto';
import { and, eq, isNull, sql } from 'drizzle-orm';
import { decodeJwt } from 'jose';
import {
  createDatabase,
  memberships,
  organizations,
  sessions,
  users,
  type Database,
} from '@bhd-r/db';
import {
  issueSessionToken,
  permissionsForRoles,
  roleKeySchema,
  sessionClaimsSchema,
  verifyIdentityToken,
  type Permission,
  type SessionClaims,
} from '@bhd-r/authz';
import { createCsrfToken } from '@bhd-r/security';

export type IssuedSession = {
  token: string;
  csrf: string;
  claims: SessionClaims;
};

type Tx = Parameters<Parameters<Database['transaction']>[0]>[0];

const tokenHash = (token: string) => createHash('sha256').update(token).digest('hex');

function sessionSecret(): Uint8Array {
  return new TextEncoder().encode(
    process.env.BHD_R_SESSION_SECRET ?? 'development-session-secret-at-least-32-characters',
  );
}

async function withSystem<T>(work: (tx: Tx) => Promise<T>): Promise<T> {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL is required');
  const { client, db } = createDatabase(url, { max: 1 });
  try {
    return await db.transaction(async (tx) => {
      await tx.execute(sql`select set_config('app.platform_admin', 'true', true)`);
      await tx.execute(sql`select set_config('app.public', 'false', true)`);
      return work(tx);
    });
  } finally {
    await client.end();
  }
}

async function issueForUser(tx: Tx, userId: string): Promise<IssuedSession> {
  const user = await tx.query.users.findFirst({ where: eq(users.id, userId) });
  if (!user) throw new Error('User missing after identity login');
  const allMemberships = await tx.query.memberships.findMany({
    where: and(eq(memberships.userId, userId), eq(memberships.status, 'active')),
  });
  if (allMemberships.length === 0) throw new Error('No active organization membership');
  const selectedOrganization = allMemberships[0]!.organizationId;
  const organizationMemberships = allMemberships.filter(
    (membership) => membership.organizationId === selectedOrganization,
  );
  const roles = organizationMemberships
    .map((membership) => roleKeySchema.safeParse(membership.roleKey))
    .filter((result) => result.success)
    .map((result) => result.data);
  const customPermissions = organizationMemberships
    .flatMap((membership) => membership.permissions)
    .filter(
      (permission): permission is Permission =>
        sessionClaimsSchema.shape.permissions.element.safeParse(permission).success,
    );
  const sid = randomUUID();
  const claims = sessionClaimsSchema.parse({
    sub: user.id,
    sid,
    organizationId: selectedOrganization,
    partyId: organizationMemberships.find((membership) => membership.partyId)?.partyId ?? null,
    roles,
    permissions: [...new Set([...permissionsForRoles(roles), ...customPermissions])],
    locale: user.locale === 'en' ? 'en' : 'ar',
    sessionVersion: user.sessionVersion,
  });
  const token = await issueSessionToken(claims, sessionSecret(), 8 * 60 * 60);
  await tx.insert(sessions).values({
    id: sid,
    userId: user.id,
    tokenIdHash: tokenHash(token),
    expiresAt: new Date(Date.now() + 8 * 60 * 60_000),
  });
  return {
    token,
    csrf: createCsrfToken(
      sid,
      process.env.CSRF_SECRET ?? 'development-csrf-secret-must-be-at-least-32-chars',
    ),
    claims,
  };
}

async function provisionIdentityUser(
  tx: Tx,
  identity: { subject: string; email?: string; name?: string },
) {
  const email =
    identity.email?.trim().toLowerCase() ||
    `${identity.subject.replace(/[^a-z0-9]/gi, '').slice(0, 24) || 'user'}@identity.bhd-om.local`;
  const displayName = identity.name?.trim() || email.split('@')[0] || 'BHD user';
  const base =
    email
      .split('@')[0]!
      .replace(/[^a-z0-9]/gi, '')
      .toLowerCase()
      .slice(0, 16) || 'user';
  const username = `${base}.${randomBytes(3).toString('hex')}`;
  const slug = `sso-${identity.subject.replace(/[^a-z0-9-]/gi, '').slice(0, 40) || randomBytes(6).toString('hex')}`;

  const insertedUsers = await tx
    .insert(users)
    .values({
      username,
      email,
      displayName,
      identitySubject: identity.subject,
    })
    .returning();
  const user = insertedUsers[0]!;

  const insertedOrgs = await tx
    .insert(organizations)
    .values({
      type: 'individual',
      slug,
      legalName: displayName,
      displayNameAr: displayName,
      displayNameEn: displayName,
      planKey: 'starter',
    })
    .returning();
  const organization = insertedOrgs[0]!;

  await tx.insert(memberships).values({
    organizationId: organization.id,
    userId: user.id,
    roleKey: 'organization_owner',
  });

  return user;
}

/** Issue BHD R session from a verified Identity ID token (SSO §0.7). */
export async function issueIdentitySession(input: {
  idToken: string;
  nonce: string;
}): Promise<IssuedSession> {
  const identityTokenSecret =
    process.env.BHD_IDENTITY_TOKEN_SECRET ?? process.env.IDENTITY_TOKEN_SECRET;
  const identity = await verifyIdentityToken({
    token: input.idToken,
    issuer: process.env.BHD_IDENTITY_ISSUER ?? 'https://id.bhd-om.com',
    clientId: process.env.BHD_OAUTH_CLIENT_ID ?? process.env.BHD_IDENTITY_CLIENT_ID ?? 'bhd-r',
    expectedNonce: input.nonce,
    ...(identityTokenSecret ? { sharedSecret: identityTokenSecret } : {}),
  });
  const verifiedClaims = decodeJwt(input.idToken);
  if (verifiedClaims.nonce !== input.nonce) throw new Error('Identity nonce mismatch');
  const clientId =
    process.env.BHD_OAUTH_CLIENT_ID ?? process.env.BHD_IDENTITY_CLIENT_ID ?? 'bhd-r';
  if (
    Array.isArray(verifiedClaims.aud) &&
    verifiedClaims.aud.length > 1 &&
    verifiedClaims.azp !== clientId
  ) {
    throw new Error('Identity authorized party mismatch');
  }

  return withSystem(async (tx) => {
    let user = await tx.query.users.findFirst({
      where: eq(users.identitySubject, identity.subject),
    });

    if (!user && identity.email && identity.emailVerified) {
      const byEmail = await tx.query.users.findFirst({
        where: eq(users.email, identity.email.trim().toLowerCase()),
      });
      if (byEmail && !byEmail.identitySubject) {
        const linked = await tx
          .update(users)
          .set({
            identitySubject: identity.subject,
            displayName: identity.name?.trim() || byEmail.displayName,
          })
          .where(and(eq(users.id, byEmail.id), isNull(users.identitySubject)))
          .returning();
        user = linked[0] ?? byEmail;
      }
    }

    if (!user) {
      user = await provisionIdentityUser(tx, {
        subject: identity.subject,
        ...(identity.email ? { email: identity.email } : {}),
        ...(identity.name ? { name: identity.name } : {}),
      });
    }

    if (!user || user.disabledAt) throw new Error('Identity account cannot sign in');

    if (identity.name?.trim() && identity.name.trim() !== user.displayName) {
      await tx.update(users).set({ displayName: identity.name.trim() }).where(eq(users.id, user.id));
    }

    await tx
      .update(sessions)
      .set({ revokedAt: new Date() })
      .where(and(eq(sessions.userId, user.id), isNull(sessions.revokedAt)));
    await tx
      .update(users)
      .set({ sessionVersion: sql`${users.sessionVersion} + 1` })
      .where(eq(users.id, user.id));

    return issueForUser(tx, user.id);
  });
}

export function hasDatabaseUrl(): boolean {
  return Boolean(process.env.DATABASE_URL?.trim());
}

import { cookies } from 'next/headers';
import { NextResponse } from 'next/server';
import { z } from 'zod';
import {
  identitySettings,
  openOidcState,
  secureCookies,
} from '@/lib/bhd/oauth';
import { hasDatabaseUrl, issueIdentitySession } from '@/lib/bhd/identity-session';

export const runtime = 'nodejs';

/** GET /api/auth/bhd/callback — required by BHD-PRODUCT-SSO-ADMIN §3.1 */
export async function GET(request: Request) {
  const url = new URL(request.url);
  const code = url.searchParams.get('code');
  const state = url.searchParams.get('state');
  const oauthError = url.searchParams.get('error');
  const cookieStore = await cookies();
  const cookie = cookieStore.get('bhd_oauth_state')?.value;

  const clearAndRedirect = (path: string, status = 302) => {
    const response = NextResponse.redirect(new URL(path, url.origin), status);
    response.cookies.set({
      name: 'bhd_oauth_state',
      value: '',
      httpOnly: true,
      secure: secureCookies(),
      sameSite: 'lax',
      path: '/api/auth/bhd',
      maxAge: 0,
    });
    return response;
  };

  if (oauthError) return clearAndRedirect(`/ar/login?bhd=${encodeURIComponent(oauthError)}`);
  if (!cookie || !code || !state) return clearAndRedirect('/ar/login?bhd=state');

  let saved: ReturnType<typeof openOidcState>;
  try {
    saved = openOidcState(cookie);
  } catch {
    return clearAndRedirect('/ar/login?bhd=state');
  }
  if (saved.state !== state) return clearAndRedirect('/ar/login?bhd=state');

  const { issuer, clientId, clientSecret, redirectUri } = identitySettings(url.origin);
  const discoveryResponse = await fetch(`${issuer}/.well-known/openid-configuration`, {
    signal: AbortSignal.timeout(5_000),
    redirect: 'error',
  });
  if (!discoveryResponse.ok) return clearAndRedirect('/ar/login?bhd=discovery');
  const discovery = z
    .object({ token_endpoint: z.string().url() })
    .parse(await discoveryResponse.json());
  const tokenEndpoint = new URL(discovery.token_endpoint);
  if (tokenEndpoint.origin !== new URL(issuer).origin || tokenEndpoint.protocol !== 'https:') {
    return clearAndRedirect('/ar/login?bhd=unsafe');
  }

  const tokenResponse = await fetch(discovery.token_endpoint, {
    method: 'POST',
    signal: AbortSignal.timeout(8_000),
    redirect: 'error',
    headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({
      grant_type: 'authorization_code',
      code,
      client_id: clientId,
      client_secret: clientSecret,
      redirect_uri: redirectUri,
      code_verifier: saved.verifier,
    }),
  });
  if (!tokenResponse.ok) return clearAndRedirect('/ar/login?bhd=token');
  const tokens = z.object({ id_token: z.string().min(20) }).parse(await tokenResponse.json());

  let issued: { token: string; csrf: string };
  try {
    if (hasDatabaseUrl()) {
      issued = await issueIdentitySession({
        idToken: tokens.id_token,
        nonce: saved.nonce,
      });
    } else {
      const apiOrigin = (process.env.API_INTERNAL_ORIGIN ?? process.env.API_ORIGIN ?? '').replace(
        /\/$/,
        '',
      );
      const apiPublic =
        /^https:\/\//i.test(apiOrigin) &&
        !/localhost|127\.0\.0\.1|\.local|\.internal/i.test(apiOrigin);

      if (!apiPublic && process.env.VERCEL) {
        return clearAndRedirect('/ar/login?bhd=api');
      }

      const sessionApi = apiPublic
        ? `${apiOrigin}/v1/auth/identity/session`
        : `${process.env.API_INTERNAL_ORIGIN ?? 'http://127.0.0.1:4000'}/v1/auth/identity/session`;

      const sessionResponse = await fetch(sessionApi, {
        method: 'POST',
        signal: AbortSignal.timeout(10_000),
        headers: { 'content-type': 'application/json' },
        body: JSON.stringify({ idToken: tokens.id_token, nonce: saved.nonce }),
      }).catch(() => null);

      if (!sessionResponse?.ok) {
        const codeHint = sessionResponse?.status === 401 ? 'account' : 'session';
        return clearAndRedirect(`/ar/login?bhd=${codeHint}`);
      }

      issued = z
        .object({ token: z.string().min(20), csrf: z.string().min(8) })
        .parse(await sessionResponse.json());
    }
  } catch {
    return clearAndRedirect('/ar/login?bhd=session');
  }

  const response = clearAndRedirect(saved.returnTo);
  response.cookies.set({
    name: 'bhd_r_session',
    value: issued.token,
    httpOnly: true,
    secure: secureCookies(),
    sameSite: 'lax',
    path: '/',
    maxAge: 8 * 60 * 60,
  });
  response.cookies.set({
    name: 'bhd_r_csrf',
    value: issued.csrf,
    httpOnly: false,
    secure: secureCookies(),
    sameSite: 'strict',
    path: '/',
    maxAge: 8 * 60 * 60,
  });
  return response;
}

