function readEnvFile(filePath) {
  const map = {};
  for (const line of fs.readFileSync(filePath, "utf8").split(/\r?\n/)) {
    if (!line || line.startsWith("#")) continue;
    const i = line.indexOf("=");
    if (i < 0) continue;
    map[line.slice(0, i)] = line.slice(i + 1).replace(/^\uFEFF/, "").trim();
  }
  return map;
}

