import fs from 'node:fs';
import { spawnSync } from 'node:child_process';

function get(path, key) {
  const raw = fs.readFileSync(path, 'utf8');
  const m = raw.match(new RegExp(`^${key}=(.*)$`, 'm'));
  if (!m) throw new Error(`missing ${key} in ${path}`);
  let v = m[1];
  if (
    (v.startsWith('"') && v.endsWith('"')) ||
    (v.startsWith("'") && v.endsWith("'"))
  ) {
    v = v.slice(1, -1);
  }
  return v.replace(/^\uFEFF/, '').replace(/\\r\\n$/i, '').replace(/[\r\n]+$/g, '').trim();
}

const idEnv =
  'C:/dev/ONE-BHD/BHD-Complete-Brand-and-Portal-v1.1.0/.env.identity.check';
const secret = get(idEnv, 'IDENTITY_TOKEN_SECRET');
if (secret.length < 32) throw new Error('identity secret too short');

const pairs = [
  ['BHD_IDENTITY_TOKEN_SECRET', secret],
  ['IDENTITY_TOKEN_SECRET', secret],
];

for (const [name, value] of pairs) {
  console.log('updating', name, 'len=', value.length);
  spawnSync('npx', ['vercel', 'env', 'rm', name, 'production', '-y'], {
    stdio: 'inherit',
    shell: true,
  });
  spawnSync('npx', ['vercel', 'env', 'rm', name, 'preview', '-y'], {
    stdio: 'inherit',
    shell: true,
  });
  for (const envName of ['production', 'preview']) {
    const result = spawnSync(
      'npx',
      ['vercel', 'env', 'add', name, envName],
      {
        input: value + '\n',
        encoding: 'utf8',
        shell: true,
      },
    );
    if (result.status !== 0) {
      console.error(result.stdout, result.stderr);
      throw new Error(`failed to set ${name} ${envName}`);
    }
    console.log('set', name, envName, 'ok');
  }
}

console.log('done');

