import { spawnSync } from 'node:child_process';
import { createHmac } from 'node:crypto';
import fs from 'node:fs';

function readEnvFile(path, key) {
  const raw = fs.readFileSync(path, 'utf8');
  const m = raw.match(new RegExp(`^${key}=(.*)$`, 'm'));
  if (!m) throw new Error(`missing ${key}`);
  let v = m[1];
  if (
    (v.startsWith('"') && v.endsWith('"')) ||
    (v.startsWith("'") && v.endsWith("'"))
  ) {
    v = v.slice(1, -1);
  }
  return v
    .replace(/^\uFEFF/, '')
    .replace(/\\r\\n$/gi, '')
    .replace(/\\n$/gi, '')
    .replace(/[\r\n]+$/g, '')
    .trim();
}

function setEnv(name, value, environments = ['production', 'preview']) {
  if (!value) throw new Error(`empty ${name}`);
  for (const envName of environments) {
    spawnSync('npx', ['vercel', 'env', 'rm', name, envName, '-y'], {
      stdio: 'inherit',
      shell: true,
    });
    // Write value to a temp file with NO trailing newline, then pipe bytes.
    const tmp = `.env.set.${name}.${envName}.tmp`;
    fs.writeFileSync(tmp, value, { encoding: 'utf8' });
    const result = spawnSync(
      `Get-Content -Raw -Encoding utf8 ${tmp} | npx vercel env add ${name} ${envName}`,
      {
        shell: 'powershell.exe',
        encoding: 'utf8',
      },
    );
    fs.unlinkSync(tmp);
    if (result.status !== 0) {
      console.error(result.stdout, result.stderr);
      throw new Error(`failed ${name} ${envName}`);
    }
    console.log('set', name, envName, 'len', value.length);
  }
}

const idEnv =
  'C:/dev/ONE-BHD/BHD-Complete-Brand-and-Portal-v1.1.0/.env.identity.check';
if (!fs.existsSync(idEnv)) {
  spawnSync(
    'npx',
    ['vercel', 'env', 'pull', '.env.identity.check', '--environment=production', '--yes'],
    {
      cwd: 'C:/dev/ONE-BHD/BHD-Complete-Brand-and-Portal-v1.1.0',
      stdio: 'inherit',
      shell: true,
    },
  );
}

const secret = readEnvFile(idEnv, 'IDENTITY_TOKEN_SECRET');
const auth = readEnvFile(idEnv, 'AUTH_SECRET');
const clientSecret = createHmac('sha256', auth)
  .update('bhd-oauth:bhd-r')
  .digest('base64url');

setEnv('BHD_IDENTITY_ISSUER', 'https://id.bhd-om.com');
setEnv('BHD_OAUTH_CLIENT_ID', 'bhd-r');
setEnv('BHD_IDENTITY_TOKEN_SECRET', secret);
setEnv('IDENTITY_TOKEN_SECRET', secret);
setEnv('BHD_OAUTH_CLIENT_SECRET', clientSecret);
setEnv('BHD_OAUTH_REDIRECT_URI', 'https://bhd-r-api-phi.vercel.app/api/auth/bhd/callback');

console.log('all env cleaned');

