import type { Pool } from 'pg';
import {
  emptyBackfillMetrics,
  mergeBackfillMetrics,
  tryRotateEncryptedField,
  type EncryptionBackfillMetrics,
  type Keyring,
} from '@bhd-r/security';
import { z } from 'zod';
import { logger } from '../logger.js';

export const encryptionBackfillPayloadSchema = z.object({
  target: z.enum([
    'users.totp_secret_encrypted',
    'parties.national_id_encrypted',
    'parties.registration_number_encrypted',
    'party_identity_documents.number_encrypted',
    'payment_gateway_settings.credentials_encrypted',
  ]),
  afterId: z.string().uuid().nullable().default(null),
  batchSize: z.number().int().min(1).max(200).default(50),
  continue: z.boolean().default(true),
});

export type EncryptionBackfillPayload = z.infer<typeof encryptionBackfillPayloadSchema>;

interface TargetConfig {
  table: string;
  column: string;
  idColumn: string;
  orgScoped: boolean;
  purpose: string;
  context: (row: { id: string; organization_id?: string | null }) => string;
}

const TARGETS: Record<EncryptionBackfillPayload['target'], TargetConfig> = {
  'users.totp_secret_encrypted': {
    table: 'users',
    column: 'totp_secret_encrypted',
    idColumn: 'id',
    orgScoped: false,
    purpose: 'totp',
    context: (row) => `totp:${row.id}`,
  },
  'parties.national_id_encrypted': {
    table: 'parties',
    column: 'national_id_encrypted',
    idColumn: 'id',
    orgScoped: true,
    purpose: 'party-identity',
    context: (row) => `party:national:${row.id}`,
  },
  'parties.registration_number_encrypted': {
    table: 'parties',
    column: 'registration_number_encrypted',
    idColumn: 'id',
    orgScoped: true,
    purpose: 'party-identity',
    context: (row) => `party:registration:${row.id}`,
  },
  'party_identity_documents.number_encrypted': {
    table: 'party_identity_documents',
    column: 'number_encrypted',
    idColumn: 'id',
    orgScoped: true,
    purpose: 'party-document',
    context: (row) => `party-document:${row.id}`,
  },
  'payment_gateway_settings.credentials_encrypted': {
    table: 'payment_gateway_settings',
    column: 'credentials_encrypted',
    idColumn: 'id',
    orgScoped: true,
    purpose: 'payment-gateway',
    context: (row) => `payment-gateway:${row.organization_id ?? row.id}`,
  },
};

export interface EncryptionBackfillResult {
  target: EncryptionBackfillPayload['target'];
  metrics: EncryptionBackfillMetrics;
  nextAfterId: string | null;
  done: boolean;
}

export function createEncryptionBackfillProcessor(
  pool: Pool,
  keyringFor: (purpose: string) => Keyring,
) {
  return async function processEncryptionBackfill(
    payload: EncryptionBackfillPayload,
  ): Promise<EncryptionBackfillResult> {
    const input = encryptionBackfillPayloadSchema.parse(payload);
    const target = TARGETS[input.target];
    const keyring = keyringFor(target.purpose);
    const metrics = emptyBackfillMetrics();
    const client = await pool.connect();
    let nextAfterId: string | null = input.afterId;
    try {
      await client.query('BEGIN');
      await client.query("SET LOCAL app.worker = 'true'");
      const selectSql = target.orgScoped
        ? `SELECT ${target.idColumn} AS id, organization_id, ${target.column} AS ciphertext
           FROM ${target.table}
           WHERE ${target.column} IS NOT NULL
             AND ($1::uuid IS NULL OR ${target.idColumn} > $1::uuid)
           ORDER BY ${target.idColumn}
           LIMIT $2
           FOR UPDATE SKIP LOCKED`
        : `SELECT ${target.idColumn} AS id, NULL::uuid AS organization_id, ${target.column} AS ciphertext
           FROM ${target.table}
           WHERE ${target.column} IS NOT NULL
             AND ($1::uuid IS NULL OR ${target.idColumn} > $1::uuid)
           ORDER BY ${target.idColumn}
           LIMIT $2
           FOR UPDATE SKIP LOCKED`;
      const rows = await client.query<{
        id: string;
        organization_id: string | null;
        ciphertext: string;
      }>(selectSql, [input.afterId, input.batchSize]);
      for (const row of rows.rows) {
        const rotated = tryRotateEncryptedField(
          row.ciphertext,
          keyring,
          target.context(row),
          metrics,
        );
        if (rotated.changed) {
          await client.query(
            `UPDATE ${target.table}
             SET ${target.column} = $2, updated_at = now()
             WHERE ${target.idColumn} = $1`,
            [row.id, rotated.value],
          );
        }
        nextAfterId = row.id;
      }
      await client.query('COMMIT');
      const done = rows.rows.length < input.batchSize;
      logger.info(
        {
          target: input.target,
          activeVersion: keyring.activeVersion,
          metrics,
          nextAfterId,
          done,
        },
        'Encryption backfill batch completed',
      );
      return { target: input.target, metrics, nextAfterId: done ? null : nextAfterId, done };
    } catch (error) {
      await client.query('ROLLBACK');
      throw error;
    } finally {
      client.release();
    }
  };
}

export { mergeBackfillMetrics };

/**
 * Machine-readable status transitions for BHD R domain aggregates.
 * Services must reject jumps not listed in `transitions`.
 */

export type StateMachine = {
  name: string;
  initial: string;
  terminals: readonly string[];
  transitions: Readonly<Record<string, readonly string[]>>;
};

export function assertTransition(
  machine: StateMachine,
  from: string,
  to: string,
): { ok: true } | { ok: false; reason: string } {
  if (from === to) return { ok: true };
  const allowed = machine.transitions[from];
  if (!allowed) return { ok: false, reason: `Unknown source state ${from} for ${machine.name}` };
  if (!allowed.includes(to)) {
    return {
      ok: false,
      reason: `Illegal ${machine.name} transition ${from} → ${to}`,
    };
  }
  return { ok: true };
}

export const reservationMachine: StateMachine = {
  name: 'reservation',
  initial: 'draft',
  terminals: ['converted', 'cancelled', 'expired', 'rejected'],
  transitions: {
    draft: ['submitted', 'cancelled'],
    submitted: ['payment_pending', 'compliance_pending', 'rejected', 'cancelled'],
    payment_pending: ['payment_confirmed', 'cancelled', 'expired'],
    payment_confirmed: ['compliance_pending', 'cancelled'],
    compliance_pending: ['ready_for_contract', 'rejected', 'cancelled'],
    ready_for_contract: ['converted', 'cancelled'],
  },
};

export const contractMachine: StateMachine = {
  name: 'contract',
  initial: 'draft',
  terminals: ['active', 'rejected', 'cancelled', 'expired', 'terminated'],
  transitions: {
    draft: ['compliance_ready', 'cancelled'],
    compliance_ready: ['admin_approved', 'rejected', 'cancelled'],
    admin_approved: ['tenant_signature_pending', 'rejected', 'cancelled'],
    tenant_signature_pending: ['owner_signature_pending', 'cancelled', 'expired'],
    owner_signature_pending: ['final_review', 'cancelled', 'expired'],
    final_review: ['active', 'rejected', 'cancelled'],
    active: ['termination_pending'],
    termination_pending: ['terminated', 'active'],
  },
};

export const journalMachine: StateMachine = {
  name: 'journal_entry',
  initial: 'draft',
  terminals: ['posted', 'reversed'],
  transitions: {
    draft: ['posted', 'void'],
    posted: ['reversed'],
  },
};

export const maintenanceTicketMachine: StateMachine = {
  name: 'maintenance_ticket',
  initial: 'reported',
  terminals: ['closed', 'cancelled'],
  transitions: {
    reported: ['triaged', 'cancelled'],
    triaged: ['quote_requested', 'approval_pending', 'scheduled', 'cancelled'],
    quote_requested: ['approval_pending', 'cancelled'],
    approval_pending: ['approved', 'rejected', 'cancelled'],
    approved: ['scheduled', 'cancelled'],
    scheduled: ['in_progress', 'cancelled'],
    in_progress: ['work_completed', 'cancelled'],
    work_completed: ['verified', 'reopened'],
    verified: ['invoiced', 'closed'],
    invoiced: ['closed'],
    rejected: ['triaged', 'cancelled'],
    reopened: ['triaged', 'scheduled'],
  },
};

export const STATE_MACHINES = {
  reservation: reservationMachine,
  contract: contractMachine,
  journal_entry: journalMachine,
  maintenance_ticket: maintenanceTicketMachine,
} as const;

