return async (event: DomainEventJob) => {
  if (event.topic !== 'report.requested') return { ignored: true, topic: event.topic };
  if (!event.organizationId) {
    throw new PermanentJobError('REPORT_ORG_REQUIRED', 'Report jobs require organizationId');
  }
  const organizationId = event.organizationId;
  const report = await asWorker(pool, async (client) => {
    const result = await client.query<ReportJobRow>(
      `UPDATE report_jobs SET status = 'running', updated_at = now()
       WHERE id = $1 AND organization_id = $2 AND status IN ('queued','failed') RETURNING *`,
      [event.aggregateId, organizationId],
    );
    return result.rows[0];
  });
  if (!report) throw new PermanentJobError('REPORT_NOT_FOUND', 'Report job was not found');
  try {
    const definition = reportQueries[report.type];
    if (!definition)
      throw new PermanentJobError(
        'REPORT_TYPE_UNSUPPORTED',
        `Unsupported report: ${report.type}`,
      );
    const format = report.format as ReportFormat;
    if (!['csv', 'xlsx', 'pdf'].includes(format))
      throw new PermanentJobError('REPORT_FORMAT_UNSUPPORTED', `Unsupported format: ${format}`);
    const result = await asWorker(pool, (client) =>
      client.query<QueryResultRow>(definition.sql, [organizationId]),
    );
    const columns = result.fields.map((field) => field.name);
    const data: ReportData = {
      title: definition.title,
      columns,
      rows: result.rows.map((row) => columns.map((column) => row[column] as Cell)),
    };
    const objectKey = `reports/${organizationId}/${report.id}.${format}`;
    if (format === 'pdf') {
      await processPdf({
        documentId: report.id,
        documentType: 'report',
        html: toHtml(data),
        outputKey: objectKey,
        locale: 'ar',
        correlationId: event.eventId,
        organizationId,
      });
    } else if (format === 'xlsx') {
      await storage.putObject(objectKey, Buffer.from(toXlsx(data)), {
        contentType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
      });
    } else {
      await storage.putObject(objectKey, Buffer.from(toCsv(data), 'utf8'), {
        contentType: 'text/csv; charset=utf-8',
      });
    }
    await asWorker(pool, (client) =>
      client.query(
        `UPDATE report_jobs
         SET status = 'ready', object_key = $3, expires_at = now() + interval '7 days', updated_at = now()
         WHERE id = $1 AND organization_id = $2`,
        [report.id, organizationId, objectKey],
      ),
    );
    return { reportId: report.id, objectKey, organizationId };
  } catch (error) {
    await asWorker(pool, (client) =>
      client.query(
        `UPDATE report_jobs SET status = 'failed', updated_at = now()
         WHERE id = $1 AND organization_id = $2`,
        [report.id, organizationId],
      ),
    );
    throw error;
  }
};

