import { ConflictException } from '@nestjs/common';
import { and, count, eq, sql } from 'drizzle-orm';
import {
  assertWithinEntitlement,
  type EntitlementMetric,
  entitlementsForPlan,
} from '@bhd-r/domain';
import { organizations, properties, representationAuthorities, units } from '@bhd-r/db';
import type { DatabaseTransaction } from '../database/database.service.js';

export async function loadOrganizationPlan(
  transaction: DatabaseTransaction,
  organizationId: string,
) {
  const organization = await transaction.query.organizations.findFirst({
    where: eq(organizations.id, organizationId),
  });
  if (!organization) throw new ConflictException('Organization was not found');
  return organization;
}

async function countMetric(
  transaction: DatabaseTransaction,
  organizationId: string,
  metric: EntitlementMetric,
): Promise<number> {
  if (metric === 'properties') {
    const rows = await transaction
      .select({ value: count() })
      .from(properties)
      .where(
        and(eq(properties.organizationId, organizationId), sql`${properties.status} <> 'archived'`),
      );
    return Number(rows[0]?.value ?? 0);
  }
  if (metric === 'units') {
    const rows = await transaction
      .select({ value: count() })
      .from(units)
      .where(and(eq(units.organizationId, organizationId), sql`${units.status} <> 'archived'`));
    return Number(rows[0]?.value ?? 0);
  }
  if (metric === 'representatives') {
    const rows = await transaction
      .select({ value: count() })
      .from(representationAuthorities)
      .where(
        and(
          eq(representationAuthorities.organizationId, organizationId),
          eq(representationAuthorities.status, 'active'),
          sql`(${representationAuthorities.endsOn} IS NULL OR ${representationAuthorities.endsOn} >= CURRENT_DATE)`,
        ),
      );
    return Number(rows[0]?.value ?? 0);
  }
  return 0;
}

export async function assertOrganizationEntitlement(
  transaction: DatabaseTransaction,
  organizationId: string,
  metric: EntitlementMetric,
  requested = 1,
): Promise<void> {
  const organization = await loadOrganizationPlan(transaction, organizationId);
  const current = await countMetric(transaction, organizationId, metric);
  const decision = assertWithinEntitlement({
    planKey: organization.planKey,
    metric,
    current,
    requested,
  });
  if (!decision.ok) {
    const plan = entitlementsForPlan(organization.planKey);
    throw new ConflictException(
      `Plan ${plan.key} allows at most ${decision.limit} ${metric}; requested total would be ${decision.next}`,
    );
  }
}

import type { Metadata } from 'next';
import type { PublicPropertyDetail, PublicUnitDetail } from '@bhd-r/contracts';

export function publicWebOrigin(): string {
  return (
    process.env.PUBLIC_WEB_ORIGIN ??
    process.env.NEXT_PUBLIC_SITE_URL ??
    'https://r.bhd-om.com'
  ).replace(/\/$/, '');
}

/** Canonical + hreflang ar/en with x-default (Arabic preferred for Oman-first). */
export function bilingualAlternates(pathWithoutLocale: string): Metadata['alternates'] {
  const path = pathWithoutLocale.startsWith('/')
    ? pathWithoutLocale
    : `/${pathWithoutLocale}`;
  const normalized = path === '/' ? '' : path;
  return {
    canonical: normalized || '/',
    languages: {
      ar: `/ar${normalized}`,
      en: `/en${normalized}`,
      'x-default': `/ar${normalized}`,
    },
  };
}

function moneyMajor(amountMinor: string, currency: string): string {
  const fractionDigits: Record<string, number> = { OMR: 3, BHD: 3, KWD: 3 };
  const digits = fractionDigits[currency] ?? 2;
  const raw = amountMinor.padStart(digits + 1, '0');
  return `${raw.slice(0, -digits)}.${raw.slice(-digits)}`;
}

export function unitListingJsonLd(input: {
  locale: string;
  unit: PublicUnitDetail;
  title: string;
  description: string;
}) {
  const origin = publicWebOrigin();
  const url = `${origin}/${input.locale}/units/${input.unit.unitId}`;
  const propertiesUrl = `${origin}/${input.locale}/properties`;
  const homeUrl = `${origin}/${input.locale}`;
  const price = moneyMajor(input.unit.rent.amountMinor, input.unit.rent.currency);
  return {
    '@context': 'https://schema.org',
    '@graph': [
      {
        '@type': 'Organization',
        '@id': `${origin}/#organization`,
        name: 'BHD R',
        url: origin,
        areaServed: 'OM',
      },
      {
        '@type': 'BreadcrumbList',
        itemListElement: [
          { '@type': 'ListItem', position: 1, name: 'BHD R', item: homeUrl },
          {
            '@type': 'ListItem',
            position: 2,
            name: input.locale === 'ar' ? 'العقارات' : 'Properties',
            item: propertiesUrl,
          },
          { '@type': 'ListItem', position: 3, name: input.title, item: url },
        ],
      },
      {
        '@type': 'RealEstateListing',
        '@id': `${url}#listing`,
        name: input.title,
        description: input.description || undefined,
        url,
        datePosted: undefined,
        image: input.unit.images.map((item) => item.url),
        about: {
          '@type': 'Apartment',
          name: input.title,
          numberOfBedrooms: input.unit.bedrooms,
          numberOfBathroomsTotal: input.unit.bathrooms,
          floorSize: input.unit.areaSquareMeters
            ? {
                '@type': 'QuantitativeValue',
                value: input.unit.areaSquareMeters,
                unitCode: 'MTK',
              }
            : undefined,
          address: {
            '@type': 'PostalAddress',
            addressCountry: 'OM',
            addressRegion: input.unit.governorate,
            addressLocality: `${input.unit.wilayat}, ${input.unit.city}`,
          },
        },
        offers: {
          '@type': 'Offer',
          price,
          priceCurrency: input.unit.rent.currency,
          availability: 'https://schema.org/InStock',
          url,
          businessFunction:
            input.unit.listingPurpose === 'sale'
              ? 'https://schema.org/SellAction'
              : 'https://schema.org/LeaseOutAction',
        },
        provider: { '@id': `${origin}/#organization` },
      },
    ],
  };
}

export function propertyListingJsonLd(input: {
