export function bilingualAlternates(pathWithoutLocale: string): Metadata['alternates'] {
  const path = pathWithoutLocale.startsWith('/')
    ? pathWithoutLocale
    : `/${pathWithoutLocale}`;
  const normalized = path === '/' ? '' : path;
  return {
    canonical: normalized || '/',
    languages: {
      ar: `/ar${normalized}`,
      en: `/en${normalized}`,
      'x-default': `/ar${normalized}`,
    },
  };
}

