import 'server-only';
import { cookies, headers } from 'next/headers';
import { ApiError } from './api';

export { ApiError };

const DEFAULT_DEV_API = 'http://localhost:4000';
const FETCH_TIMEOUT_MS = 8_000;

function configuredApiOrigin(): string | null {
  const value = process.env.API_INTERNAL_ORIGIN ?? process.env.API_ORIGIN;
  return value?.trim() ? value.replace(/\/$/, '') : null;
}

function isLoopbackOrPrivate(origin: string): boolean {
  try {
    const url = new URL(origin);
    const host = url.hostname.toLowerCase();
    return (
      host === 'localhost' ||
      host === '127.0.0.1' ||
      host === '::1' ||
      host.endsWith('.local') ||
      host.endsWith('.internal')
    );
  } catch {
    return true;
  }
}

/** Prefer a reachable API. On Vercel, never block on localhost (hangs 20–70s). */
async function resolveApiOrigin(): Promise<string> {
  const configured = configuredApiOrigin();
  if (configured) {
    if (process.env.VERCEL && isLoopbackOrPrivate(configured)) {
      // Fall through to same-origin so missing Nest fails fast (404) instead of TCP hang.
    } else {
      return configured;
    }
  } else if (!process.env.VERCEL) {
    return DEFAULT_DEV_API;
  }

  const requestHeaders = await headers();
  const host = requestHeaders.get('x-forwarded-host') ?? requestHeaders.get('host');
  const proto = requestHeaders.get('x-forwarded-proto') ?? (process.env.VERCEL ? 'https' : 'http');
  if (host) return `${proto}://${host.split(',')[0]!.trim()}`;
  return DEFAULT_DEV_API;
}

function mergeSignal(init?: RequestInit): AbortSignal {
  const timeout = AbortSignal.timeout(FETCH_TIMEOUT_MS);
  if (!init?.signal) return timeout;
  return AbortSignal.any([init.signal, timeout]);
}

export async function apiFetch<T>(path: string, init: RequestInit = {}): Promise<T> {
  if (!path.startsWith('/')) throw new Error('API path must be absolute');
  const cookieStore = await cookies();
  const requestHeaders = await headers();
  const origin = await resolveApiOrigin();
  let response: Response;
  try {
    response = await fetch(`${origin}${path}`, {
      ...init,
      headers: {
        accept: 'application/json',
        cookie: cookieStore.toString(),
        'x-request-id': requestHeaders.get('x-request-id') ?? crypto.randomUUID(),
        ...init.headers,
      },
      cache: init.cache ?? 'no-store',
      signal: mergeSignal(init),
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'API unreachable';
    throw new ApiError(503, 'api_unreachable', message);
  }
  if (!response.ok) {
    const payload = (await response.json().catch(() => null)) as {
      error?: { code?: string; message?: string; requestId?: string };
    } | null;
    throw new ApiError(
      response.status,
      payload?.error?.code ?? 'api_error',
      payload?.error?.message ?? 'Request failed',
      payload?.error?.requestId,
    );
  }
  if (response.status === 204) return undefined as T;
  return response.json() as Promise<T>;
}

export async function publicApiFetch<T>(
  path: string,
  revalidate = 60,
  tags: string[] = ['public-listings'],
): Promise<T> {
  if (!path.startsWith('/')) throw new Error('API path must be absolute');
  const origin = await resolveApiOrigin();
  let response: Response;
  try {
    response = await fetch(`${origin}${path}`, {
      headers: { accept: 'application/json' },
      next: { revalidate, tags },
      signal: AbortSignal.timeout(FETCH_TIMEOUT_MS),
    });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'Public API unreachable';
    throw new ApiError(503, 'public_api_unreachable', message);
  }
  if (!response.ok)
    throw new ApiError(response.status, 'public_api_error', 'Public data is unavailable');
  return response.json() as Promise<T>;
}

import { cache } from 'react';
import { cookies } from 'next/headers';
import { eq } from 'drizzle-orm';
import { createDatabase, users, type Database } from '@bhd-r/db';
import { verifySessionToken } from '@bhd-r/authz';
import type { PortalRole, Viewer } from './types';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';

type DbHandle = { db: Database };

const globalForDb = globalThis as unknown as { __bhdRWebDb?: DbHandle };

function sessionSecret(): Uint8Array {
  return new TextEncoder().encode(
    process.env.BHD_R_SESSION_SECRET ?? 'development-session-secret-at-least-32-characters',
  );
}

function portalsForRoles(roles: readonly string[]): PortalRole[] {
  const portalSet = new Set<PortalRole>();
  if (roles.some((role) => role === 'platform_admin' || role === 'platform_support'))
    portalSet.add('platform');
  if (roles.includes('developer_admin')) portalSet.add('developer');
  if (roles.includes('tenant')) portalSet.add('tenant');
  if (
    roles.some((role) =>
      [
        'organization_owner',
        'organization_admin',
        'property_manager',
        'finance_manager',
        'maintenance_agent',
        'auditor',
      ].includes(role),
    )
  )
    portalSet.add('owner');
  return [...portalSet];
}

function getSharedDatabase(): DbHandle {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL is required');
  if (!globalForDb.__bhdRWebDb) {
    const { db } = createDatabase(url, { max: 1 });
    globalForDb.__bhdRWebDb = { db };
  }
  return globalForDb.__bhdRWebDb;
}

async function getViewerFromDatabase(): Promise<Viewer | null> {
  const cookieStore = await cookies();
  const token = cookieStore.get('bhd_r_session')?.value;
  if (!token) return null;
  try {
    const claims = await verifySessionToken(token, sessionSecret());
    const { db } = getSharedDatabase();
    const user = await db.query.users.findFirst({
      where: eq(users.id, claims.sub),
      columns: {
        id: true,
        username: true,
        email: true,
        displayName: true,
        locale: true,
        disabledAt: true,
        sessionVersion: true,
      },
    });
    if (!user || user.disabledAt || user.sessionVersion !== claims.sessionVersion) return null;
    return {
      id: user.id,
      username: user.username,
      email: user.email,
      displayName: user.displayName,
      partyId: claims.partyId,
      locale: user.locale === 'en' ? 'en' : 'ar',
      organizationId: claims.organizationId,
      roles: claims.roles,
      permissions: claims.permissions,
      portals: portalsForRoles(claims.roles),
    };
  } catch {
    return null;
  }
}

/** One viewer resolution per RSC request (layout + page share the result). */
export const getViewer = cache(async (): Promise<Viewer | null> => {
  if (hasDatabaseUrl()) return getViewerFromDatabase();

  const { ApiError, apiFetch } = await import('./server-api');
  try {
    const user = await apiFetch<Omit<Viewer, 'portals'> & { portals?: PortalRole[] }>('/v1/me');
    return { ...user, portals: portalsForRoles(user.roles) };
  } catch (error) {
    if (error instanceof ApiError && error.status === 401) return null;
    throw error;
  }
});

export async function requirePortal(locale: string, portal: PortalRole): Promise<Viewer> {
  const { redirect } = await import('next/navigation');
  const viewer = await getViewer();
  if (viewer === null) {
    redirect(`/${locale}/login`);
    throw new Error('unreachable');
  }
  if (!viewer.portals.includes(portal)) {
    redirect(`/${locale}/portal?denied=${portal}`);
    throw new Error('unreachable');
  }
  return viewer;
}

