async function advance(row: DataRow) {
  const action = nextAction(section, row);
  if (!action) return;
  setBusy(true);
  setError(null);
  try {
    await browserMutation(action.path, {
      method: action.method,
      body: JSON.stringify(action.body),
    });
    router.refresh();
  } catch (caught) {
    setError(caught instanceof Error ? caught.message : 'request_failed');
  } finally {
    setBusy(false);
  }
}

async function leaseLifecycle(row: DataRow, action: 'activate' | 'end' | 'terminate') {
  const id = safeString(row.id);
  if (!id) return;
  setBusy(true);
  setError(null);
  try {
    await browserMutation(`/v1/leasing/leases/${id}`, {
      method: 'PATCH',
      body: JSON.stringify({ action }),
    });
    router.refresh();
  } catch (caught) {
    setError(caught instanceof Error ? caught.message : 'request_failed');
  } finally {
    setBusy(false);
  }
}

