];

function roleTone(
  role: NodeDef['role'],
): 'neutral' | 'info' | 'success' | 'warning' | 'danger' {
  switch (role) {
    case 'setup':
      return 'neutral';
    case 'ops':
      return 'info';
    case 'finance':
      return 'warning';
    case 'legal':
      return 'info';
    case 'active':
      return 'success';
    case 'exit':
      return 'danger';
    case 'loop':
      return 'warning';
  }
}

function FlowDag({
  nodes,
  edges,
  lang,
}: {
  nodes: NodeDef[];
  edges: Array<{ from: string; to: string }>;
  lang: 'ar' | 'en';
}) {
  const theme = useHostTheme();
  const layout = useMemo(
    () =>
      computeDAGLayout({
        nodes: nodes.map((n) => ({ id: n.id })),
        edges,
        direction: 'vertical',
        nodeWidth: 168,
        nodeHeight: 52,
        rankGap: 56,
        nodeGap: 28,
        padding: 16,
      }),
    [nodes, edges],
  );

  const byId = useMemo(() => new Map(nodes.map((n) => [n.id, n])), [nodes]);
  const pos = useMemo(() => new Map(layout.nodes.map((n) => [n.id, n])), [layout.nodes]);

  return (
    <div
      style={{
        width: '100%',
        overflowX: 'auto',
        border: `1px solid ${theme.stroke.secondary}`,
        borderRadius: 8,
        background: theme.surface.secondary,
      }}
    >
      <svg width={layout.width} height={layout.height} style={{ display: 'block' }}>
        {layout.edges.map((edge: DAGLayoutEdge, i: number) => (
          <line
            key={`${edge.from}-${edge.to}-${i}`}
            x1={edge.sourceX}
            y1={edge.sourceY}
            x2={edge.targetX}
            y2={edge.targetY}
            stroke={edge.isBackEdge ? theme.stroke.warning : theme.stroke.primary}
            strokeWidth={edge.isBackEdge ? 1.5 : 1.25}
            strokeDasharray={edge.isBackEdge ? '5 4' : undefined}
            opacity={0.85}
          />
        ))}
        {layout.nodes.map((node: DAGLayoutNode) => {
          const def = byId.get(node.id)!;
          const tone = roleTone(def.role);
          const fill =
            tone === 'success'
              ? theme.fill.success
              : tone === 'warning'
                ? theme.fill.warning
                : tone === 'danger'
                  ? theme.fill.danger
                  : tone === 'info'
                    ? theme.fill.info
                    : theme.fill.tertiary;
          const stroke =
            tone === 'success'
              ? theme.stroke.success
              : tone === 'warning'
                ? theme.stroke.warning
                : tone === 'danger'
                  ? theme.stroke.danger
                  : tone === 'info'
                    ? theme.stroke.info
                    : theme.stroke.secondary;
          return (
            <g key={node.id} transform={`translate(${node.x},${node.y})`}>
              <rect
                width={168}
                height={52}
                rx={8}
                fill={fill}
                stroke={stroke}
                strokeWidth={1}
              />
              <text
                x={84}
                y={22}
                textAnchor="middle"
                fill={theme.text.primary}
                fontSize={11}
                fontWeight={600}
              >
                {lang === 'ar' ? def.ar : def.en}
              </text>
              <text
                x={84}
                y={38}
                textAnchor="middle"
                fill={theme.text.secondary}
                fontSize={10}
              >
                {lang === 'ar' ? def.en : def.ar}
              </text>
            </g>
          );
        })}
        {/* silence unused */}
        {pos.size === 0 ? null : null}
      </svg>
    </div>
  );
}

