export default function TransactionFlowMapCanvas() {
  const theme = useHostTheme();
  const [mode, setMode] = useState<Mode>('lease');
  const [lang, setLang] = useState<'ar' | 'en'>('ar');

  const activeNodes = mode === 'sale' ? SALE_NODES : mode === 'cycle' ? CYCLE_NODES : LEASE_NODES;
  const activeEdges = mode === 'sale' ? SALE_EDGES : mode === 'cycle' ? CYCLE_EDGES : LEASE_EDGES;

  return (
    <Stack gap={20} style={{ padding: 20, direction: 'rtl' }}>
      <Stack gap={6}>
        <H1>خارطة مسار المعاملة — BHD-R</H1>
        <Text tone="secondary">
          مصدر السلوك: تدفق BHD-OM المنقول إلى BHD-R (خطوات 1–19). للمراجعة والتصحيح.
        </Text>
        <Text tone="secondary" size="small">
          Source: docs/implementation + leasing/operations services · 2026-08-25
        </Text>
      </Stack>

      <Row gap={12} wrap>
        <Stat value="إيجار" label="مسار أساسي كامل" tone="info" />
        <Stat value="بيع" label="مسار مبيعات منفصل" tone="warning" />
        <Stat value="حلقة" label="شاغر ↔ مؤجّر" tone="success" />
      </Row>

      <Row gap={12} wrap align="center">
        <Text weight="semibold">العرض</Text>
        <Select
          value={mode}
          onChange={(v) => setMode(v as Mode)}
          options={[
            { value: 'lease', label: 'مسار الإيجار الكامل' },
            { value: 'sale', label: 'مسار البيع' },
            { value: 'cycle', label: 'حلقة الشغور / إعادة التأجير' },
          ]}
        />
        <Select
          value={lang}
          onChange={(v) => setLang(v as 'ar' | 'en')}
          options={[
            { value: 'ar', label: 'تسمية عربية أولاً' },
            { value: 'en', label: 'English labels first' },
          ]}
        />
      </Row>

      <Callout tone="info" title="كيف تقرأ المخطط">
        الأسهم المتقطعة = عودة/حلقة (مثل التجديد أو العودة للشاغر). الألوان: رمادي إعداد، أزرق
        عمليات، كهرماني مالية، أخضر ساري، أحمر خروج.
      </Callout>

      <Card>
        <CardHeader
          trailing={
            <Pill tone={mode === 'lease' ? 'info' : mode === 'sale' ? 'warning' : 'success'}>
              {mode === 'lease' ? 'إيجار' : mode === 'sale' ? 'بيع' : 'حلقة'}
            </Pill>
          }
        >
          {mode === 'lease'
            ? 'من تخزين العقار حتى إنهاء التعاقد وإعادة التأجير'
            : mode === 'sale'
              ? 'مسار صفقة البيع (sales_deals)'
              : 'دورة حياة الوحدة: شاغر → إيجار → خروج → شاغر'}
        </CardHeader>
        <CardBody>
          <FlowDag nodes={activeNodes} edges={activeEdges} lang={lang} />
        </CardBody>
      </Card>

      <Divider />

      <H2>حالات الإيجار (كما في النظام)</H2>
      <Table
        headers={['المرحلة', 'الحالة / الكود', 'المسؤول']}
        rows={LEASE_STATUS_ROWS.map((r) => [r.stage, r.code, r.who])}
      />

      <H2>حالات البيع (كما في النظام)</H2>
      <Table
        headers={['المرحلة', 'الحالة / الكود', 'المسؤول']}
        rows={SALE_STATUS_ROWS.map((r) => [r.stage, r.code, r.who])}
      />

      <Divider />

      <H2>نقاط للمراجعة والتصحيح</H2>
      <Text tone="secondary">
        راجع هذه النقاط وأخبرني بما تريد تعديله في المنتج أو في المخطط.
      </Text>
      <Spacer height={8} />
      <Stack gap={8}>
        {GAPS.map((g) => (
          <Card key={g.id}>
            <CardBody>
              <Row gap={10} align="center">
                <Pill
                  tone={
                    g.severity === 'حرج للتشغيل'
                      ? 'danger'
                      : g.severity === 'نقص محتمل'
                        ? 'warning'
                        : 'neutral'
                  }
                >
                  {g.id}
                </Pill>
                <Text weight="semibold">{g.severity}</Text>
              </Row>
              <Spacer height={6} />
              <Text>{g.ar}</Text>
            </CardBody>
          </Card>
        ))}
      </Stack>

      <Divider />

      <H3>ملخص سريع بالكلمات</H3>
      <Stack gap={6}>
        <Text>
          <Text as="span" weight="semibold">
            إيجار:{' '}
          </Text>
          سجل عناوين → عقار/وحدات → شاغر → حجز معلّق → تأكيد عربون (قيد) → عقد قيد الإجراء
          (اعتمادات/شيكات/توقيع) → ساري → تجديد أو إنهاء/فسخ → متابعة شغور → شاغر مرة أخرى.
        </Text>
        <Text>
          <Text as="span" weight="semibold">
            بيع:{' '}
          </Text>
          سجل عناوين → عقار للبيع → lead → مؤهل → معاينة → عرض/تفاوض → محجوز → تعاقد → closed_won
          (أو خسارة/إلغاء في أي مرحلة تقريباً).
        </Text>
      </Stack>

      <Callout tone="warning" title="طلب منك">
        صحّح أي مرحلة ناقصة أو ترتيب خاطئ (خصوصاً البيع بعد الإغلاق، والتجديد، ومخالصات التأمين).
        سأحدّث المخطط والكود وفق ملاحظاتك.
      </Callout>
    </Stack>
  );
}

