  error,
  requiredLabel,
  tone,
  id,
  className = '',
  children,
  ...props
}: SelectHTMLAttributes<HTMLSelectElement> & FieldBase & { id: string }) {
  return (
    <FieldFrame
      id={id}
      label={label}
      {...(hint === undefined ? {} : { hint })}
      {...(error === undefined ? {} : { error })}
      {...(props.required === undefined ? {} : { required: props.required })}
      {...(requiredLabel === undefined ? {} : { requiredLabel })}
      {...(tone === undefined ? {} : { tone })}
