.form-shell {
  max-width: 64rem;
}
.wizard-shell {
  max-width: min(72rem, 100%);
}
.wizard-steps {
  display: grid;
  grid-template-columns: repeat(6, minmax(0, 1fr));
  gap: 0.55rem;
  margin: 0 0 1.25rem;
  padding: 0;
  list-style: none;
}
.wizard-steps__btn {
  width: 100%;
  display: grid;
  gap: 0.35rem;
  justify-items: center;
  min-height: 4.4rem;
  padding: 0.65rem 0.4rem;
  color: var(--ink-700);
  background: white;
  border: 1px solid rgb(9 45 36 / 0.12);
  border-radius: 0.9rem;
  cursor: pointer;
  transition:
    transform 0.16s ease,
    border-color 0.16s ease,
    background 0.16s ease,
    box-shadow 0.16s ease;
}
.wizard-steps__btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
}
.wizard-steps__btn:not(:disabled):hover {
  transform: translateY(-1px);
  border-color: rgb(8 163 159 / 0.35);
}
.wizard-steps__btn.is-current {
  color: white;
  background: linear-gradient(145deg, #0b3a2f, #174b70);
  border-color: transparent;
  box-shadow: 0 12px 28px rgb(9 45 36 / 0.16);
}
.wizard-steps__btn.is-done {
  color: var(--oman-deep);
  background: rgb(22 115 75 / 0.08);
  border-color: rgb(22 115 75 / 0.35);
}
.wizard-steps__num {
  display: grid;
  place-content: center;
  width: 1.85rem;
  height: 1.85rem;
  color: inherit;
  background: rgb(9 45 36 / 0.06);
  border-radius: 50%;
  font-weight: 800;
  font-size: 0.85rem;
}
.wizard-steps__btn.is-current .wizard-steps__num {
  background: rgb(255 255 255 / 0.18);
