import {
  ForbiddenException,
  Injectable,
  type CanActivate,
  type ExecutionContext,
} from '@nestjs/common';
import type { FastifyRequest } from 'fastify';
import { verifyCsrfToken } from '@bhd-r/security';
import { isAllowedWebOrigin } from './web-origins.js';

const safeMethods = new Set(['GET', 'HEAD', 'OPTIONS']);
const trustedFetchSites = new Set(['same-origin', 'same-site', 'none']);

@Injectable()
export class CsrfGuard implements CanActivate {
  canActivate(context: ExecutionContext): boolean {
    const request = context.switchToHttp().getRequest<FastifyRequest>();
    if (safeMethods.has(request.method) || request.auth?.authenticationMethod !== 'session')
      return true;

    const fetchSite = request.headers['sec-fetch-site'];
    const origin = request.headers.origin;

    // Browser → Next (same-origin) rewritten/proxied to Nest: trust Fetch Metadata.
    // Cross-site browser calls still require an allowlisted Origin.
    if (typeof fetchSite === 'string' && fetchSite === 'cross-site') {
      throw new ForbiddenException('Cross-site request rejected');
    }
    if (
      typeof fetchSite === 'string' &&
      !trustedFetchSites.has(fetchSite) &&
      fetchSite !== 'cross-site'
    ) {
      throw new ForbiddenException('Cross-site request rejected');
    }
    if (
      (typeof fetchSite !== 'string' || fetchSite === 'none') &&
      typeof origin === 'string' &&
      !isAllowedWebOrigin(origin)
    ) {
      throw new ForbiddenException('Cross-site request rejected');
    }
    if (
      typeof fetchSite !== 'string' &&
      typeof origin === 'string' &&
      !isAllowedWebOrigin(origin)
    ) {
      throw new ForbiddenException('Cross-site request rejected');
    }

    const header = request.headers['x-csrf-token'];
    const cookie = request.cookies?.bhd_r_csrf;
    if (
      typeof header !== 'string' ||
      header !== cookie ||
      !request.auth ||
      !verifyCsrfToken(
        header,
        request.auth.sid,
        process.env.CSRF_SECRET ?? 'development-csrf-secret-must-be-at-least-32-chars',
      )
    ) {
      throw new ForbiddenException('CSRF validation failed');
    }
    return true;
  }
}

