useEffect(() => {
  if (!open || !mapNode.current || mapRef.current) return;
  let cancelled = false;

  void (async () => {
    const L = (await import('leaflet')).default;
    await import('leaflet/dist/leaflet.css');
    if (cancelled || !mapNode.current) return;

    const start = initial ?? MUSCAT;
    const map = L.map(mapNode.current, {
      center: [start.latitude, start.longitude],
      zoom: initial ? 16 : 12,
      scrollWheelZoom: true,
    });
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; OpenStreetMap',
      maxZoom: 19,
    }).addTo(map);

    const pin = L.divIcon({
      className: 'map-picker__pin',
      html: '<span></span>',
      iconSize: [28, 28],
      iconAnchor: [14, 28],
    });
    const marker = L.marker([start.latitude, start.longitude], {
      draggable: true,
      icon: pin,
    }).addTo(map);

    const publish = (latitude: number, longitude: number) => {
      setDraft({ latitude, longitude });
    };

    marker.on('dragend', () => {
      const pos = marker.getLatLng();
      publish(pos.lat, pos.lng);
    });
    map.on('click', (event: { latlng: { lat: number; lng: number } }) => {
      marker.setLatLng(event.latlng);
      publish(event.latlng.lat, event.latlng.lng);
    });

    mapRef.current = map;
    markerRef.current = marker;
    publish(start.latitude, start.longitude);
    requestAnimationFrame(() => map.invalidateSize());
  })();

  return () => {
    cancelled = true;
    mapRef.current?.remove();
    mapRef.current = null;
    markerRef.current = null;
  };
}, [open, initial]);

