      ? transaction
          .select({ value: count() })
          .from(invoices)
          .innerJoin(leases, eq(invoices.leaseId, leases.id))
          .where(openInvoiceFilter)
      : transaction.select({ value: count() }).from(invoices).where(openInvoiceFilter);

