'use client';

import { useRouter } from '@/i18n/navigation';
import { useEffect, useRef } from 'react';
import type { PortalRole } from '@/lib/types';
import { portalNavHrefs } from '@/lib/portal-nav-paths';

/**
 * WAZEN-style idle prefetch: warm portal section RSC payloads in the client router cache
 * so sidebar clicks feel like returning to an already-open view.
 */
export function PortalRoutePrefetch({ portal }: { portal: PortalRole }) {
  const router = useRouter();
  const started = useRef(false);

  useEffect(() => {
    if (started.current) return;
    started.current = true;
    const hrefs = portalNavHrefs(portal);
    let cancelled = false;
    const timers: number[] = [];

    const run = () => {
      hrefs.forEach((href, index) => {
        timers.push(
          window.setTimeout(() => {
            if (cancelled) return;
            try {
              router.prefetch(href);
            } catch {
              /* ignore */
            }
          }, 180 + index * 120),
        );
      });
    };

    const idle =
      typeof window.requestIdleCallback === 'function'
        ? window.requestIdleCallback(() => run(), { timeout: 2_500 })
        : window.setTimeout(run, 600);

    return () => {
      cancelled = true;
      if (typeof window.cancelIdleCallback === 'function' && typeof idle === 'number') {
        try {
          window.cancelIdleCallback(idle as number);
        } catch {
          /* ignore */
        }
      } else {
        window.clearTimeout(idle as number);
      }
      timers.forEach((id) => window.clearTimeout(id));
    };
  }, [portal, router]);

  return null;
}

