      'content-type',
      'authorization',
      'x-api-key',
      'x-csrf-token',
      'x-organization-id',
      'idempotency-key',
      'x-request-id',
      'x-requested-with',
    ],
  });
  app.enableShutdownHooks();

  await app.listen(nestPort, '127.0.0.1');
  nestReady = true;
  console.log(`BHD-R API Nest listening on 127.0.0.1:${nestPort} (public ${publicPort})`);

