    ],
  });
  app.enableShutdownHooks();

  await app.init();
  nestHandler = server as unknown as (req: IncomingMessage, res: ServerResponse) => void;

  console.log(`BHD-R API Nest Express ready (public ${publicPort}, no Fastify listen)`);

  try {
    const ping = await fetch(`http://127.0.0.1:${publicPort}/raw-ping`, {
