import {
  Catch,
  HttpException,
  HttpStatus,
  type ArgumentsHost,
  type ExceptionFilter,
} from '@nestjs/common';
import type { ApiRequest, ApiResponse } from './api-http.js';
import { requestIdOf } from './http-request.js';

@Catch()
export class HttpExceptionFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost): void {
    const http = host.switchToHttp();
    const request = http.getRequest<ApiRequest>();
    const reply = http.getResponse<ApiResponse>();
    const status =
      exception instanceof HttpException ? exception.getStatus() : HttpStatus.INTERNAL_SERVER_ERROR;
    const response = exception instanceof HttpException ? exception.getResponse() : undefined;
    const code =
      typeof response === 'object' && response && 'code' in response
        ? String(response.code)
        : status === 500
          ? 'INTERNAL_ERROR'
          : 'REQUEST_FAILED';
    const message =
      typeof response === 'string'
        ? response
        : typeof response === 'object' && response && 'message' in response
          ? String(response.message)
          : status === 500
            ? 'An unexpected error occurred'
            : 'Request failed';
    reply.status(status).json({
      error: {
        code,
        message,
        requestId: requestIdOf(request),
        ...(status < 500 && typeof response === 'object' ? { details: response } : {}),
      },
    });
  }
}

import {
  ConflictException,
  Injectable,
  UnprocessableEntityException,
  type CallHandler,
  type ExecutionContext,
  type NestInterceptor,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { Observable, catchError, from, mergeMap, of, throwError } from 'rxjs';
import { createHash } from 'node:crypto';
import { and, eq, lt } from 'drizzle-orm';
import { idempotencyKeys } from '@bhd-r/db';
import { idempotencyKeySchema } from '@bhd-r/contracts';
import type { ApiRequest, ApiResponse, AuthClaims } from './api-http.js';
import { IDEMPOTENT_ROUTE } from './decorators.js';
import { requestRoutePath } from './http-request.js';
import { DatabaseService } from '../database/database.service.js';

function stable(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(stable).join(',')}]`;
  if (value && typeof value === 'object')
    return `{${Object.entries(value)
      .sort(([a], [b]) => a.localeCompare(b))
      .map(([key, child]) => `${JSON.stringify(key)}:${stable(child)}`)
      .join(',')}}`;
  return JSON.stringify(value);
}

@Injectable()
export class IdempotencyInterceptor implements NestInterceptor {
  constructor(
    private readonly reflector: Reflector,
    private readonly database: DatabaseService,
  ) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    if (
      !this.reflector.getAllAndOverride<boolean>(IDEMPOTENT_ROUTE, [
        context.getHandler(),
        context.getClass(),
      ])
    )
      return next.handle();
    const request = context.switchToHttp().getRequest<ApiRequest>();
    const reply = context.switchToHttp().getResponse<ApiResponse>();
    const keyResult = idempotencyKeySchema.safeParse(request.headers['idempotency-key']);
    if (!keyResult.success)
      throw new UnprocessableEntityException('A valid Idempotency-Key is required');
    if (!request.auth?.organizationId)
      throw new UnprocessableEntityException('Organization context is required');
    const key = keyResult.data;
    const route = `${request.method}:${requestRoutePath(request)}`;
    const requestHash = createHash('sha256').update(stable(request.body)).digest('hex');

    return from(this.claim(request.auth, key, route, requestHash)).pipe(
      mergeMap((claimed) => {
        if (claimed.kind === 'replay') {
          reply.status(claimed.status);
          reply.setHeader('Idempotency-Replayed', 'true');
          return of(claimed.body);
        }
        return next.handle().pipe(
          mergeMap((body) =>
            from(this.complete(request.auth!, key, route, reply.statusCode, body)).pipe(
              mergeMap(() => of(body)),
            ),
          ),
          catchError((error: unknown) =>
            from(this.release(request.auth!, key, route, requestHash)).pipe(
              mergeMap(() => throwError(() => error)),
            ),
          ),
        );
      }),
    );
  }

  private async claim(
    claims: AuthClaims,
    key: string,
    route: string,
    requestHash: string,
  ): Promise<{ kind: 'new' } | { kind: 'replay'; status: number; body: unknown }> {
    return this.database.withinTenant(claims, async (transaction) => {
      const now = new Date();
      const inserted = await transaction
        .insert(idempotencyKeys)
        .values({
          organizationId: claims.organizationId!,
          key,
          route,
          requestHash,
          lockedUntil: new Date(now.getTime() + 30_000),
          expiresAt: new Date(now.getTime() + 86_400_000),
        })
        .onConflictDoNothing()
        .returning();
      if (inserted.length > 0) return { kind: 'new' };
      const existing = await transaction.query.idempotencyKeys.findFirst({
        where: and(
          eq(idempotencyKeys.organizationId, claims.organizationId!),
          eq(idempotencyKeys.key, key),
          eq(idempotencyKeys.route, route),
        ),
      });
      if (!existing || existing.requestHash !== requestHash)
        throw new UnprocessableEntityException('Idempotency key was used with another payload');
      if (existing.responseStatus !== null)
        return { kind: 'replay', status: existing.responseStatus, body: existing.responseBody };
      if (existing.lockedUntil <= now) {
        const reclaimed = await transaction
          .update(idempotencyKeys)
          .set({ lockedUntil: new Date(now.getTime() + 30_000) })
          .where(
            and(
              eq(idempotencyKeys.organizationId, claims.organizationId!),
              eq(idempotencyKeys.key, key),
              eq(idempotencyKeys.route, route),
              eq(idempotencyKeys.requestHash, requestHash),
              lt(idempotencyKeys.lockedUntil, now),
            ),
          )
          .returning({ key: idempotencyKeys.key });
        if (reclaimed.length > 0) return { kind: 'new' };
      }
      throw new ConflictException('An equivalent request is still being processed');
    });
  }

  private async complete(
    claims: AuthClaims,
    key: string,
    route: string,
    status: number,
    body: unknown,
  ): Promise<void> {
    await this.database.withinTenant(claims, async (transaction) => {
      await transaction
        .update(idempotencyKeys)
        .set({ responseStatus: status, responseBody: body })
        .where(
          and(
            eq(idempotencyKeys.organizationId, claims.organizationId!),
            eq(idempotencyKeys.key, key),
            eq(idempotencyKeys.route, route),
          ),
        );
    });
  }

  private async release(
    claims: AuthClaims,
    key: string,
    route: string,
    requestHash: string,
  ): Promise<void> {
    await this.database.withinTenant(claims, async (transaction) => {
      await transaction
        .delete(idempotencyKeys)
        .where(
          and(
            eq(idempotencyKeys.organizationId, claims.organizationId!),
            eq(idempotencyKeys.key, key),
            eq(idempotencyKeys.route, route),
            eq(idempotencyKeys.requestHash, requestHash),
          ),
        );
    });
  }
}

import {
  Injectable,
  Logger,
  type CallHandler,
  type ExecutionContext,
  type NestInterceptor,
} from '@nestjs/common';
import { Observable, tap } from 'rxjs';
import { createAuditRecord } from '@bhd-r/observability';
import { auditLogs } from '@bhd-r/db';
import { DatabaseService } from '../database/database.service.js';
import { createHash } from 'node:crypto';
import type { ApiRequest } from './api-http.js';
import { requestIdOf, requestRoutePath } from './http-request.js';

const sensitiveAuditField =
  /(?:password|passphrase|secret|token|authorization|cookie|credential|api[-_]?key|totp|signature|card|cvv|national[-_]?id|civil[-_]?id|registration[-_]?number)/i;

export function auditChangedFields(body: unknown): string[] {
  if (!body || typeof body !== 'object' || Array.isArray(body)) return [];
  return Object.keys(body)
    .filter((field) => !sensitiveAuditField.test(field))
    .slice(0, 50);
}

@Injectable()
export class AuditInterceptor implements NestInterceptor {
  readonly #logger = new Logger(AuditInterceptor.name);
  constructor(private readonly database: DatabaseService) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<unknown> {
    const request = context.switchToHttp().getRequest<ApiRequest>();
    if (['GET', 'HEAD', 'OPTIONS'].includes(request.method)) return next.handle();
    const started = Date.now();
    return next.handle().pipe(
      tap({
        next: () => void this.record(request, 'succeeded', started),
        error: () => void this.record(request, 'failed', started),
      }),
    );
  }

  private async record(request: ApiRequest, outcome: string, started: number): Promise<void> {
    try {
      const path = requestRoutePath(request);
      const record = createAuditRecord({
        action: `${request.method} ${path}`,
        actorId: request.auth?.sub ?? null,
        organizationId: request.auth?.organizationId ?? null,
        resourceType: path.split('/')[2] ?? 'api',
        resourceId:
          typeof (request.params as Record<string, unknown> | undefined)?.id === 'string'
            ? String((request.params as Record<string, unknown>).id)
            : null,
        requestId: requestIdOf(request),
        ipHash: createHash('sha256').update(request.ip ?? '').digest('hex'),
        metadata: {
          outcome,
          durationMs: Date.now() - started,
          requiredPermissions: request.requiredPermissions,
          changedFields: auditChangedFields(request.body),
        },
      });
      await this.database.asSystem(async (transaction) => {
        await transaction
          .insert(auditLogs)
          .values({
            organizationId: record.organizationId,
            actorUserId: record.actorId,
            action: record.action,
            resourceType: record.resourceType,
            resourceId: record.resourceId,
            requestId: record.requestId,
            ipHash: record.ipHash,
            metadata: record.metadata,
            occurredAt: new Date(record.occurredAt),
          })
          .onConflictDoNothing();
      });
    } catch (error) {
      this.#logger.error(
        `Unable to persist audit record (${error instanceof Error ? error.name : 'UnknownError'})`,
      );
    }
  }
}

