import 'server-only';
import { and, eq, ne, sql } from 'drizzle-orm';
import {
  addresses,
  createDatabase,
  parties,
  properties,
  type Database,
} from '@bhd-r/db';

type DbHandle = { db: Database };
const globalForDb = globalThis as unknown as { __bhdRPropertyWriteDb?: DbHandle };

function getDatabase(): DbHandle {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL is required');
  if (!globalForDb.__bhdRPropertyWriteDb) {
    const { db } = createDatabase(url, { max: 2 });
    globalForDb.__bhdRPropertyWriteDb = { db };
  }
  return globalForDb.__bhdRPropertyWriteDb;
}

export type OwnerPartyOption = {
  id: string;
  displayName: string;
  type: string;
};

/** Parties in the org that can be recorded as property owners. */
export async function listOwnerPartyOptions(
  organizationId: string,
): Promise<OwnerPartyOption[]> {
  const { db } = getDatabase();
  const rows = await db
    .select({
      id: parties.id,
      displayName: parties.displayName,
      type: parties.type,
    })
    .from(parties)
    .where(and(eq(parties.organizationId, organizationId), eq(parties.status, 'active')))
    .orderBy(parties.displayName);
  return rows;
}

export async function loadPropertyForEdit(
  organizationId: string,
  propertyId: string,
): Promise<Record<string, unknown> | null> {
  const { db } = getDatabase();
  return db.transaction(async (transaction) => {
    await transaction.execute(
      sql`select set_config('app.organization_id', ${organizationId}, true)`,
    );
    await transaction.execute(sql`select set_config('app.platform_admin', 'false', true)`);
    await transaction.execute(sql`select set_config('app.public', 'false', true)`);
    await transaction.execute(sql`select set_config('app.is_tenant', 'false', true)`);

    const property = await transaction.query.properties.findFirst({
      where: and(
        eq(properties.id, propertyId),
        eq(properties.organizationId, organizationId),
        ne(properties.status, 'archived'),
      ),
    });
    if (!property) return null;

    const [address, profile, amenities, meters, documents, unitRows] = await Promise.all([
      transaction.query.addresses.findFirst({ where: eq(addresses.id, property.addressId) }),
      transaction.query.propertyProfiles.findFirst({
        where: eq(
          // lazy import avoided — use drizzle relation via query
          (await import('@bhd-r/db')).propertyProfiles.propertyId,
          property.id,
        ),
      }),
      transaction.query.propertyAmenities.findMany({
        where: eq((await import('@bhd-r/db')).propertyAmenities.propertyId, property.id),
      }),
      transaction.query.utilityMeters.findMany({
        where: eq((await import('@bhd-r/db')).utilityMeters.propertyId, property.id),
      }),
      transaction.query.propertyDocuments.findMany({
        where: eq((await import('@bhd-r/db')).propertyDocuments.propertyId, property.id),
      }),
      transaction.query.units.findMany({
        where: eq((await import('@bhd-r/db')).units.propertyId, property.id),
      }),
    ]);

    return {
      ...property,
      rentMinor: undefined,
      address,
      profile: profile
        ? {
            ...profile,
            managementFeeMinor: profile.managementFeeMinor?.toString() ?? null,
          }
        : null,
      amenities,
      meters,
      documents,
      units: unitRows.map((unit) => ({
        ...unit,
        rentMinor: unit.rentMinor.toString(),
        salePriceMinor: unit.salePriceMinor?.toString() ?? null,
        depositMinor: unit.depositMinor?.toString() ?? null,
      })),
    };
  });
}

