  const digits = minor.padStart(places + 1, '0');
  if (places === 0) return digits;
  return `${digits.slice(0, -places)}.${digits.slice(-places)}`.replace(/\.?0+$/, (m) =>
    m.includes('.') ? m.replace(/0+$/, '').replace(/\.$/, '') : m,
  );
}

