import { readFileSync } from 'node:fs';
import { createRequire } from 'node:module';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const require = createRequire(path.join(root, 'packages/db/package.json'));
const postgres = require('postgres');

const raw = readFileSync(path.join(root, '.env.neon'), 'utf8');
const line = raw.split(/\r?\n/).find((l) => l.startsWith('DATABASE_URL='[REDACTED-DATABASE-URL]
const url = line?.slice('DATABASE_URL='[REDACTED-DATABASE-URL]"']|["']$/g, '');
if (!url) process.exit(1);

const sql = postgres(url, { max: 1, prepare: false, ssl: 'require' });

try {
  const rows = await sql`
    select p.id, p.name_ar, p.serial_number, p.created_at, p.status
    from properties p
    where p.status <> 'archived'
    order by p.created_at asc
  `;
  console.log(
    'active',
    rows.map((r) => ({
      id: r.id,
      name: r.name_ar,
      serial: r.serial_number,
      created: r.created_at,
    })),
  );

  // Archive later duplicates with same Arabic name (keep oldest).
  const byName = new Map();
  for (const row of rows) {
    const key = String(row.name_ar).trim();
    if (!byName.has(key)) byName.set(key, []);
    byName.get(key).push(row);
  }
  for (const [name, group] of byName) {
    if (group.length < 2) continue;
    const [, ...dupes] = group;
    for (const dupe of dupes) {
      await sql`update properties set status = 'archived', updated_at = now() where id = ${dupe.id}`;
      console.log('archived_duplicate', { name, id: dupe.id, serial: dupe.serial_number });
    }
  }
} finally {
  await sql.end({ timeout: 2 });
}

