/** Browser-side image compression before property media upload. */

const MAX_EDGE = 1600;
const JPEG_QUALITY = 0.72;
const TARGET_BYTES = 1_200_000;

function loadImage(file: File): Promise<HTMLImageElement> {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const image = new Image();
    image.onload = () => {
      URL.revokeObjectURL(url);
      resolve(image);
    };
    image.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error('image_decode_failed'));
    };
    image.src = url;
  });
}

function canvasToBlob(
  canvas: HTMLCanvasElement,
  type: string,
  quality: number,
): Promise<Blob> {
  return new Promise((resolve, reject) => {
    canvas.toBlob(
      (blob) => (blob ? resolve(blob) : reject(new Error('image_encode_failed'))),
      type,
      quality,
    );
  });
}

/** Shrink and re-encode large photos (JPEG/WebP) for faster upload and less storage. */
export async function compressImageFile(file: File): Promise<File> {
  if (!file.type.startsWith('image/') || file.type === 'image/svg+xml') return file;
  if (file.size <= 450_000) return file;

  try {
    const image = await loadImage(file);
    const scale = Math.min(1, MAX_EDGE / Math.max(image.width, image.height));
    const width = Math.max(1, Math.round(image.width * scale));
    const height = Math.max(1, Math.round(image.height * scale));
    const canvas = document.createElement('canvas');
    canvas.width = width;
    canvas.height = height;
    const ctx = canvas.getContext('2d');
    if (!ctx) return file;
    ctx.drawImage(image, 0, 0, width, height);

    let quality = JPEG_QUALITY;
    let blob = await canvasToBlob(canvas, 'image/jpeg', quality);
    while (blob.size > TARGET_BYTES && quality > 0.45) {
      quality -= 0.08;
      blob = await canvasToBlob(canvas, 'image/jpeg', quality);
    }

    if (blob.size >= file.size * 0.95) return file;
    const base = file.name.replace(/\.[^.]+$/, '') || 'property';
    return new File([blob], `${base}.jpg`, {
      type: 'image/jpeg',
      lastModified: Date.now(),
    });
  } catch {
    return file;
  }
}

import 'server-only';
import { createHash, randomUUID } from 'node:crypto';
import { PutObjectCommand, S3Client, GetObjectCommand } from '@aws-sdk/client-s3';
import { and, eq, sql } from 'drizzle-orm';
import type { SessionClaims } from '@bhd-r/authz';
import { createDatabase, mediaAssets, unitMedia, units, type Database } from '@bhd-r/db';

type DbHandle = { db: Database };
const globalForDb = globalThis as unknown as { __bhdRPropertyWriteDb?: DbHandle };

function getDatabase(): DbHandle {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL is required');
  if (!globalForDb.__bhdRPropertyWriteDb) {
    const { db } = createDatabase(url, { max: 2 });
    globalForDb.__bhdRPropertyWriteDb = { db };
  }
  return globalForDb.__bhdRPropertyWriteDb;
}

function s3Configured(): boolean {
  return Boolean(
    process.env.S3_ENDPOINT &&
      process.env.S3_ACCESS_KEY &&
      process.env.S3_SECRET_KEY &&
      !String(process.env.S3_ENDPOINT).includes('example.com'),
  );
}

function getS3(): S3Client {
  return new S3Client({
    region: process.env.S3_REGION ?? 'auto',
    forcePathStyle: true,
    endpoint: process.env.S3_ENDPOINT,
    credentials: {
      accessKeyId: process.env.S3_ACCESS_KEY!,
      secretAccessKey: process.env.S3_SECRET_KEY!,
    },
  });
}

async function withinTenant<T>(
  claims: SessionClaims,
  work: (tx: Parameters<Parameters<Database['transaction']>[0]>[0]) => Promise<T>,
): Promise<T> {
  const { db } = getDatabase();
  return db.transaction(async (transaction) => {
    await transaction.execute(
      sql`select set_config('app.organization_id', ${claims.organizationId ?? ''}, true)`,
    );
    await transaction.execute(sql`select set_config('app.user_id', ${claims.sub}, true)`);
    await transaction.execute(
      sql`select set_config('app.party_id', ${claims.partyId ?? ''}, true)`,
    );
    await transaction.execute(
      sql`select set_config('app.platform_admin', ${String(claims.roles.includes('platform_admin'))}, true)`,
    );
    await transaction.execute(
      sql`select set_config('app.is_tenant', ${String(claims.roles.includes('tenant'))}, true)`,
    );
    await transaction.execute(sql`select set_config('app.public', 'false', true)`);
    return work(transaction);
  });
}

export async function uploadUnitMediaOnNeon(
  claims: SessionClaims,
  input: {
    unitId: string;
    purpose: 'property_image' | 'attachment';
    position: number;
    mimeType: string;
    bytes: Buffer;
    fileName?: string;
  },
): Promise<{ assetId: string; url: string }> {
  if (!claims.organizationId) throw new Error('organization_required');
  if (!claims.permissions.includes('media.create')) throw new Error('forbidden');
  if (!s3Configured()) throw new Error('s3_unconfigured');

  const allowed =
    input.purpose === 'property_image'
      ? new Set(['image/jpeg', 'image/png', 'image/webp'])
      : new Set(['image/jpeg', 'image/png', 'image/webp', 'application/pdf']);
  if (!allowed.has(input.mimeType) || input.bytes.byteLength < 1 || input.bytes.byteLength > 12 * 1024 * 1024) {
    throw new Error('invalid_file');
  }

  const extension =
    input.mimeType === 'image/png'
      ? 'png'
      : input.mimeType === 'image/webp'
        ? 'webp'
        : input.mimeType === 'application/pdf'
          ? 'pdf'
          : 'jpg';
  const objectKey = `org/${claims.organizationId}/units/${input.unitId}/${randomUUID()}.${extension}`;
  const publicBucket = process.env.S3_BUCKET_PUBLIC?.trim();
  const privateBucket = process.env.S3_BUCKET_PRIVATE?.trim() || 'bhd-r-private';
  const usePublic = Boolean(publicBucket) && input.purpose === 'property_image';
  const bucket = usePublic ? publicBucket! : privateBucket;
  const sha256 = createHash('sha256').update(input.bytes).digest('hex');

  const assetId = await withinTenant(claims, async (transaction) => {
    const unit = await transaction.query.units.findFirst({
      where: and(
        eq(units.id, input.unitId),
        eq(units.organizationId, claims.organizationId!),
      ),
    });
    if (!unit) throw new Error('unit_not_found');

    const rows = await transaction
      .insert(mediaAssets)
      .values({
        organizationId: claims.organizationId!,
        uploadedByUserId: claims.sub,
        privateObjectKey: objectKey,
        publicObjectKey: usePublic ? objectKey : null,
        mimeType: input.mimeType,
        byteSize: BigInt(input.bytes.byteLength),
        sha256,
        processingStatus: 'ready',
        scanStatus: 'clean',
        metadata: {
          purpose: input.purpose,
          unitId: input.unitId,
          via: 'vercel-neon',
          fileName: input.fileName ?? null,
        },
      })
      .returning();
    const asset = rows[0]!;
    await transaction.insert(unitMedia).values({
      organizationId: claims.organizationId!,
      unitId: input.unitId,
      mediaAssetId: asset.id,
      position: input.position,
    });
    return asset.id;
  });

  await getS3().send(
    new PutObjectCommand({
      Bucket: bucket,
      Key: objectKey,
      Body: input.bytes,
      ContentType: input.mimeType,
      ContentLength: input.bytes.byteLength,
      ...(usePublic ? { ACL: 'public-read' as const } : {}),
    }),
  );

  return { assetId, url: `/api/owner/media/${assetId}` };
}

export async function loadUnitMediaBytes(
  claims: SessionClaims,
  assetId: string,
): Promise<{ bytes: Buffer; mimeType: string } | null> {
  if (!claims.organizationId) return null;
  if (!s3Configured()) return null;

  const asset = await withinTenant(claims, async (transaction) => {
    return transaction.query.mediaAssets.findFirst({
      where: and(
        eq(mediaAssets.id, assetId),
        eq(mediaAssets.organizationId, claims.organizationId!),
      ),
    });
  });
  if (!asset) return null;

  const publicBucket = process.env.S3_BUCKET_PUBLIC?.trim();
  const privateBucket = process.env.S3_BUCKET_PRIVATE?.trim() || 'bhd-r-private';
  const bucket = asset.publicObjectKey && publicBucket ? publicBucket : privateBucket;
  const key = asset.publicObjectKey || asset.privateObjectKey;

  const result = await getS3().send(
    new GetObjectCommand({
      Bucket: bucket,
      Key: key,
    }),
  );
  const body = result.Body;
  if (!body) return null;
  const bytes = Buffer.from(await body.transformToByteArray());
  return { bytes, mimeType: asset.mimeType };
}

export { s3Configured };

import { cookies } from 'next/headers';
import { NextResponse } from 'next/server';
import { verifySessionToken } from '@bhd-r/authz';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { s3Configured, uploadUnitMediaOnNeon } from '@/lib/upload-property-media-neon';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 60;

function sessionSecret(): Uint8Array {
  return new TextEncoder().encode(
    process.env.BHD_R_SESSION_SECRET ?? 'development-session-secret-at-least-32-characters',
  );
}

/** POST /api/owner/media — compress-friendly property image/doc upload via Vercel→R2→Neon. */
export async function POST(request: Request) {
  if (!hasDatabaseUrl()) {
    return NextResponse.json(
      {
        error: {
          code: 'db_unconfigured',
          message: 'DATABASE_URL is not set',
          messageAr: 'قاعدة البيانات غير مضبوطة',
        },
      },
      { status: 503 },
    );
  }
  if (!s3Configured()) {
    return NextResponse.json(
      {
        error: {
          code: 's3_unconfigured',
          message: 'Object storage is not configured on Vercel',
          messageAr: 'تخزين الصور غير مضبوط على Vercel (S3/R2)',
        },
      },
      { status: 503 },
    );
  }

  const token = (await cookies()).get('bhd_r_session')?.value;
  if (!token) {
    return NextResponse.json(
      {
        error: {
          code: 'unauthorized',
          message: 'Authentication is required',
          messageAr: 'يلزم تسجيل الدخول',
        },
      },
      { status: 401 },
    );
  }

  let claims: Awaited<ReturnType<typeof verifySessionToken>>;
  try {
    claims = await verifySessionToken(token, sessionSecret());
  } catch {
    return NextResponse.json(
      {
        error: {
          code: 'unauthorized',
          message: 'Invalid or expired session',
          messageAr: 'انتهت الجلسة',
        },
      },
      { status: 401 },
    );
  }

  try {
    const form = await request.formData();
    const file = form.get('file');
    const unitId = String(form.get('unitId') ?? '');
    const purposeRaw = String(form.get('purpose') ?? 'property_image');
    const purpose =
      purposeRaw === 'attachment' ? ('attachment' as const) : ('property_image' as const);
    const position = Number(form.get('position') ?? 0);
    if (!(file instanceof File) || !unitId) {
      return NextResponse.json(
        {
          error: {
            code: 'validation_failed',
            message: 'file and unitId are required',
            messageAr: 'الملف ومعرّف الوحدة مطلوبان',
          },
        },
        { status: 400 },
      );
    }
    const bytes = Buffer.from(await file.arrayBuffer());
    const result = await uploadUnitMediaOnNeon(claims, {
      unitId,
      purpose,
      position: Number.isFinite(position) ? position : 0,
      mimeType: file.type || 'application/octet-stream',
      bytes,
      fileName: file.name,
    });
    return NextResponse.json(result, { status: 201 });
  } catch (error) {
    const code = error instanceof Error ? error.message : 'upload_failed';
    const map: Record<string, { status: number; ar: string; en: string }> = {
      forbidden: { status: 403, ar: 'ليست لديك صلاحية رفع الملفات', en: 'Forbidden' },
      organization_required: { status: 400, ar: 'اختر مؤسسة أولاً', en: 'Organization required' },
      unit_not_found: { status: 404, ar: 'الوحدة غير موجودة', en: 'Unit not found' },
      invalid_file: { status: 400, ar: 'نوع أو حجم الملف غير مسموح', en: 'Invalid file' },
      s3_unconfigured: {
        status: 503,
        ar: 'تخزين الصور غير مضبوط',
        en: 'Object storage unconfigured',
      },
    };
    const known = map[code];
    if (known) {
      return NextResponse.json(
        { error: { code, message: known.en, messageAr: known.ar } },
        { status: known.status },
      );
    }
    console.error('POST /api/owner/media failed', error);
    return NextResponse.json(
      {
        error: {
          code: 'upload_failed',
          message: error instanceof Error ? error.message : 'Upload failed',
          messageAr: 'تعذر رفع الملف',
        },
      },
      { status: 500 },
    );
  }
}

import { cookies } from 'next/headers';
import { NextResponse } from 'next/server';
import { verifySessionToken } from '@bhd-r/authz';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { loadUnitMediaBytes } from '@/lib/upload-property-media-neon';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 30;

function sessionSecret(): Uint8Array {
  return new TextEncoder().encode(
    process.env.BHD_R_SESSION_SECRET ?? 'development-session-secret-at-least-32-characters',
  );
}

/** GET /api/owner/media/:assetId — stream stored property media for the signed-in org. */
export async function GET(
  _request: Request,
  context: { params: Promise<{ assetId: string }> },
) {
  if (!hasDatabaseUrl()) {
    return NextResponse.json({ error: { code: 'db_unconfigured' } }, { status: 503 });
  }

  const token = (await cookies()).get('bhd_r_session')?.value;
  if (!token) {
    return NextResponse.json({ error: { code: 'unauthorized' } }, { status: 401 });
  }

  let claims: Awaited<ReturnType<typeof verifySessionToken>>;
  try {
    claims = await verifySessionToken(token, sessionSecret());
  } catch {
    return NextResponse.json({ error: { code: 'unauthorized' } }, { status: 401 });
  }

  const { assetId } = await context.params;
  if (!assetId || assetId.length < 32) {
    return NextResponse.json({ error: { code: 'not_found' } }, { status: 404 });
  }

  try {
    const media = await loadUnitMediaBytes(claims, assetId);
    if (!media) {
      return NextResponse.json({ error: { code: 'not_found' } }, { status: 404 });
    }
    return new NextResponse(new Uint8Array(media.bytes), {
      status: 200,
      headers: {
        'content-type': media.mimeType,
        'cache-control': 'private, max-age=3600',
      },
    });
  } catch (error) {
    console.error('GET /api/owner/media failed', error);
    return NextResponse.json({ error: { code: 'read_failed' } }, { status: 500 });
  }
}

