/**
 * Adaptive portal surfaces — phone / tablet / desktop scale in one place.
 * Imported last from globals.css so these rules win over scattered media queries.
 */

:root {
  --portal-pad: clamp(0.7rem, 1.8vw, 1.35rem);
  --portal-gap: clamp(0.5rem, 1.2vw, 1rem);
  --portal-text: clamp(0.84rem, 0.78rem + 0.25vw, 0.95rem);
  --portal-title: clamp(1.15rem, 1rem + 1.1vw, 1.85rem);
  --portal-control-h: clamp(2.2rem, 2rem + 0.55vw, 2.7rem);
  --portal-icon: clamp(1.85rem, 1.65rem + 0.45vw, 2.4rem);
  --portal-radius: clamp(0.6rem, 0.5rem + 0.35vw, 1rem);
}

.portal-layout {
  font-size: var(--portal-text);
}

.portal-main {
  padding: var(--portal-pad);
  padding-block-end: calc(var(--portal-pad) + var(--safe-bottom));
}

.portal-chrome__row {
  min-height: calc(var(--portal-icon) + 0.85rem);
  gap: var(--portal-gap);
  padding-inline: var(--portal-pad);
  padding-block: 0.4rem;
  padding-block-start: calc(0.4rem + var(--safe-top));
}

.portal-chrome__menu,
.portal-chrome__lang,
.bhd-switcher-grid,
.bhd-switcher-avatar {
  width: var(--portal-icon);
  height: var(--portal-icon);
  min-width: var(--portal-icon);
  min-height: var(--portal-icon);
}

.portal-chrome__avatar,
.bhd-switcher-avatar > span {
  width: calc(var(--portal-icon) - 0.2rem);
  height: calc(var(--portal-icon) - 0.2rem);
  font-size: calc(var(--portal-icon) * 0.38);
}

.portal-chrome__logo .logo__product img {
  width: clamp(2.4rem, 2.1rem + 1.2vw, 3.6rem);
}

.ops-workspace,
.wizard-shell,
.property-360 {
  font-size: var(--portal-text);
}

.ops-header,
.wizard-hero,
.property-360__titlebar {
  gap: var(--portal-gap);
}

.ops-header h1,
.wizard-hero h1,
.property-360__titlebar h1 {
  font-size: var(--portal-title);
  line-height: 1.25;
  margin: 0.1rem 0 0.25rem;
}

.ops-header,
.property-360__section,
.property-360__summary-card,
.ops-mobile-card,
.wizard-progress-compact,
.wizard-card.card {
  border-radius: var(--portal-radius);
}

.ops-metrics {
  gap: var(--portal-gap);
  margin-block: var(--portal-gap);
}

.ops-metrics > div,
.ops-metrics > article {
  padding: calc(var(--portal-pad) * 0.75);
  border-radius: calc(var(--portal-radius) * 0.9);
}

.ops-metrics strong {
  font-size: clamp(1.05rem, 0.95rem + 0.8vw, 1.55rem);
}

.ops-metrics span,
.ops-metrics small {
  font-size: 0.78em;
  line-height: 1.3;
}

.wizard-shell .input,
.wizard-shell .select,
.wizard-shell .textarea,
.ops-workspace .input,
.ops-workspace .select,
.ops-search input {
  min-height: var(--portal-control-h);
  font-size: var(--portal-text);
  border-radius: calc(var(--portal-radius) * 0.85);
}

.wizard-shell .field label,
.ops-workspace label {
  font-size: 0.86em;
}

.button {
  min-height: var(--portal-control-h);
  font-size: var(--portal-text);
}

.property-360__layout {
  gap: var(--portal-gap);
}

.property-360__hero-shot {
  border-radius: var(--portal-radius);
}

.property-360__price strong {
  font-size: clamp(1.15rem, 1rem + 1vw, 1.55rem);
}

.property-360__facts > div {
  padding-block: 0.3rem;
  font-size: 0.95em;
}

.ops-mobile-card {
  padding: calc(var(--portal-pad) * 0.9);
  gap: calc(var(--portal-gap) * 0.85);
}

.ops-mobile-card__title {
  font-size: 1.05em;
}

.ops-mobile-card__serial {
  font-size: 0.86em;
}

.ops-mobile-card__meta div {
  font-size: 0.95em;
}

/* —— Phone & narrow tablet —— */
@media (max-width: 960px) {
  :root {
    --portal-pad: 0.65rem;
    --portal-gap: 0.45rem;
    --portal-text: 0.84rem;
    --portal-title: 1.08rem;
