      ST_Y(location::geometry) as lat,
      ST_X(location::geometry) as lon
    from addresses
    where id = ${property.addressId}
    limit 1
  `),
]);

const coordRow = Array.isArray(coords) ? coords[0] : (coords as { rows?: Array<{ lat: number | null; lon: number | null }> }).rows?.[0];
const latitude =
  coordRow?.lat !== null && coordRow?.lat !== undefined && Number.isFinite(Number(coordRow.lat))
    ? Number(coordRow.lat)
    : null;
const longitude =
  coordRow?.lon !== null && coordRow?.lon !== undefined && Number.isFinite(Number(coordRow.lon))
    ? Number(coordRow.lon)
