import 'server-only';
import { getLocale } from 'next-intl/server';
import { ApiError } from '@/lib/api';
import {
  apiFetch,
  configuredApiOrigin,
  isNestApiConfiguredForRuntime,
} from '@/lib/server-api';
import { loadOpsRecordsFromDb } from '@/lib/portal-ops-data';
import type { PortalRole } from '@/lib/types';
import type { OperationsContext } from '@/components/operations-console';

export type OperationsSection =
  | 'properties'
  | 'contacts'
  | 'requests'
  | 'bookings'
  | 'leasing'
  | 'sales'
  | 'contracts'
  | 'invoices'
  | 'payments'
  | 'accounting'
  | 'expenses'
  | 'maintenance'
  | 'work-orders'
  | 'tasks'
  | 'legal'
  | 'approvals'
  | 'reports'
  | 'team'
  | 'api-keys';

export const OPERATIONS_SECTIONS = [
  'properties',
  'contacts',
  'requests',
  'bookings',
  'leasing',
  'sales',
  'contracts',
  'invoices',
  'payments',
  'accounting',
  'expenses',
  'maintenance',
  'work-orders',
  'tasks',
  'legal',
  'approvals',
  'reports',
  'team',
  'api-keys',
] as const satisfies readonly OperationsSection[];

type DataRow = Record<string, unknown>;

export type OperationsWorkspacePayload = {
  records: DataRow[];
  summary: DataRow;
  secondary: DataRow[];
  context: OperationsContext;
  apiOnline: boolean;
  nestConfigured: boolean;
  recordsEmpty: boolean;
  apiUnauthorized: boolean;
  dataFromDb: boolean;
  locale: 'ar' | 'en';
};

async function safeRows(path: string): Promise<DataRow[]> {
  const payload = await Promise.race([
    apiFetch<DataRow[] | { data: DataRow[] }>(path)
      .then((value) => value)
      .catch(() => [] as DataRow[] | { data: DataRow[] }),
    new Promise<DataRow[]>((resolve) => {
      setTimeout(() => resolve([]), 3_500);
    }),
  ]);
  return Array.isArray(payload) ? payload : (payload.data ?? []);
}

async function loadSection(portal: PortalRole, section: OperationsSection) {
  const fromDb = await loadOpsRecordsFromDb(portal, section);
  if (fromDb !== null) return { records: fromDb as DataRow[], source: 'db' as const };

  switch (section) {
    case 'properties':
      return {
        records: await safeRows(
          portal === 'developer' ? '/v1/developer/projects' : '/v1/owner/properties',
        ),
      };
    case 'contacts':
      return { records: await safeRows('/v1/parties') };
    case 'requests':
      return { records: await safeRows('/v1/operations/requests') };
    case 'bookings': {
      const [reservations, viewings, holds] = await Promise.all([
        safeRows('/v1/leasing/reservations'),
        safeRows('/v1/operations/viewings'),
        safeRows('/v1/leasing/holds'),
      ]);
      return {
        records: [
          ...reservations.map((row) => ({ ...row, recordKind: 'reservation' })),
          ...viewings.map((row) => ({ ...row, recordKind: 'viewing' })),
          ...holds.map((row) => ({ ...row, recordKind: 'hold' })),
        ],
      };
    }
    case 'leasing':
      return { records: await safeRows('/v1/leasing/leases') };
    case 'sales': {
      const [records, totals] = await Promise.all([
        safeRows('/v1/operations/sales'),
        apiFetch<Record<string, unknown>>('/v1/operations/sales/totals').catch(() => ({})),
      ]);
      return { records, summary: totals };
    }
    case 'contracts':
      return { records: await safeRows('/v1/leasing/contracts') };
    case 'invoices':
      return { records: await safeRows('/v1/finance/invoices') };
    case 'payments': {
      const [payments, receipts] = await Promise.all([
        safeRows('/v1/finance/payments'),
        safeRows('/v1/finance/receipts'),
      ]);
      return {
        records: [
          ...payments.map((row) => ({ ...row, recordKind: 'payment' })),
          ...receipts.map((row) => ({ ...row, recordKind: 'receipt', status: 'issued' })),
        ],
      };
    }
    case 'accounting': {
      const [records, dashboard, trialBalance, chequeRows, invoiceRows] = await Promise.all([
        safeRows('/v1/accounting/journals'),
        apiFetch<Record<string, unknown>>('/v1/accounting/dashboard').catch(() => ({})),
        safeRows('/v1/accounting/trial-balance'),
        safeRows('/v1/finance/cheques'),
        safeRows('/v1/finance/invoices'),
      ]);
      return {
        records,
        summary: {
          ...dashboard,
          activeLeaseInvoices: invoiceRows.filter((row) => row.leaseId && row.status !== 'void')
            .length,
          pendingCheques: chequeRows.filter((row) => row.reviewStatus === 'pending').length,
        },
        secondary: [
          ...chequeRows.map((row) => ({ ...row, recordKind: 'cheque', status: row.reviewStatus })),
          ...invoiceRows
            .filter((row) => row.leaseId)
            .map((row) => ({ ...row, recordKind: 'lease_invoice' })),
        ],
      };
    }
    case 'expenses':
      return { records: await safeRows('/v1/accounting/expenses') };
    case 'maintenance':
      return { records: await safeRows('/v1/maintenance') };
    case 'work-orders':
      return { records: await safeRows('/v1/operations/work-orders') };
    case 'tasks':
      return { records: await safeRows('/v1/operations/tasks') };
    case 'legal':
      return { records: await safeRows('/v1/operations/legal-cases') };
    case 'approvals':
      return { records: await safeRows('/v1/operations/approvals') };
    case 'reports': {
      const [records, summary] = await Promise.all([
        safeRows('/v1/reports'),
        apiFetch<Record<string, unknown>>('/v1/reports/operational-summary').catch(() => ({})),
      ]);
      return { records, summary };
    }
    case 'team':
      return { records: await safeRows('/v1/organizations/current/members') };
    case 'api-keys':
      return { records: await safeRows('/v1/auth/api-keys') };
  }
}

async function probeNestHealthz(): Promise<boolean> {
  const origin = configuredApiOrigin();
  if (!origin) return false;
  try {
    const response = await fetch(`${origin}/healthz`, {
      headers: { accept: 'application/json' },
      cache: 'no-store',
      signal: AbortSignal.timeout(3_000),
    });
    return response.ok;
  } catch {
    return false;
  }
}

export function isOperationsSection(value: string): value is OperationsSection {
  return (OPERATIONS_SECTIONS as readonly string[]).includes(value);
}

export async function loadOperationsWorkspacePayload(
  portal: PortalRole,
  section: OperationsSection,
  localeHint?: 'ar' | 'en',
): Promise<OperationsWorkspacePayload> {
  const locale =
    localeHint ?? ((await getLocale()) === 'en' ? 'en' : 'ar');
  const nestConfigured = isNestApiConfiguredForRuntime();
  const [loaded, contextResult, healthzOk] = await Promise.all([
    loadSection(portal, section),
    portal === 'tenant'
      ? Promise.resolve({
          ok: true as const,
          unauthorized: false,
          unreachable: false,
          context: {} as OperationsContext,
        })
      : Promise.race([
          apiFetch<OperationsContext>('/v1/operations/context')
            .then((payload) => ({
              ok: true as const,
              unauthorized: false,
              unreachable: false,
              context: payload,
            }))
            .catch((error: unknown) => ({
              ok: false as const,
              unauthorized: error instanceof ApiError && error.status === 401,
              unreachable:
                error instanceof ApiError &&
                (error.status === 503 || error.code === 'api_unreachable'),
              context: {} as OperationsContext,
            })),
          new Promise<{
            ok: false;
            unauthorized: false;
            unreachable: true;
            context: OperationsContext;
          }>((resolve) => {
            setTimeout(
              () =>
                resolve({
                  ok: false,
                  unauthorized: false,
                  unreachable: true,
                  context: {} as OperationsContext,
                }),
              3_500,
            );
          }),
        ]),
    probeNestHealthz(),
  ]);
  const apiOnline = portal === 'tenant' ? true : healthzOk || !contextResult.unreachable;
  const context = contextResult.context;
  const recordsEmpty = !loaded.records.length;
  const dataFromDb = 'source' in loaded && loaded.source === 'db';
  const apiUnauthorized =
    Boolean(contextResult.unauthorized) && !(dataFromDb && !recordsEmpty);

  return {
    records: loaded.records,
    summary: loaded.summary ?? {},
    secondary: loaded.secondary ?? [],
    context,
    apiOnline,
    nestConfigured,
    recordsEmpty,
    apiUnauthorized,
    dataFromDb,
    locale,
  };
}

import { cookies } from 'next/headers';
import { NextResponse } from 'next/server';
import { verifySessionToken } from '@bhd-r/authz';
import {
  isOperationsSection,
  loadOperationsWorkspacePayload,
} from '@/lib/portal-ops-workspace';
import type { PortalRole } from '@/lib/types';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 60;

const PORTALS = new Set<PortalRole>(['owner', 'developer', 'tenant', 'platform']);

function sessionSecret(): Uint8Array {
  return new TextEncoder().encode(
    process.env.BHD_R_SESSION_SECRET ?? 'development-session-secret-at-least-32-characters',
  );
}

function portalsForRoles(roles: readonly string[]): PortalRole[] {
  const portalSet = new Set<PortalRole>();
  if (roles.some((role) => role === 'platform_admin' || role === 'platform_support'))
    portalSet.add('platform');
  if (roles.includes('developer_admin')) portalSet.add('developer');
  if (roles.includes('tenant')) portalSet.add('tenant');
  if (
    roles.some((role) =>
      [
        'organization_owner',
        'organization_admin',
        'property_manager',
        'finance_manager',
        'maintenance_agent',
        'auditor',
      ].includes(role),
    )
  )
    portalSet.add('owner');
  return [...portalSet];
}

/**
 * GET /api/portal/ops/:portal/:section
 * Session-backed ops payload for client cache / soft navigation (WAZEN-style).
 */
export async function GET(
  _request: Request,
  context: { params: Promise<{ portal: string; section: string }> },
) {
  const { portal: portalRaw, section: sectionRaw } = await context.params;
  if (!PORTALS.has(portalRaw as PortalRole) || !isOperationsSection(sectionRaw)) {
    return NextResponse.json({ error: { code: 'not_found' } }, { status: 404 });
  }
  const portal = portalRaw as PortalRole;

  const token = (await cookies()).get('bhd_r_session')?.value;
  if (!token) {
    return NextResponse.json({ error: { code: 'unauthorized' } }, { status: 401 });
  }

  let claims: Awaited<ReturnType<typeof verifySessionToken>>;
  try {
    claims = await verifySessionToken(token, sessionSecret());
  } catch {
    return NextResponse.json({ error: { code: 'unauthorized' } }, { status: 401 });
  }

  const allowed = portalsForRoles(claims.roles);
  if (!allowed.includes(portal)) {
    return NextResponse.json({ error: { code: 'forbidden' } }, { status: 403 });
  }

  const locale = claims.locale === 'en' ? 'en' : 'ar';
  const payload = await loadOperationsWorkspacePayload(portal, sectionRaw, locale);
  return NextResponse.json(payload, {
    headers: {
      'Cache-Control': 'private, no-store',
    },
  });
}

import type { OperationsWorkspacePayload } from '@/lib/portal-ops-workspace';
import type { PortalRole } from '@/lib/types';
import type { OperationsSection } from '@/lib/portal-ops-workspace';

type CacheEntry = {
  payload: OperationsWorkspacePayload;
  savedAt: number;
};

const TTL_MS = 5 * 60 * 1000;
const store = new Map<string, CacheEntry>();
const inflight = new Map<string, Promise<OperationsWorkspacePayload | null>>();

function key(portal: PortalRole, section: OperationsSection): string {
  return `${portal}:${section}`;
}

export function getOpsCache(
  portal: PortalRole,
  section: OperationsSection,
): OperationsWorkspacePayload | null {
  const hit = store.get(key(portal, section));
  if (!hit) return null;
  if (Date.now() - hit.savedAt > TTL_MS) {
    store.delete(key(portal, section));
    return null;
  }
  return hit.payload;
}

export function setOpsCache(
  portal: PortalRole,
  section: OperationsSection,
  payload: OperationsWorkspacePayload,
): void {
  store.set(key(portal, section), { payload, savedAt: Date.now() });
}

export function invalidateOpsCache(portal?: PortalRole, section?: OperationsSection): void {
  if (!portal) {
    store.clear();
    return;
  }
  if (!section) {
    for (const k of store.keys()) {
      if (k.startsWith(`${portal}:`)) store.delete(k);
    }
    return;
  }
  store.delete(key(portal, section));
}

export async function fetchOpsPayload(
  portal: PortalRole,
  section: OperationsSection,
): Promise<OperationsWorkspacePayload | null> {
  const cacheKey = key(portal, section);
  const existing = inflight.get(cacheKey);
  if (existing) return existing;

  const task = (async () => {
    try {
      const response = await fetch(`/api/portal/ops/${portal}/${section}`, {
        method: 'GET',
        credentials: 'same-origin',
        cache: 'no-store',
        headers: { accept: 'application/json' },
      });
      if (!response.ok) return null;
      const payload = (await response.json()) as OperationsWorkspacePayload;
      setOpsCache(portal, section, payload);
      return payload;
    } catch {
      return null;
    } finally {
      inflight.delete(cacheKey);
    }
  })();

  inflight.set(cacheKey, task);
  return task;
}

/** Warm a section into memory without throwing. */
export function warmOpsSection(portal: PortalRole, section: OperationsSection): void {
  if (getOpsCache(portal, section)) return;
  void fetchOpsPayload(portal, section);
}

'use client';

import { useEffect, useState } from 'react';
import { BrandMark } from '@bhd-r/ui';
import type { PortalRole } from '@/lib/types';
import type { OperationsSection, OperationsWorkspacePayload } from '@/lib/portal-ops-workspace';
import { fetchOpsPayload, getOpsCache } from '@/lib/portal-ops-client-cache';
import { OperationsConsole } from './operations-console';

/**
 * Client ops workspace: paint from in-memory cache when available so sidebar
 * navigation feels like returning to an already-open view (WAZEN-style).
 */
export function OperationsWorkspaceClient({
  portal,
  section,
  locale,
}: {
  portal: PortalRole;
  section: OperationsSection;
  locale: 'ar' | 'en';
}) {
  const [payload, setPayload] = useState<OperationsWorkspacePayload | null>(() =>
    getOpsCache(portal, section),
  );
  const [busy, setBusy] = useState(() => !getOpsCache(portal, section));

  useEffect(() => {
    let cancelled = false;
    const hit = getOpsCache(portal, section);
    if (hit) {
      setPayload(hit);
      setBusy(false);
      // Soft revalidate in the background so data stays fresh without blocking UI.
      void fetchOpsPayload(portal, section).then((fresh) => {
        if (!cancelled && fresh) setPayload(fresh);
      });
      return () => {
        cancelled = true;
      };
    }

    setBusy(true);
    void fetchOpsPayload(portal, section).then((fresh) => {
      if (cancelled) return;
      if (fresh) setPayload(fresh);
      setBusy(false);
    });

    return () => {
      cancelled = true;
    };
  }, [portal, section]);

  if (!payload) {
    return (
      <div className="portal-ops-boot" aria-busy={busy} aria-live="polite">
        <BrandMark decorative className="portal-ops-boot__mark" />
        <p>{locale === 'ar' ? 'جاري تحميل القسم…' : 'Loading section…'}</p>
      </div>
    );
  }

  return (
    <OperationsConsole
      portal={portal}
      section={section}
      locale={payload.locale || locale}
      records={payload.records}
      summary={payload.summary}
      secondary={payload.secondary}
      context={payload.context}
      apiOnline={payload.apiOnline}
      nestConfigured={payload.nestConfigured}
      recordsEmpty={payload.recordsEmpty}
      apiUnauthorized={payload.apiUnauthorized}
      dataFromDb={payload.dataFromDb}
    />
  );
}

