'use client';

import { Logo } from '@bhd-r/ui';
import { useLocale, useTranslations } from 'next-intl';
import { Link, usePathname } from '@/i18n/navigation';
import { BhdAppSwitcher } from '@/components/bhd-app-switcher';
import type { PortalRole, Viewer } from '@/lib/types';

export function PortalHeader({
  portal,
  viewer,
  onOpenNav,
  navOpen = false,
  navPanelId,
}: {
  portal: PortalRole;
  viewer: Viewer;
  onOpenNav?: () => void;
  navOpen?: boolean;
  navPanelId?: string;
}) {
  const t = useTranslations();
  const locale = useLocale() as 'ar' | 'en';
  const pathname = usePathname();
  const ar = locale === 'ar';
  const nextLocale = locale === 'ar' ? 'en' : 'ar';
  const subtitle = viewer.email ?? viewer.username ?? (ar ? 'حساب BHD' : 'BHD account');
  const roleLabel = viewer.roles[0]?.replace(/_/g, ' ') ?? t(`Portal.${portal}`);

  return (
    <header className="portal-chrome">
      <div className="oman-flag-line" aria-hidden="true" />
      <div className="portal-chrome__row">
        <div className="portal-chrome__brand">
          {onOpenNav ? (
            <button
              type="button"
              className="portal-chrome__menu"
              aria-label={ar ? 'فتح القائمة' : 'Open menu'}
              aria-expanded={navOpen}
              aria-controls={navPanelId}
              onClick={onOpenNav}
            >
              <span aria-hidden="true">{navOpen ? '×' : '☰'}</span>
            </button>
          ) : null}
          <Link href={`/${portal}`} className="portal-chrome__logo" aria-label="BHD R">
            <Logo descriptor="" />
          </Link>
          <div className="portal-chrome__titles">
            <strong>BHD R</strong>
            <span>{t(`Portal.${portal}`)}</span>
          </div>
        </div>

        <div className="portal-chrome__actions">
          <Link
            href={pathname}
            locale={nextLocale}
            className="portal-chrome__lang"
            hrefLang={nextLocale}
            lang={nextLocale}
          >
            <span className="portal-chrome__lang-code">{nextLocale.toUpperCase()}</span>
            <span>{ar ? 'English' : 'العربية'}</span>
          </Link>

          {/* Text only — avatar lives in BhdAppSwitcher to avoid stacked identity controls. */}
          <div
            className="portal-chrome__user portal-chrome__user--text"
            title={`${viewer.displayName} · ${subtitle}`}
            aria-label={`${viewer.displayName}, ${roleLabel}, ${subtitle}`}
          >
            <strong>{viewer.displayName}</strong>
            <small>
              <span className="portal-chrome__role">{roleLabel}</span>
              <span className="portal-chrome__dot" aria-hidden="true">
                ·
              </span>
              <span>{subtitle}</span>
            </small>
          </div>

          <BhdAppSwitcher viewer={viewer} locale={locale} />
        </div>
      </div>
    </header>
  );
}

'use client';

import { useMemo, useState } from 'react';
import { browserMutation } from '@/lib/api';
import { formatMoney } from '@/lib/format';
import type { ManagedProperty } from '@/components/property-detail-manager';

export function PropertyManageHub({
  property,
  locale,
  portal,
}: {
  property: ManagedProperty;
  locale: 'ar' | 'en';
  portal: 'owner' | 'developer';
}) {
  const ar = locale === 'ar';
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const base = `/${locale}/${portal}`;
  const propertyId = encodeURIComponent(property.id);
  const publicPath = `/${locale}/properties/${property.id}`;
  const editHref = `${base}/properties/${property.id}/edit`;
  const scoped = (section: string) => `${base}/${section}?propertyId=${propertyId}`;

  const publishedUnits = property.units.filter((unit) => unit.listingEnabled).length;
  const unpublishedUnits = property.units.length - publishedUnits;
  const primaryUnit = property.units[0];
  const currency = primaryUnit?.currency ?? property.defaultCurrency;

  const alerts = useMemo(() => {
    const items: Array<{ text: string; href?: string }> = [];
    if (property.status === 'archived') {
      items.push({
        text: ar ? 'العقار مؤرشف — الإعلانات متوقفة.' : 'Property is archived — listings are off.',
      });
    }
    if (!property.gallery?.length) {
      items.push({
        text: ar ? 'لا صور في المعرض بعد.' : 'Gallery has no photos yet.',
        href: editHref,
      });
    }
    if (unpublishedUnits > 0) {
      items.push({
        text: ar
          ? `${unpublishedUnits} وحدة غير منشورة للجمهور.`
          : `${unpublishedUnits} unit(s) not published publicly.`,
        href: editHref,
      });
    }
    const missingDeposit = property.units.filter(
      (unit) => !unit.depositMinor || unit.depositMinor === '0',
    ).length;
    if (missingDeposit > 0) {
      items.push({
        text: ar
          ? 'حدّد مبلغ العربون/الحجز من تعديل العقار → الوحدات حتى يعمل زر «احجز الآن».'
          : 'Set the booking deposit under Edit property → Units so Book now works.',
        href: editHref,
      });
    }
    if (!property.address) {
      items.push({
        text: ar ? 'عنوان العقار غير مكتمل.' : 'Property address is incomplete.',
        href: editHref,
      });
    }
    return items;
  }, [ar, editHref, property, unpublishedUnits]);

  const actions = [
    { href: editHref, label: ar ? 'تعديل العقار (الضبط)' : 'Edit property (settings)', primary: true },
    { href: publicPath, label: ar ? 'عرض عام' : 'Public view', external: true },
    { href: scoped('contracts'), label: ar ? 'العقود' : 'Contracts' },
    { href: scoped('leasing'), label: ar ? 'التأجير' : 'Leasing' },
    { href: scoped('sales'), label: ar ? 'البيع' : 'Sales' },
    { href: scoped('bookings'), label: ar ? 'الحجوزات' : 'Bookings' },
    { href: scoped('maintenance'), label: ar ? 'الصيانة' : 'Maintenance' },
    { href: scoped('invoices'), label: ar ? 'الفواتير' : 'Invoices' },
  ];

  async function archiveOrRestore() {
    setBusy(true);
    setError(null);
    try {
      await browserMutation(
        `/v1/owner/properties/${property.id}/${property.status === 'archived' ? 'restore' : 'archive'}`,
        { method: 'POST', body: '{}' },
      );
      window.location.assign(`${base}/properties`);
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'request_failed');
      setBusy(false);
    }
  }

  return (
    <div className="property-manage-hub">
      <header className="property-manage-hub__hero">
        <div>
          <p className="muted">{ar ? 'مركز إدارة العقار' : 'Property operations hub'}</p>
          <h1>{locale === 'ar' ? property.nameAr : property.nameEn || property.nameAr}</h1>
          <p className="muted">
            {property.code ? <span dir="ltr">{property.code}</span> : null}
            {property.code ? ' · ' : null}
            {ar ? 'العملة:' : 'Currency:'} {currency}
            {primaryUnit?.depositMinor && primaryUnit.depositMinor !== '0' ? (
              <>
                {' · '}
                {ar ? 'عربون الحجز:' : 'Booking deposit:'}{' '}
                <strong dir="ltr">{formatMoney(primaryUnit.depositMinor, currency, locale)}</strong>
              </>
            ) : null}
          </p>
        </div>
      </header>

      <section className="property-manage-hub__stats" aria-label={ar ? 'إحصائيات' : 'Stats'}>
        <div>
          <strong>{property.units.length}</strong>
          <span>{ar ? 'وحدات' : 'Units'}</span>
        </div>
        <div>
          <strong>{publishedUnits}</strong>
          <span>{ar ? 'منشورة' : 'Published'}</span>
        </div>
        <div>
          <strong>{property.gallery?.length ?? 0}</strong>
          <span>{ar ? 'صور' : 'Photos'}</span>
        </div>
        <div>
          <strong>{property.status === 'archived' ? (ar ? 'مؤرشف' : 'Archived') : ar ? 'نشط' : 'Active'}</strong>
          <span>{ar ? 'الحالة' : 'Status'}</span>
        </div>
      </section>

      {alerts.length ? (
        <section className="property-manage-hub__alerts" aria-label={ar ? 'تنبيهات' : 'Alerts'}>
          <h2>{ar ? 'تنبيهات' : 'Alerts'}</h2>
          <ul>
            {alerts.map((alert) => (
              <li key={alert.text}>
                {alert.href ? <a href={alert.href}>{alert.text}</a> : alert.text}
              </li>
            ))}
          </ul>
        </section>
      ) : null}

      {error ? (
        <p className="error" role="alert">
          {error}
        </p>
      ) : null}

      <section className="property-manage-hub__actions" aria-label={ar ? 'إجراءات' : 'Actions'}>
        <h2>{ar ? 'إجراءات هذا العقار' : 'Actions for this property'}</h2>
        <div className="property-manage-hub__action-grid">
          {actions.map((action) =>
            'external' in action && action.external ? (
              <a
                key={action.href}
                className="button button--quiet"
                href={action.href}
                target="_blank"
                rel="noreferrer"
              >
                {action.label}
              </a>
            ) : (
              <a
                key={action.href}
                className={`button ${'primary' in action && action.primary ? 'button--primary' : 'button--quiet'}`}
                href={action.href}
              >
                {action.label}
              </a>
            ),
          )}
        </div>
      </section>

      <section className="ops-panel property-danger-zone">
        <div>
          <h2>
            {property.status === 'archived'
              ? ar
                ? 'استعادة العقار'
                : 'Restore property'
              : ar
                ? 'أرشفة العقار'
                : 'Archive property'}
          </h2>
          <p>
            {property.status === 'archived'
              ? ar
                ? 'تعيد الأصل دون إعادة نشر أي وحدة تلقائياً.'
                : 'Restores the asset without automatically republishing units.'
              : ar
                ? 'يتوقف نشر جميع الوحدات، ولا تُحذف السجلات أو الوثائق.'
                : 'All listings are unpublished; records and documents remain retained.'}
          </p>
        </div>
        <button
          className={`button ${property.status === 'archived' ? 'button--primary' : 'button--danger'}`}
          type="button"
          disabled={busy}
          onClick={() => void archiveOrRestore()}
        >
          {property.status === 'archived' ? (ar ? 'استعادة' : 'Restore') : ar ? 'أرشفة' : 'Archive'}
        </button>
      </section>
    </div>
  );
}

'use client';

import { useMemo, useState } from 'react';
import { useRouter } from 'next/navigation';
import { browserMutation } from '@/lib/api';
import { formatMoney } from '@/lib/format';
import type { ManagedProperty } from '@/components/property-detail-manager';

export function PropertyManageHub({
  property,
  locale,
  portal,
}: {
  property: ManagedProperty;
  locale: 'ar' | 'en';
  portal: 'owner' | 'developer';
}) {
  const router = useRouter();
  const ar = locale === 'ar';
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const base = `/${locale}/${portal}`;
  const propertyId = encodeURIComponent(property.id);
  const publicPath = `/${locale}/properties/${property.id}`;
