/** Icon-only share row for public listings (place below booking CTAs). */
export function PublicListingShare({
  path,
  title,
  locale,
}: {
  path: string;
  title: string;
  locale: 'ar' | 'en';
}) {
  const ar = locale === 'ar';
  const [notice, setNotice] = useState<string | null>(null);

  const absoluteUrl = useMemo(() => {
    if (typeof window === 'undefined') return path;
    try {
      return new URL(path, window.location.origin).toString();
    } catch {
      return path;
    }
  }, [path]);

  const shareText = useMemo(
    () => (ar ? `${title}\nشاهده على BHD R:\n${absoluteUrl}` : `${title}\nSee it on BHD R:\n${absoluteUrl}`),
    [ar, absoluteUrl, title],
  );

  const channels: ShareChannel[] = useMemo(
    () => [
      {
        id: 'whatsapp',
        labelAr: 'واتساب',
        labelEn: 'WhatsApp',
        href: `https://wa.me/?text=${encodeURIComponent(shareText)}`,
        icon: <IconWhatsApp />,
      },
      {
        id: 'facebook',
        labelAr: 'فيسبوك',
        labelEn: 'Facebook',
        href: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(absoluteUrl)}`,
        icon: <IconFacebook />,
      },
      {
        id: 'x',
        labelAr: 'X',
        labelEn: 'X',
        href: `https://twitter.com/intent/tweet?url=${encodeURIComponent(absoluteUrl)}&text=${encodeURIComponent(title)}`,
        icon: <IconX />,
      },
      {
        id: 'telegram',
        labelAr: 'تيليجرام',
        labelEn: 'Telegram',
        href: `https://t.me/share/url?url=${encodeURIComponent(absoluteUrl)}&text=${encodeURIComponent(title)}`,
        icon: <IconTelegram />,
      },
      {
        id: 'linkedin',
        labelAr: 'لينكدإن',
        labelEn: 'LinkedIn',
        href: `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(absoluteUrl)}`,
        icon: <IconLinkedIn />,
      },
      {
        id: 'instagram',
        labelAr: 'إنستغرام',
        labelEn: 'Instagram',
        action: 'native',
        icon: <IconInstagram />,
      },
      {
        id: 'copy',
        labelAr: 'نسخ الرابط',
        labelEn: 'Copy link',
        action: 'copy',
        icon: <IconCopy />,
      },
    ],
    [absoluteUrl, shareText, title],
  );

  const flash = useCallback((message: string) => {
    setNotice(message);
    window.setTimeout(() => setNotice(null), 2_400);
  }, []);

  const onChannel = useCallback(
    async (channel: ShareChannel) => {
      if (channel.href) {
        window.open(channel.href, '_blank', 'noopener,noreferrer');
        return;
      }
      if (channel.action === 'copy') {
        try {
          await navigator.clipboard.writeText(absoluteUrl);
          flash(ar ? 'تم نسخ رابط العقار.' : 'Listing link copied.');
        } catch {
          flash(ar ? 'تعذّر النسخ.' : 'Could not copy.');
        }
        return;
      }
      if (channel.action === 'native') {
        if (typeof navigator !== 'undefined' && typeof navigator.share === 'function') {
          try {
            await navigator.share({ title, text: shareText, url: absoluteUrl });
            return;
          } catch {
            /* fall through */
          }
        }
        try {
          await navigator.clipboard.writeText(absoluteUrl);
          flash(ar ? 'تم نسخ الرابط للمشاركة.' : 'Link copied to share.');
        } catch {
          flash(ar ? 'تعذّرت المشاركة.' : 'Share unavailable.');
        }
      }
    },
    [absoluteUrl, ar, flash, shareText, title],
  );

  return (
    <div className="listing-share listing-share--icons" aria-label={ar ? 'مشاركة العقار' : 'Share listing'}>
      <div className="listing-share__grid">
        {channels.map((channel) => {
          const label = ar ? channel.labelAr : channel.labelEn;
          if (channel.href) {
            return (
              <a
                key={channel.id}
                className={`listing-share__icon listing-share__icon--${channel.id}`}
                href={channel.href}
                target="_blank"
                rel="noreferrer"
                aria-label={label}
                title={label}
              >
                {channel.icon}
              </a>
            );
          }
          return (
            <button
              key={channel.id}
              type="button"
              className={`listing-share__icon listing-share__icon--${channel.id}`}
              onClick={() => void onChannel(channel)}
              aria-label={label}
              title={label}
            >
              {channel.icon}
            </button>
          );
        })}
      </div>
      {notice ? (
        <p className="listing-share__notice" role="status">
          {notice}
        </p>
      ) : null}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { formatMoney } from '@/lib/format';
import { PublicListingShare } from '@/components/public-listing-share';

export function PublicListingActions({
  unitId,
  locale,
  signedIn,
  depositMinor,
  currency,
  canBook,
  sharePath,
  shareTitle,
}: {
  unitId: string;
  locale: 'ar' | 'en';
  signedIn: boolean;
  depositMinor: string | null;
  currency: string;
  canBook: boolean;
  sharePath: string;
  shareTitle: string;
}) {
  const router = useRouter();
  const ar = locale === 'ar';
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);

  const loginHref = `/${locale}/login?next=${encodeURIComponent(`/${locale}/units/${unitId}`)}`;
  const bookHref = `/${locale}/book/${unitId}`;

  async function requestViewing() {
    if (!signedIn) {
      router.push(loginHref);
      return;
    }
    setBusy(true);
    setError(null);
    setMessage(null);
    try {
      const response = await fetch('/api/public/viewing-requests', {
        method: 'POST',
        credentials: 'same-origin',
        headers: { 'content-type': 'application/json', accept: 'application/json' },
        body: JSON.stringify({ unitId, locale }),
      });
      const payload = (await response.json().catch(() => null)) as {
        reference?: string;
        error?: { message?: string; code?: string };
      } | null;
      if (!response.ok) {
        throw new Error(payload?.error?.message ?? payload?.error?.code ?? 'request_failed');
      }
      setMessage(
        ar
          ? `تم إرسال طلب المعاينة${payload?.reference ? ` · المرجع ${payload.reference}` : ''}.`
          : `Viewing request sent${payload?.reference ? ` · ref ${payload.reference}` : ''}.`,
      );
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : 'request_failed');
    } finally {
      setBusy(false);
    }
  }

  function startBooking() {
    if (!signedIn) {
      router.push(`/${locale}/login?next=${encodeURIComponent(bookHref)}`);
      return;
    }
    router.push(bookHref);
  }

  return (
    <div className="public-listing-actions">
      <button
        type="button"
        className="button button--primary property-360__summary-cta"
        disabled={busy}
        onClick={() => void requestViewing()}
      >
        {ar ? 'طلب معاينة' : 'Request viewing'}
      </button>
      <button
        type="button"
        className="button button--quiet property-360__summary-cta"
        disabled={busy || !canBook}
        onClick={() => startBooking()}
      >
        {ar ? 'احجز الآن' : 'Book now'}
      </button>
      {canBook && depositMinor ? (
        <p className="muted public-listing-actions__deposit">
          {ar ? 'عربون الحجز:' : 'Booking deposit:'}{' '}
          <strong dir="ltr">{formatMoney(depositMinor, currency, locale)}</strong>
        </p>
      ) : (
        <p className="muted public-listing-actions__deposit">
          {ar
            ? 'الحجز متاح بعد تحديد العربون من إدارة العقار.'
            : 'Booking opens once the owner sets a deposit.'}
        </p>
      )}
      {!signedIn ? (
        <p className="muted">
          {ar
            ? 'يلزم تسجيل الدخول لطلب المعاينة أو الحجز.'
            : 'Sign in is required to request a viewing or book.'}
        </p>
      ) : null}
      {message ? (
        <p className="notice" role="status">
          {message}
        </p>
      ) : null}
      {error ? (
        <p className="notice notice--error" role="alert">
          {error}
        </p>
      ) : null}

      <PublicListingShare path={sharePath} title={shareTitle} locale={locale} />
    </div>
  );
}

