/** Build a polished listing share message (description + link). */
export function buildListingShareText(input: {
  locale: 'ar' | 'en';
  title: string;
  description?: string | null;
  url: string;
}): string {
  const description = (input.description ?? '').trim();
  const body = description || input.title;
  if (input.locale === 'ar') {
    return [
      'شاهد هذا الإعلان من منصة BHD R:',
      '',
      body,
      '',
      'للاطلاع على تفاصيل الإعلان زُر الرابط التالي:',
      input.url,
    ].join('\n');
  }
  return [
    'Check out this listing on BHD R:',
    '',
    body,
    '',
    'View full details here:',
    input.url,
  ].join('\n');
}

/** Icon-only share row for public listings (place below booking CTAs). */
export function PublicListingShare({
  path,
  title,
  description,
  locale,
}: {
  path: string;
  title: string;
  description?: string | null;
  locale: 'ar' | 'en';
}) {
  const ar = locale === 'ar';
  const [notice, setNotice] = useState<string | null>(null);

  const absoluteUrl = useMemo(() => {
    if (typeof window === 'undefined') return path;
    try {
      return new URL(path, window.location.origin).toString();
    } catch {
      return path;
    }
  }, [path]);

  const shareText = useMemo(
    () =>
      buildListingShareText({
        locale,
        title,
        description,
        url: absoluteUrl,
      }),
    [absoluteUrl, description, locale, title],
  );

  const channels: ShareChannel[] = useMemo(
    () => [
      {
        id: 'whatsapp',
        labelAr: 'واتساب',
        labelEn: 'WhatsApp',
        href: `https://wa.me/?text=${encodeURIComponent(shareText)}`,
        icon: <IconWhatsApp />,
      },
      {
        id: 'facebook',
        labelAr: 'فيسبوك',
        labelEn: 'Facebook',
        href: `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(absoluteUrl)}&quote=${encodeURIComponent(shareText)}`,
        icon: <IconFacebook />,
      },
      {
        id: 'x',
        labelAr: 'X',
        labelEn: 'X',
        href: `https://twitter.com/intent/tweet?text=${encodeURIComponent(shareText)}`,
        icon: <IconX />,
      },
      {
        id: 'telegram',
        labelAr: 'تيليجرام',
        labelEn: 'Telegram',
        href: `https://t.me/share/url?url=${encodeURIComponent(absoluteUrl)}&text=${encodeURIComponent(shareText)}`,
        icon: <IconTelegram />,
      },
      {
        id: 'linkedin',
        labelAr: 'لينكدإن',
        labelEn: 'LinkedIn',
        href: `https://www.linkedin.com/sharing/share-offsite/?url=${encodeURIComponent(absoluteUrl)}`,
        icon: <IconLinkedIn />,
      },
      {
        id: 'instagram',
        labelAr: 'إنستغرام',
        labelEn: 'Instagram',
        action: 'native',
        icon: <IconInstagram />,
      },
      {
        id: 'copy',
        labelAr: 'نسخ الإعلان',
        labelEn: 'Copy listing',
        action: 'copy',
        icon: <IconCopy />,
      },
    ],
    [absoluteUrl, shareText],
  );

  const flash = useCallback((message: string) => {
    setNotice(message);
    window.setTimeout(() => setNotice(null), 2_400);
  }, []);

  const onChannel = useCallback(
    async (channel: ShareChannel) => {
      if (channel.href) {
        window.open(channel.href, '_blank', 'noopener,noreferrer');
        return;
      }
      if (channel.action === 'copy') {
        try {
          await navigator.clipboard.writeText(shareText);
          flash(ar ? 'تم نسخ نص الإعلان مع الرابط.' : 'Listing text and link copied.');
        } catch {
          flash(ar ? 'تعذّر النسخ.' : 'Could not copy.');
        }
        return;
      }
      if (channel.action === 'native') {
        if (typeof navigator !== 'undefined' && typeof navigator.share === 'function') {
          try {
            await navigator.share({ title, text: shareText, url: absoluteUrl });
            return;
          } catch {
            /* fall through */
          }
        }
        try {
          await navigator.clipboard.writeText(shareText);
          flash(ar ? 'تم نسخ الإعلان للمشاركة.' : 'Listing copied to share.');
        } catch {
          flash(ar ? 'تعذّرت المشاركة.' : 'Share unavailable.');
        }
      }
    },
    [absoluteUrl, ar, flash, shareText, title],
  );

  return (
    <div className="listing-share listing-share--icons" aria-label={ar ? 'مشاركة العقار' : 'Share listing'}>
      <div className="listing-share__grid">
        {channels.map((channel) => {
          const label = ar ? channel.labelAr : channel.labelEn;
          if (channel.href) {
            return (
              <a
                key={channel.id}
                className={`listing-share__icon listing-share__icon--${channel.id}`}
                href={channel.href}
                target="_blank"
                rel="noreferrer"
                aria-label={label}
                title={label}
              >
                {channel.icon}
              </a>
            );
          }
          return (
            <button
              key={channel.id}
              type="button"
              className={`listing-share__icon listing-share__icon--${channel.id}`}
              onClick={() => void onChannel(channel)}
              aria-label={label}
              title={label}
            >
              {channel.icon}
            </button>
          );
        })}
      </div>
      {notice ? (
        <p className="listing-share__notice" role="status">
          {notice}
        </p>
      ) : null}
    </div>
  );
}

