import fs from 'node:fs';
import postgres from 'postgres';

const env = fs.readFileSync('.env.vercel.local', 'utf8');
const m = env.match(/^DATABASE_URL=[REDACTED-DATABASE-URL]
if (!m) {
  console.error('no DATABASE_URL');
  process.exit(1);
}
const url = m[1].trim().replace(/^"|"$/g, '');
const sql = postgres(url, { max: 1, prepare: false });

async function run(label, fn) {
  try {
    const rows = await fn();
    console.log(label, 'ok', Array.isArray(rows) ? rows.length : rows);
    if (Array.isArray(rows)) console.log(JSON.stringify(rows.slice(0, 3), null, 2));
  } catch (e) {
    console.log(label, 'FAIL', e.message);
    console.log('code=', e.code, 'detail=', e.detail, 'hint=', e.hint);
  }
}

await sql.begin(async (tx) => {
  await tx`select set_config('app.platform_admin', 'true', true)`;
  await tx`select set_config('app.public', 'false', true)`;

  await run('role', async () =>
    tx`select current_user, current_setting('app.platform_admin', true) as pa, app_private.is_platform_admin() as is_admin`,
  );

  await run('publish_count', async () =>
    tx`select count(*)::int as n from units where publish_when_available = true`,
  );

  await run('simple', async () =>
    tx`
      select u.id::text as unit_id, p.id::text as property_id, p.status, u.status as ustatus
      from units u
      join properties p on p.id = u.property_id
      join addresses a on a.id = p.address_id
      left join listings l on l.unit_id = u.id
      where u.publish_when_available = true
        and p.status <> 'archived'
        and u.status in ('active', 'draft', 'inactive')
      limit 5
    `,
  );

  await run('media', async () =>
    tx`
      select ma.id::text, ma.processing_status, ma.scan_status, ma.mime_type
      from unit_media um
      join media_assets ma on ma.id = um.media_asset_id
      limit 3
    `,
  );

  await run('occupancy', async () =>
    tx`
      select
        u.id::text as unit_id,
        case
          when exists (
            select 1 from sales_deals sd
            where sd.unit_id = u.id and sd.status = 'closed_won'
          ) then 'sold'
