/**
 * Shared Next.js runtime env helpers (P0-04 from security review).
 * Production must never fall back to development secrets.
 */

export function isProductionRuntime(): boolean {
  return (
    process.env.NODE_ENV === 'production' ||
    process.env.VERCEL_ENV === 'production' ||
    process.env.BHD_R_FORCE_PRODUCTION === '1'
  );
}

/** Explicit opt-in for local/sandbox booking payment simulation only. */
export function isBookingSandboxAllowed(): boolean {
  if (process.env.ALLOW_BOOKING_SANDBOX === '1') return true;
  if (isProductionRuntime()) return false;
  return process.env.ALLOW_BOOKING_SANDBOX !== '0';
}

export function requireSessionSecret(): Uint8Array {
  const value = process.env.BHD_R_SESSION_SECRET?.trim();
  if (value && value.length >= 32) {
    return new TextEncoder().encode(value);
  }
  if (isProductionRuntime()) {
    throw new Error('BHD_R_SESSION_SECRET_required');
  }
  return new TextEncoder().encode('development-session-secret-at-least-32-characters');
}

export function requireOidcStateSecret(): string {
  const value =
    process.env.BHD_R_OIDC_STATE_SECRET?.trim() ||
    process.env.BHD_R_SESSION_SECRET?.trim() ||
    '';
  if (value.length >= 32) return value;
  if (isProductionRuntime()) {
    throw new Error('BHD_R_OIDC_STATE_SECRET_required');
  }
  return 'development-session-secret-at-least-32-characters';
}

import { cookies } from 'next/headers';
import { NextResponse } from 'next/server';
import { z } from 'zod';
import { verifySessionToken } from '@bhd-r/authz';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { completePublicBookingPayment } from '@/lib/public-booking-neon';
import { isBookingSandboxAllowed, requireSessionSecret } from '@/lib/runtime-env';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const bodySchema = z.object({
  sessionReference: z.string().min(16).max(80),
});

/**
 * POST /api/public/bookings/complete — sandbox-only deposit confirmation.
 * Disabled in production (P0-01). Real confirmations must come from signed payment webhooks.
 */
export async function POST(request: Request) {
  if (!isBookingSandboxAllowed()) {
    return NextResponse.json(
      {
        error: {
          code: 'sandbox_disabled',
          message: 'Booking sandbox completion is disabled outside ALLOW_BOOKING_SANDBOX.',
        },
      },
      { status: 403 },
    );
  }

  if (!hasDatabaseUrl()) {
    return NextResponse.json({ error: { code: 'db_unconfigured' } }, { status: 503 });
  }
  const token = (await cookies()).get('bhd_r_session')?.value;
  if (!token) return NextResponse.json({ error: { code: 'unauthorized' } }, { status: 401 });
  let claims: Awaited<ReturnType<typeof verifySessionToken>>;
  try {
    claims = await verifySessionToken(token, requireSessionSecret());
  } catch {
    return NextResponse.json({ error: { code: 'unauthorized' } }, { status: 401 });
  }

  let body: z.infer<typeof bodySchema>;
  try {
    body = bodySchema.parse(await request.json());
  } catch {
    return NextResponse.json({ error: { code: 'invalid_body' } }, { status: 400 });
  }

  try {
    const result = await completePublicBookingPayment(claims, body.sessionReference);
    return NextResponse.json(result);
  } catch (error) {
    const code = error instanceof Error ? error.message : 'complete_failed';
    const status = code === 'not_found' ? 404 : code === 'forbidden' ? 403 : 500;
    return NextResponse.json({ error: { code } }, { status });
  }
}

