import { createHash, timingSafeEqual } from 'node:crypto';
import { readdirSync, readFileSync, statSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';

const apiRoot = path.resolve(
  path.dirname(fileURLToPath(import.meta.url)),
  '../../src/app/api',
);

const WRITE_EXPORT =
  /export\s+(?:async\s+)?function\s+(POST|PATCH|PUT|DELETE)\b|export\s+const\s+(POST|PATCH|PUT|DELETE)\s*=/;

/** Routes that intentionally omit requireLiveSession (secret/oauth/proxy). */
const ALLOWLIST_PREFIXES = [
  path.join('auth', 'bhd'),
  path.join('cron'),
  'revalidate',
  path.join('backend'),
  'warm',
];

function listRouteFiles(dir: string): string[] {
  const out: string[] = [];
  for (const entry of readdirSync(dir)) {
    const full = path.join(dir, entry);
    if (statSync(full).isDirectory()) out.push(...listRouteFiles(full));
    else if (entry === 'route.ts') out.push(full);
  }
  return out;
}

function isAllowlisted(relative: string): boolean {
  const normalized = relative.split(path.sep).join(path.sep);
  return ALLOWLIST_PREFIXES.some(
    (prefix) => normalized === prefix || normalized.startsWith(`${prefix}${path.sep}`),
  );
}

describe('Next write-route live-session policy', () => {
  it('requires requireLiveSession on every non-allowlisted write handler', () => {
    const files = listRouteFiles(apiRoot);
    const offenders: string[] = [];
    for (const file of files) {
      const relative = path.relative(apiRoot, path.dirname(file));
      const source = readFileSync(file, 'utf8');
      if (!WRITE_EXPORT.test(source)) continue;
      if (isAllowlisted(relative)) continue;
      if (!source.includes('requireLiveSession')) {
        offenders.push(relative.replaceAll('\\', '/') || '(api root)');
      }
    }
    expect(offenders, `missing requireLiveSession:\n${offenders.join('\n')}`).toEqual([]);
  });
});

describe('cron bearer compare helper contract', () => {
  it('uses length-safe equality for secrets', () => {
    const a = Buffer.from('cron-secret-value-abcdefgh');
    const b = Buffer.from('cron-secret-value-abcdefgh');
    const c = Buffer.from('cron-secret-value-abcdefgX');
    expect(a.length === b.length && timingSafeEqual(a, b)).toBe(true);
    expect(a.length === c.length && timingSafeEqual(a, c)).toBe(false);
    expect(createHash('sha256').update('x').digest('hex')).toHaveLength(64);
  });
});

import 'server-only';
import { createHash, timingSafeEqual } from 'node:crypto';

type Bucket = { timestamps: number[] };

const globalStore = globalThis as unknown as { __bhdRRouteRateLimit?: Map<string, Bucket> };

function store(): Map<string, Bucket> {
  if (!globalStore.__bhdRRouteRateLimit) {
    globalStore.__bhdRRouteRateLimit = new Map();
  }
  return globalStore.__bhdRRouteRateLimit;
}

/** Best-effort in-memory sliding window (per isolate on serverless). */
export function assertRouteRateLimit(input: {
  key: string;
  limit: number;
  windowMs: number;
}): { ok: true } | { ok: false; retryAfterSec: number } {
  const now = Date.now();
  const buckets = store();
  const bucket = buckets.get(input.key) ?? { timestamps: [] };
  bucket.timestamps = bucket.timestamps.filter((ts) => now - ts < input.windowMs);
  if (bucket.timestamps.length >= input.limit) {
    const oldest = bucket.timestamps[0] ?? now;
    const retryAfterSec = Math.max(1, Math.ceil((input.windowMs - (now - oldest)) / 1000));
    buckets.set(input.key, bucket);
    return { ok: false, retryAfterSec };
  }
  bucket.timestamps.push(now);
  buckets.set(input.key, bucket);
  return { ok: true };
}

export function clientIp(request: Request): string {
  const forwarded = request.headers.get('x-forwarded-for');
  if (forwarded) return forwarded.split(',')[0]!.trim().slice(0, 64);
  return request.headers.get('x-real-ip')?.trim().slice(0, 64) || 'unknown';
}

/** Fail-closed cron Authorization: Bearer <CRON_SECRET>. */
export function assertCronAuthorized(request: Request):
  | { ok: true }
  | { ok: false; status: number; error: string } {
  const secret = process.env.CRON_SECRET?.trim();
  if (!secret || secret.length < 16) {
    return { ok: false, status: 503, error: 'cron_unconfigured' };
  }
  const auth = request.headers.get('authorization') ?? '';
  const expected = `Bearer ${secret}`;
  const left = Buffer.from(auth);
  const right = Buffer.from(expected);
  if (left.length !== right.length || !timingSafeEqual(left, right)) {
    return { ok: false, status: 401, error: 'unauthorized' };
  }
  return { ok: true };
}

export function hashRateKey(parts: string[]): string {
  return createHash('sha256').update(parts.join('|')).digest('hex').slice(0, 32);
}

import 'server-only';
import { randomUUID } from 'node:crypto';
import { eq, sql } from 'drizzle-orm';
import type { SessionClaims } from '@bhd-r/authz';
import { createDatabase, users } from '@bhd-r/db';
import { configuredApiOrigin, isNestApiConfiguredForRuntime, probeNestReady } from '@/lib/server-api';
import { createAuthenticatedViewingRequest } from '@/lib/public-booking-neon';

async function loadViewerContact(userId: string): Promise<{ email: string; displayName: string }> {
  const { db } = createDatabase(process.env.DATABASE_URL!, { max: 1 });
  return db.transaction(async (transaction) => {
    await transaction.execute(sql`select set_config('app.platform_admin', 'true', true)`);
    const user = await transaction.query.users.findFirst({
      where: eq(users.id, userId),
      columns: { email: true, displayName: true },
    });
    if (!user?.email) throw new Error('unauthorized');
    return {
      email: user.email.trim().toLowerCase(),
      displayName: (user.displayName || user.email).trim().slice(0, 160),
    };
  });
}

/**
 * Prefer Nest public viewing (throttled + audit) when reachable; fall back to Neon.
 */
export async function createViewingRequestNestOrNeon(
  claims: SessionClaims,
  unitId: string,
  locale: 'ar' | 'en',
): Promise<{ accepted: true; reference: string; status: string; via: 'nest' | 'neon' }> {
  const contact = await loadViewerContact(claims.sub);
  const submissionId = randomUUID();

  if (isNestApiConfiguredForRuntime() && (await probeNestReady())) {
    const origin = configuredApiOrigin();
    if (origin) {
      try {
        const response = await fetch(`${origin}/v1/public/units/${unitId}/viewing-requests`, {
          method: 'POST',
          headers: {
            accept: 'application/json',
            'content-type': 'application/json',
          },
          body: JSON.stringify({
            submissionId,
            unitId,
            displayName: contact.displayName,
            email: contact.email,
            locale,
            consent: true,
            notes: locale === 'ar' ? 'طلب معاينة من مستخدم مسجّل' : 'Viewing request from signed-in user',
          }),
          cache: 'no-store',
          signal: AbortSignal.timeout(8_000),
        });
        if (response.ok) {
          const payload = (await response.json()) as {
            accepted?: boolean;
            reference?: string;
            status?: string;
          };
          return {
            accepted: true,
            reference: payload.reference ?? `WEB-${submissionId}`,
            status: payload.status ?? 'requested',
            via: 'nest',
          };
        }
      } catch {
        /* fall through to Neon */
      }
    }
  }

  const neon = await createAuthenticatedViewingRequest(claims, unitId, locale);
  return { ...neon, via: 'neon' };
}

import { NextResponse } from 'next/server';
import { z } from 'zod';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { createViewingRequestNestOrNeon } from '@/lib/nest-or-neon-write';
import { guardErrorResponse, requireLiveSession } from '@/lib/next-route-guard';
import {
  assertRouteRateLimit,
  clientIp,
  hashRateKey,
} from '@/lib/route-rate-limit';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const bodySchema = z.object({
  unitId: z.string().uuid(),
  locale: z.enum(['ar', 'en']).default('ar'),
});

/** POST /api/public/viewing-requests — Nest-first with Neon fallback. */
export async function POST(request: Request) {
  if (!hasDatabaseUrl()) {
    return NextResponse.json({ error: { code: 'db_unconfigured' } }, { status: 503 });
  }

  let claims;
  try {
    claims = await requireLiveSession(request, { requireCsrf: true });
  } catch (error) {
    const mapped = guardErrorResponse(error);
    return NextResponse.json(mapped.body, { status: mapped.status });
  }

  const limited = assertRouteRateLimit({
    key: hashRateKey(['viewing', claims.sub, clientIp(request)]),
    limit: 5,
    windowMs: 60_000,
  });
  if (!limited.ok) {
    return NextResponse.json(
      { error: { code: 'rate_limited' } },
      { status: 429, headers: { 'retry-after': String(limited.retryAfterSec) } },
    );
  }

  let body: z.infer<typeof bodySchema>;
  try {
    body = bodySchema.parse(await request.json());
  } catch {
    return NextResponse.json({ error: { code: 'invalid_body' } }, { status: 400 });
  }

  try {
    const result = await createViewingRequestNestOrNeon(claims, body.unitId, body.locale);
    return NextResponse.json(result);
  } catch (error) {
    const code = error instanceof Error ? error.message : 'request_failed';
    const status =
      code === 'unit_unavailable' || code === 'not_found'
        ? 404
        : code === 'forbidden' || code === 'unauthorized'
          ? code === 'unauthorized'
            ? 401
            : 403
          : 500;
    return NextResponse.json({ error: { code } }, { status });
  }
}

