import { NextResponse } from 'next/server';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { loadPublicPropertyMediaBytes } from '@/lib/load-public-property-neon';
import {
  assertRouteRateLimit,
  clientIp,
  hashRateKey,
} from '@/lib/route-rate-limit';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';
export const maxDuration = 30;

/** GET /api/public/media/:assetId — stream gallery images for public property pages. */
export async function GET(
  request: Request,
  context: { params: Promise<{ assetId: string }> },
) {
  if (!hasDatabaseUrl()) {
    return NextResponse.json({ error: { code: 'db_unconfigured' } }, { status: 503 });
  }

  const limited = assertRouteRateLimit({
    key: hashRateKey(['public-media', clientIp(request)]),
    limit: 120,
    windowMs: 60_000,
  });
  if (!limited.ok) {
    return NextResponse.json(
      { error: { code: 'rate_limited' } },
      { status: 429, headers: { 'retry-after': String(limited.retryAfterSec) } },
    );
  }

  const { assetId } = await context.params;
  try {
    const media = await loadPublicPropertyMediaBytes(assetId);
    if (!media) {
      return NextResponse.json({ error: { code: 'not_found' } }, { status: 404 });
    }
    if (!media.mimeType.startsWith('image/')) {
      return NextResponse.json({ error: { code: 'not_found' } }, { status: 404 });
    }
    if (media.bytes.byteLength > 12 * 1024 * 1024) {
      return NextResponse.json({ error: { code: 'too_large' } }, { status: 413 });
    }
    return new NextResponse(new Uint8Array(media.bytes), {
      status: 200,
      headers: {
        'content-type': media.mimeType,
        'content-disposition': 'inline',
        'x-content-type-options': 'nosniff',
        'cache-control': 'public, max-age=86400, stale-while-revalidate=604800',
      },
    });
  } catch (error) {
    console.error('GET /api/public/media failed', error);
    return NextResponse.json({ error: { code: 'read_failed' } }, { status: 500 });
  }
}

import { NextResponse } from 'next/server';
import { configuredApiOrigin, isNestApiConfiguredForRuntime } from '@/lib/server-api';
import { assertCronAuthorized } from '@/lib/route-rate-limit';

export const dynamic = 'force-dynamic';
export const maxDuration = 30;

/**
 * Vercel Cron: ping Nest /healthz so Render does not stay cold between visits.
 * Requires CRON_SECRET (fail-closed) — Vercel sends Authorization: Bearer <CRON_SECRET>.
 */
export async function GET(request: Request) {
  const auth = assertCronAuthorized(request);
  if (!auth.ok) {
    return NextResponse.json({ ok: false, error: auth.error }, { status: auth.status });
  }
  if (!isNestApiConfiguredForRuntime()) {
    return NextResponse.json({ ok: false, error: 'nest_not_configured' }, { status: 503 });
  }
  const origin = configuredApiOrigin();
  if (!origin) {
    return NextResponse.json({ ok: false, error: 'missing_api_origin' }, { status: 503 });
  }

  const started = Date.now();
  try {
    const response = await fetch(`${origin}/healthz`, {
      headers: { accept: 'application/json' },
      cache: 'no-store',
      signal: AbortSignal.timeout(25_000),
    });
    return NextResponse.json({
      ok: response.ok,
      status: response.status,
      ms: Date.now() - started,
    });
  } catch {
    return NextResponse.json(
      {
        ok: false,
        error: 'warmup_failed',
        ms: Date.now() - started,
      },
      { status: 503 },
    );
  }
}

import { NextResponse } from 'next/server';
import { sql } from 'drizzle-orm';
import { createDatabase } from '@bhd-r/db';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { assertCronAuthorized } from '@/lib/route-rate-limit';

export const dynamic = 'force-dynamic';
export const maxDuration = 30;

/**
 * Vercel Cron: expire timed-out holds and reservations globally.
 * Requires CRON_SECRET (fail-closed) — Vercel sends Authorization: Bearer <CRON_SECRET>.
 */
export async function GET(request: Request) {
  const auth = assertCronAuthorized(request);
  if (!auth.ok) {
    return NextResponse.json({ ok: false, error: auth.error }, { status: auth.status });
  }
  if (!hasDatabaseUrl()) {
    return NextResponse.json({ ok: false, error: 'db_unconfigured' }, { status: 503 });
  }

  const started = Date.now();
  try {
    const { db } = createDatabase(process.env.DATABASE_URL!, { max: 1 });
    const result = await db.transaction(async (transaction) => {
      await transaction.execute(sql`select set_config('app.platform_admin', 'true', true)`);
      await transaction.execute(sql`
        update holds
        set status = 'expired', updated_at = now()
        where status = 'active' and expires_at <= now()
      `);
      await transaction.execute(sql`
        update reservations
        set status = 'expired', updated_at = now()
        where status in ('pending', 'confirmed') and expires_at <= now()
      `);
      return { expired: true as const };
    });
    return NextResponse.json({ ok: true, ...result, ms: Date.now() - started });
  } catch (error) {
    console.error('[cron/expire-locks]', error);
    return NextResponse.json(
      { ok: false, error: 'expire_failed', ms: Date.now() - started },
      { status: 503 },
    );
  }
}

