/**
 * Map thrown errors to client-safe codes — never echo raw DB/driver messages (P2-04).
 */
const KNOWN_CODES = new Set([
  'forbidden',
  'unauthorized',
  'not_found',
  'invalid_body',
  'invalid_file',
  'unit_unavailable',
  'deposit_not_set',
  'organization_required',
  'owner_not_found',
  'property_not_found',
  'property_archived',
  'duplicate_property',
  'single_unit_requires_one_unit',
  'multi_unit_requires_units',
  'idempotency_payload_mismatch',
  'no_units',
  'rate_limited',
  'storage_unavailable',
  'inline_too_large',
  'db_unconfigured',
  'csrf_rejected',
  'sandbox_disabled',
  'unit_not_found',
]);

export function clientSafeErrorCode(error: unknown, fallback = 'request_failed'): string {
  if (!(error instanceof Error)) return fallback;
  const code = error.message.trim();
  if (KNOWN_CODES.has(code)) return code;
  // Never return Postgres codes, stack fragments, or SQL text to the browser.
  if (/^[a-z][a-z0-9_]{2,64}$/i.test(code) && !/\s/.test(code) && code.length <= 64) {
    // Allowlist only known snake_case domain codes already in the set.
    return fallback;
  }
  return fallback;
}

export function statusForSafeCode(code: string): number {
  switch (code) {
    case 'unauthorized':
    case 'csrf_rejected':
      return 401;
    case 'forbidden':
    case 'sandbox_disabled':
      return 403;
    case 'not_found':
    case 'unit_unavailable':
    case 'owner_not_found':
    case 'property_not_found':
    case 'no_units':
    case 'unit_not_found':
      return 404;
    case 'deposit_not_set':
    case 'property_archived':
    case 'duplicate_property':
    case 'single_unit_requires_one_unit':
    case 'multi_unit_requires_units':
    case 'idempotency_payload_mismatch':
      return 409;
    case 'invalid_body':
    case 'invalid_file':
    case 'organization_required':
      return 400;
    case 'rate_limited':
      return 429;
    case 'db_unconfigured':
    case 'storage_unavailable':
      return 503;
    default:
      return 500;
  }
}

import { describe, expect, it } from 'vitest';
import { clientSafeErrorCode, statusForSafeCode } from '@/lib/client-safe-error';

describe('clientSafeErrorCode', () => {
  it('keeps known domain codes', () => {
    expect(clientSafeErrorCode(new Error('forbidden'))).toBe('forbidden');
    expect(clientSafeErrorCode(new Error('unit_unavailable'))).toBe('unit_unavailable');
  });

  it('redacts raw driver / SQL messages', () => {
    expect(clientSafeErrorCode(new Error('column "serial_number" does not exist'))).toBe(
      'request_failed',
    );
    expect(clientSafeErrorCode(new Error('42703'))).toBe('request_failed');
    expect(clientSafeErrorCode(new Error('password authentication failed'))).toBe(
      'request_failed',
    );
  });

  it('maps statuses', () => {
    expect(statusForSafeCode('forbidden')).toBe(403);
    expect(statusForSafeCode('rate_limited')).toBe(429);
    expect(statusForSafeCode('request_failed')).toBe(500);
  });
});

