function escapeXml(value: string): string {
  return value.replace(/[<>&"']/g, (character) => {
    const replacements: Record<string, string> = {
      '<': '&lt;',
      '>': '&gt;',
      '&': '&amp;',
      '"': '&quot;',
      "'": '&apos;',
    };
    return replacements[character] ?? '';
