  where u.publish_when_available = true
    and p.status <> 'archived'
    and u.status in ('active', 'draft', 'inactive')
    ${countryClause}
    ${governorateClause}
    ${wilayatClause}
    ${villageClause}
    ${categoryClause}
    ${bedroomsClause}
    ${currencyClause}
    ${purposeClause}
    ${priceMinClause}
    ${priceMaxClause}
  order by l.published_at desc nulls last, u.updated_at desc, u.id desc
  limit ${limit}
`);

