  Number.isFinite(Number(row.longitude))
    ? Number(row.longitude)
    : null;
let mapsUrl = mapsUrlFromNotes(row.maps_note);
if (!mapsUrl && latitude !== null && longitude !== null) {
  mapsUrl = googleMapsLinkFromCoords(latitude, longitude);
