import 'server-only';
import { and, desc, eq, sql } from 'drizzle-orm';
import { createDatabase, reviews, type Database } from '@bhd-r/db';

type DbHandle = { db: Database };
const globalForDb = globalThis as unknown as { __bhdRReviewsDb?: DbHandle };

function getDatabase(): DbHandle {
  const url = process.env.DATABASE_URL;
  if (!url) throw new Error('DATABASE_URL is required');
  if (!globalForDb.__bhdRReviewsDb) {
    const { db } = createDatabase(url, { max: 2 });
    globalForDb.__bhdRReviewsDb = { db };
  }
  return globalForDb.__bhdRReviewsDb;
}

export type ReviewTargetType = 'property' | 'party' | 'organization';

export type PublicReview = {
  id: string;
  targetType: ReviewTargetType;
  targetId: string;
  rating: number;
  body: string | null;
  verifiedStay: boolean;
  verifiedRole: string | null;
  authorPartyId: string | null;
  authorLabel: string;
  createdAt: string;
};

export type ReviewSummary = {
  avgRating: number | null;
  reviewCount: number;
  verifiedCount: number;
};

async function withAdmin<T>(fn: (db: Database) => Promise<T>): Promise<T> {
  const { db } = getDatabase();
  return db.transaction(async (tx) => {
    await tx.execute(sql`select set_config('app.platform_admin', 'true', true)`);
    await tx.execute(sql`select set_config('app.public', 'false', true)`);
    return fn(tx as unknown as Database);
  });
}

export async function getReviewSummary(
  targetType: ReviewTargetType,
  targetId: string,
): Promise<ReviewSummary> {
  return withAdmin(async (db) => {
    const rows = await db
      .select({
        avg: sql<string>`avg(${reviews.rating})`,
        count: sql<string>`count(*)`,
        verified: sql<string>`count(*) filter (where ${reviews.verifiedStay})`,
      })
      .from(reviews)
      .where(
        and(
          eq(reviews.targetType, targetType),
          eq(reviews.targetId, targetId),
          eq(reviews.status, 'published'),
        ),
      );
    const row = rows[0];
    const count = Number(row?.count ?? 0);
    const avg =
      count > 0 && row?.avg !== null && row?.avg !== undefined
        ? Math.round(Number(row.avg) * 10) / 10
        : null;
    return {
      avgRating: avg,
      reviewCount: count,
      verifiedCount: Number(row?.verified ?? 0),
    };
  });
}

export async function listPublishedReviews(
  targetType: ReviewTargetType,
  targetId: string,
  limit = 40,
): Promise<PublicReview[]> {
  return withAdmin(async (db) => {
    const rows = await db
      .select({
        id: reviews.id,
        targetType: reviews.targetType,
        targetId: reviews.targetId,
        rating: reviews.rating,
        body: reviews.body,
        verifiedStay: reviews.verifiedStay,
        verifiedRole: reviews.verifiedRole,
        authorPartyId: reviews.authorPartyId,
        createdAt: reviews.createdAt,
        authorUserId: reviews.authorUserId,
      })
      .from(reviews)
      .where(
        and(
          eq(reviews.targetType, targetType),
          eq(reviews.targetId, targetId),
          eq(reviews.status, 'published'),
        ),
      )
      .orderBy(desc(reviews.createdAt))
      .limit(limit);

    return rows.map((row) => ({
      id: row.id,
      targetType: row.targetType,
      targetId: row.targetId,
      rating: row.rating,
      body: row.body,
      verifiedStay: row.verifiedStay,
      verifiedRole: row.verifiedRole,
      authorPartyId: row.authorPartyId,
      authorLabel: row.authorPartyId
        ? `Party ${row.authorPartyId.slice(0, 8)}`
        : `User ${row.authorUserId.slice(0, 8)}`,
      createdAt: row.createdAt.toISOString(),
    }));
  });
}

export type VerifiedContext = {
  verifiedStay: boolean;
  verifiedRole: 'tenant' | 'buyer' | 'owner' | null;
  organizationId: string;
};

/** Resolve org + verification badge for a review target. */
export async function resolveReviewContext(input: {
  targetType: ReviewTargetType;
  targetId: string;
  authorUserId: string;
  authorPartyId?: string | null;
}): Promise<VerifiedContext> {
  return withAdmin(async (db) => {
    if (input.targetType === 'organization') {
      return {
        verifiedStay: false,
        verifiedRole: null,
        organizationId: input.targetId,
      };
    }

    if (input.targetType === 'property') {
      const prop = await db.execute(sql`
        select organization_id::text as organization_id, owner_party_id::text as owner_party_id
        from properties where id = ${input.targetId}::uuid limit 1
      `);
      const row = (Array.isArray(prop) ? prop[0] : (prop as { rows?: unknown[] }).rows?.[0]) as
        | { organization_id?: string; owner_party_id?: string }
        | undefined;
      if (!row?.organization_id) throw new Error('target_not_found');

      let verifiedRole: VerifiedContext['verifiedRole'] = null;
      if (input.authorPartyId && row.owner_party_id === input.authorPartyId) {
        verifiedRole = 'owner';
      } else if (input.authorPartyId) {
        const lease = await db.execute(sql`
          select 1 from leases le
          join units u on u.id = le.unit_id
          where u.property_id = ${input.targetId}::uuid
            and le.tenant_party_id = ${input.authorPartyId}::uuid
            and le.status::text in ('active', 'ended', 'clearance_pending', 'cancel_requested')
          limit 1
        `);
        const leaseHit = Array.isArray(lease)
          ? lease[0]
          : (lease as { rows?: unknown[] }).rows?.[0];
        if (leaseHit) verifiedRole = 'tenant';
        else {
          const sale = await db.execute(sql`
            select 1 from sales_deals sd
            join units u on u.id = sd.unit_id
            where u.property_id = ${input.targetId}::uuid
              and sd.buyer_party_id = ${input.authorPartyId}::uuid
              and sd.status::text = 'closed_won'
            limit 1
          `);
          const saleHit = Array.isArray(sale)
            ? sale[0]
            : (sale as { rows?: unknown[] }).rows?.[0];
          if (saleHit) verifiedRole = 'buyer';
        }
      }
      return {
        verifiedStay: verifiedRole === 'tenant' || verifiedRole === 'buyer' || verifiedRole === 'owner',
        verifiedRole,
        organizationId: row.organization_id,
      };
    }

    // party target — owner reviewing tenant or reverse
    const party = await db.execute(sql`
      select organization_id::text as organization_id from parties where id = ${input.targetId}::uuid limit 1
    `);
    const partyRow = (
      Array.isArray(party) ? party[0] : (party as { rows?: unknown[] }).rows?.[0]
    ) as { organization_id?: string } | undefined;
    if (!partyRow?.organization_id) throw new Error('target_not_found');

    let verifiedRole: VerifiedContext['verifiedRole'] = null;
    if (input.authorPartyId) {
      const leaseAsOwner = await db.execute(sql`
        select 1 from leases
        where owner_party_id = ${input.authorPartyId}::uuid
          and tenant_party_id = ${input.targetId}::uuid
          and status::text in ('active', 'ended', 'clearance_pending', 'cancel_requested')
        limit 1
      `);
      const ownerHit = Array.isArray(leaseAsOwner)
        ? leaseAsOwner[0]
        : (leaseAsOwner as { rows?: unknown[] }).rows?.[0];
      if (ownerHit) verifiedRole = 'owner';
      else {
        const leaseAsTenant = await db.execute(sql`
          select 1 from leases
          where tenant_party_id = ${input.authorPartyId}::uuid
            and owner_party_id = ${input.targetId}::uuid
            and status::text in ('active', 'ended', 'clearance_pending', 'cancel_requested')
          limit 1
        `);
        const tenantHit = Array.isArray(leaseAsTenant)
          ? leaseAsTenant[0]
          : (leaseAsTenant as { rows?: unknown[] }).rows?.[0];
        if (tenantHit) verifiedRole = 'tenant';
      }
    }

    return {
      verifiedStay: Boolean(verifiedRole),
      verifiedRole,
      organizationId: partyRow.organization_id,
    };
  });
}

export async function upsertReview(input: {
  targetType: ReviewTargetType;
  targetId: string;
  authorUserId: string;
  authorPartyId?: string | null;
  rating: number;
  body?: string | null;
}): Promise<PublicReview> {
  const ctx = await resolveReviewContext(input);
  return withAdmin(async (db) => {
    await db
      .insert(reviews)
      .values({
        organizationId: ctx.organizationId,
        authorUserId: input.authorUserId,
        authorPartyId: input.authorPartyId ?? null,
        targetType: input.targetType,
        targetId: input.targetId,
        rating: input.rating,
        body: input.body?.trim() || null,
        verifiedStay: ctx.verifiedStay,
        verifiedRole: ctx.verifiedRole,
        status: 'published',
        updatedAt: new Date(),
      })
      .onConflictDoUpdate({
        target: [reviews.authorUserId, reviews.targetType, reviews.targetId],
        set: {
          rating: input.rating,
          body: input.body?.trim() || null,
          verifiedStay: ctx.verifiedStay,
          verifiedRole: ctx.verifiedRole,
          status: 'published',
          updatedAt: new Date(),
        },
      });

    const [row] = await db
      .select()
      .from(reviews)
      .where(
        and(
          eq(reviews.authorUserId, input.authorUserId),
          eq(reviews.targetType, input.targetType),
          eq(reviews.targetId, input.targetId),
        ),
      )
      .limit(1);
    if (!row) throw new Error('review_failed');
    return {
      id: row.id,
      targetType: row.targetType,
      targetId: row.targetId,
      rating: row.rating,
      body: row.body,
      verifiedStay: row.verifiedStay,
      verifiedRole: row.verifiedRole,
      authorPartyId: row.authorPartyId,
      authorLabel: 'You',
      createdAt: row.createdAt.toISOString(),
    };
  });
}

import { NextResponse } from 'next/server';
import { z } from 'zod';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { guardErrorResponse, requireLiveSession } from '@/lib/next-route-guard';
import { assertRouteRateLimit, clientIp, hashRateKey } from '@/lib/route-rate-limit';
import {
  getReviewSummary,
  listPublishedReviews,
  upsertReview,
  type ReviewTargetType,
} from '@/lib/reviews';

export const runtime = 'nodejs';
export const dynamic = 'force-dynamic';

const targetTypeSchema = z.enum(['property', 'party', 'organization']);

export async function GET(request: Request) {
  if (!hasDatabaseUrl()) {
    return NextResponse.json({ error: 'db_unconfigured' }, { status: 503 });
  }
  const url = new URL(request.url);
  const targetType = targetTypeSchema.safeParse(url.searchParams.get('targetType'));
  const targetId = url.searchParams.get('targetId');
  if (!targetType.success || !targetId || !z.string().uuid().safeParse(targetId).success) {
    return NextResponse.json({ error: 'invalid_query' }, { status: 400 });
  }

  try {
    const [summary, items] = await Promise.all([
      getReviewSummary(targetType.data, targetId),
      listPublishedReviews(targetType.data, targetId),
    ]);
    return NextResponse.json({ summary, data: items });
  } catch (error) {
    console.error('[reviews] GET failed', error);
    return NextResponse.json({ error: 'reviews_failed', summary: { avgRating: null, reviewCount: 0, verifiedCount: 0 }, data: [] }, { status: 500 });
  }
}

const postSchema = z.object({
  targetType: targetTypeSchema,
  targetId: z.string().uuid(),
  rating: z.number().int().min(1).max(5),
  body: z.string().trim().max(2000).optional().nullable(),
});

export async function POST(request: Request) {
  if (!hasDatabaseUrl()) {
    return NextResponse.json({ error: { code: 'db_unconfigured' } }, { status: 503 });
  }

  let claims;
  try {
    claims = await requireLiveSession(request, { requireCsrf: true });
  } catch (error) {
    const mapped = guardErrorResponse(error);
    return NextResponse.json(mapped.body, { status: mapped.status });
  }

  const limited = assertRouteRateLimit({
    key: hashRateKey(['review', claims.sub, clientIp(request)]),
    limit: 20,
    windowMs: 60_000,
  });
  if (!limited.ok) {
    return NextResponse.json(
      { error: { code: 'rate_limited' } },
      { status: 429, headers: { 'retry-after': String(limited.retryAfterSec) } },
    );
  }

  let body: z.infer<typeof postSchema>;
  try {
    body = postSchema.parse(await request.json());
  } catch {
    return NextResponse.json({ error: { code: 'invalid_body' } }, { status: 400 });
  }

  try {
    const review = await upsertReview({
      targetType: body.targetType as ReviewTargetType,
      targetId: body.targetId,
      authorUserId: claims.sub,
      authorPartyId: claims.partyId ?? null,
      rating: body.rating,
      body: body.body ?? null,
    });
    const summary = await getReviewSummary(body.targetType, body.targetId);
    return NextResponse.json({ review, summary });
  } catch (error) {
    const message = error instanceof Error ? error.message : 'review_failed';
    const code = message === 'target_not_found' ? 'target_not_found' : 'review_failed';
    return NextResponse.json({ error: { code } }, { status: code === 'target_not_found' ? 404 : 500 });
  }
}

import type { CatalogueListing } from '@/lib/listing-market-status';
import type { ManagedProperty } from '@/components/property-detail-manager';
import {
  searchPublicListingsFromNeon,
  type PublicListingSearchInput,
} from '@/lib/search-public-listings-neon';

export type AiTag = { ar: string; en: string };

export function buildAiTags(property: ManagedProperty): AiTag[] {
  const unit = property.units[0];
  const tags: AiTag[] = [];
  const purpose = unit?.listingPurpose;
  if (purpose === 'rent' || purpose === 'both') tags.push({ ar: 'للإيجار', en: 'For rent' });
  if (purpose === 'sale' || purpose === 'both') tags.push({ ar: 'للبيع', en: 'For sale' });
  tags.push({ ar: property.category, en: property.category });
  if (unit) {
    tags.push({ ar: `${unit.bedrooms} غرف`, en: `${unit.bedrooms} bedrooms` });
    tags.push({ ar: `${unit.bathrooms} حمّامات`, en: `${unit.bathrooms} baths` });
  }
  if (property.profile?.furnishing === 'furnished') {
    tags.push({ ar: 'مفروش', en: 'Furnished' });
  } else if (property.profile?.furnishing === 'unfurnished') {
    tags.push({ ar: 'غير مفروش', en: 'Unfurnished' });
  }
  for (const amenity of property.amenities ?? []) {
    tags.push({ ar: amenity.labelAr, en: amenity.labelEn });
  }
  if (property.address?.wilayat) {
    tags.push({ ar: property.address.wilayat, en: property.address.wilayat });
  }
  return tags.slice(0, 16);
}

export type PropertyDiscoveryRails = {
  similar: CatalogueListing[];
  recommended: CatalogueListing[];
  topRated: CatalogueListing[];
};

export async function loadPropertyDiscoveryRails(
  property: ManagedProperty,
): Promise<PropertyDiscoveryRails> {
  const unit = property.units[0];
  const purpose =
    unit?.listingPurpose === 'sale' || unit?.listingPurpose === 'rent'
      ? unit.listingPurpose
      : undefined;

  const base: PublicListingSearchInput = {
    limit: 12,
    excludePropertyId: property.id,
  };
  if (property.address?.countryCode) base.countryCode = property.address.countryCode;
  if (purpose) base.purpose = purpose;

  const similarInput: PublicListingSearchInput = {
    ...base,
    governorate: property.address?.governorate,
    wilayat: property.address?.wilayat,
    category: property.category as PublicListingSearchInput['category'],
  };

  const [similarRes, recommendedRes, poolRes] = await Promise.all([
    searchPublicListingsFromNeon(similarInput).catch(() => ({ data: [] as CatalogueListing[] })),
    searchPublicListingsFromNeon({
      ...base,
      governorate: property.address?.governorate,
      bedroomsMin: unit?.bedrooms ? Math.max(0, unit.bedrooms - 1) : undefined,
    }).catch(() => ({ data: [] as CatalogueListing[] })),
    searchPublicListingsFromNeon({
      ...base,
      governorate: property.address?.governorate,
      limit: 24,
    }).catch(() => ({ data: [] as CatalogueListing[] })),
  ]);

  const amenityCodes = new Set((property.amenities ?? []).map((a) => a.code));
  const recommended = [...recommendedRes.data]
    .map((item) => {
      const overlap = (item.amenities ?? []).filter((code) => amenityCodes.has(code)).length;
      const bedScore =
        unit && item.bedrooms != null ? Math.max(0, 3 - Math.abs(item.bedrooms - unit.bedrooms)) : 0;
      return { item, score: overlap * 2 + bedScore };
    })
    .sort((a, b) => b.score - a.score)
    .map((row) => row.item)
    .slice(0, 8);

  const topRated = [...poolRes.data]
    .filter((item) => (item.reviewCount ?? 0) > 0 || (item.avgRating ?? 0) > 0)
    .sort((a, b) => (b.avgRating ?? 0) - (a.avgRating ?? 0) || (b.reviewCount ?? 0) - (a.reviewCount ?? 0))
    .slice(0, 8);

  // Fallback if no ratings yet: newest from pool
  const topRatedFinal =
    topRated.length > 0
      ? topRated
      : [...poolRes.data]
          .sort((a, b) => new Date(b.publishedAt).getTime() - new Date(a.publishedAt).getTime())
          .slice(0, 8);

  return {
    similar: similarRes.data.slice(0, 8),
    recommended: recommended.slice(0, 8),
    topRated: topRatedFinal,
  };
}

'use client';

import { useEffect, useMemo, useRef } from 'react';
import type { Map as LeafletMap, Marker as LeafletMarker } from 'leaflet';
import type { CatalogueListing } from '@/lib/listing-market-status';
import { formatMoney, localizedName } from '@/lib/format';

export function PropertiesMapPanel({
  open,
  locale,
  listings,
  selectedId,
  onSelect,
  onClose,
}: {
  open: boolean;
  locale: string;
  listings: CatalogueListing[];
  selectedId: string | null;
  onSelect: (listing: CatalogueListing) => void;
  onClose: () => void;
}) {
  const ar = locale === 'ar';
  const mapNode = useRef<HTMLDivElement | null>(null);
  const mapRef = useRef<LeafletMap | null>(null);
  const markersRef = useRef<Map<string, LeafletMarker>>(new Map());

  const pinned = useMemo(
    () =>
      listings.filter(
        (item) =>
          typeof item.latitude === 'number' &&
          typeof item.longitude === 'number' &&
          Number.isFinite(item.latitude) &&
          Number.isFinite(item.longitude),
      ),
    [listings],
  );

  useEffect(() => {
    if (!open) return;
    let cancelled = false;

    void (async () => {
      const L = (await import('leaflet')).default;
      await import('leaflet/dist/leaflet.css');
      if (cancelled || !mapNode.current) return;

      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
        markersRef.current.clear();
      }

      const center: [number, number] =
        pinned[0] && pinned[0].latitude != null && pinned[0].longitude != null
          ? [pinned[0].latitude, pinned[0].longitude]
          : [23.588, 58.3829];

      const map = L.map(mapNode.current, {
        center,
        zoom: pinned.length ? 12 : 10,
        scrollWheelZoom: true,
      });
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; OpenStreetMap',
        maxZoom: 19,
      }).addTo(map);
      mapRef.current = map;

      const bounds: [number, number][] = [];
      for (const listing of pinned) {
        const lat = listing.latitude!;
        const lng = listing.longitude!;
        bounds.push([lat, lng]);
        const price =
          listing.listingPurpose === 'sale' && listing.salePrice
            ? formatMoney(listing.salePrice.amountMinor, listing.salePrice.currency, locale)
            : formatMoney(listing.rent.amountMinor, listing.rent.currency, locale);
        const title = localizedName(locale, listing.propertyNameAr, listing.propertyNameEn);
        const icon = L.divIcon({
          className: `props-map-pin${selectedId === listing.id ? ' is-active' : ''}`,
          html: `<span>${price}</span>`,
          iconSize: [72, 28],
          iconAnchor: [36, 28],
        });
        const marker = L.marker([lat, lng], { icon }).addTo(map);
        marker.bindPopup(`<strong>${title}</strong><br/>${price}`);
        marker.on('click', () => onSelect(listing));
        markersRef.current.set(listing.id, marker);
      }
      if (bounds.length > 1) {
        map.fitBounds(bounds, { padding: [40, 40] });
      } else if (bounds.length === 1) {
        map.setView(bounds[0]!, 15);
      }
    })();

    return () => {
      cancelled = true;
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
        markersRef.current.clear();
      }
    };
  }, [open, pinned, locale, onSelect, selectedId]);

  useEffect(() => {
    if (!open || !mapRef.current) return;
    for (const [id, marker] of markersRef.current) {
      const el = marker.getElement();
      if (el) el.classList.toggle('is-active', id === selectedId);
    }
    const selected = pinned.find((item) => item.id === selectedId);
    if (selected?.latitude != null && selected.longitude != null) {
      mapRef.current.panTo([selected.latitude, selected.longitude]);
    }
  }, [selectedId, open, pinned]);

  if (!open) return null;

  return (
    <div className="props-map-overlay" role="dialog" aria-modal="true" aria-label={ar ? 'الخريطة' : 'Map'}>
      <div className="props-map-overlay__toolbar">
        <div>
          <strong>{ar ? 'اعرض على الخريطة' : 'Show on map'}</strong>
          <p>
            {ar
              ? `${pinned.length} عقار بموقع محفوظ · ${listings.length - pinned.length} بدون إحداثيات`
              : `${pinned.length} with saved location · ${listings.length - pinned.length} without coords`}
          </p>
        </div>
        <button type="button" className="button button--secondary" onClick={onClose}>
          {ar ? 'إغلاق الخريطة' : 'Close map'}
        </button>
      </div>
      <div className="props-map-overlay__body">
        <div ref={mapNode} className="props-map-overlay__canvas" />
        <aside className="props-map-overlay__list">
          {listings.map((listing) => {
            const title = localizedName(locale, listing.propertyNameAr, listing.propertyNameEn);
            const hasPin =
              typeof listing.latitude === 'number' && typeof listing.longitude === 'number';
            return (
              <button
                key={listing.id}
                type="button"
                className={
                  selectedId === listing.id
                    ? 'props-map-card is-active'
                    : 'props-map-card'
                }
                onClick={() => onSelect(listing)}
              >
                <strong>{title}</strong>
                <span>
                  {listing.governorate}
                  {listing.wilayat ? ` · ${listing.wilayat}` : ''}
                </span>
                {!hasPin ? (
                  <em>{ar ? 'بدون موقع على الخريطة' : 'No map pin'}</em>
                ) : null}
              </button>
            );
          })}
        </aside>
      </div>
    </div>
  );
}

import { Link } from '@/i18n/navigation';
import { formatMoney, localizedName } from '@/lib/format';
import type { CatalogueListing } from '@/lib/listing-market-status';
import type { AiTag } from '@/lib/property-discovery';

function RailCard({ listing, locale }: { listing: CatalogueListing; locale: string }) {
  const ar = locale === 'ar';
  const title = localizedName(locale, listing.propertyNameAr, listing.propertyNameEn);
  const href = listing.propertyId ? `/properties/${listing.propertyId}` : `/units/${listing.unitId}`;
  const price =
    listing.listingPurpose === 'sale' && listing.salePrice
      ? formatMoney(listing.salePrice.amountMinor, listing.salePrice.currency, locale)
      : formatMoney(listing.rent.amountMinor, listing.rent.currency, locale);

  return (
    <Link href={href} className="discovery-card" prefetch>
      <div
        className="discovery-card__img"
        style={
          listing.coverImageUrl
            ? { backgroundImage: `url(${listing.coverImageUrl})` }
            : undefined
        }
      />
      <div className="discovery-card__body">
