/**
 * BHD R Stays feature flags — closed by default at every scope.
 * Phase 0: definitions + resolution only. No public routes or Nest modules yet.
 */

export type StaysFlagScope = {
  /** Platform kill-switch (env STAYS_PLATFORM_ENABLED). */
  platformEnabled?: boolean;
  /** Organization allow-list (env STAYS_ORG_ALLOWLIST comma UUIDs) or future DB. */
  organizationId?: string | null;
  organizationEnabled?: boolean;
  /** Property / unit overrides once stay_profiles exist (Phase 1+). */
  propertyEnabled?: boolean;
  unitEnabled?: boolean;
};

export type StaysFlagResolution = {
  /** True only when every applicable layer allows stays. */
  enabled: boolean;
  platform: boolean;
  organization: boolean;
  property: boolean;
  unit: boolean;
  reason: 'platform_off' | 'organization_off' | 'property_off' | 'unit_off' | 'enabled';
};

function parseBoolFlag(raw: string | undefined, defaultValue = false): boolean {
  if (raw == null || raw.trim() === '') return defaultValue;
  const value = raw.trim().toLowerCase();
  if (['1', 'true', 'yes', 'on'].includes(value)) return true;
  if (['0', 'false', 'no', 'off'].includes(value)) return false;
  return defaultValue;
}

function parseAllowlist(raw: string | undefined): Set<string> {
  if (!raw?.trim()) return new Set();
  return new Set(
    raw
      .split(',')
      .map((part) => part.trim().toLowerCase())
      .filter(Boolean),
  );
}

/** Read platform + org allow-list from process env (defaults: all off). */
export function readStaysFlagsFromEnv(
  source: NodeJS.ProcessEnv = process.env,
): Pick<StaysFlagScope, 'platformEnabled'> & { organizationAllowlist: Set<string> } {
  return {
    platformEnabled: parseBoolFlag(source.STAYS_PLATFORM_ENABLED, false),
    organizationAllowlist: parseAllowlist(source.STAYS_ORG_ALLOWLIST),
  };
}

/**
 * Resolve whether Stays is active for a given scope.
 * Missing org/property/unit layers default to **false** (fail-closed).
 */
export function resolveStaysEnabled(scope: StaysFlagScope = {}): StaysFlagResolution {
  const platform = scope.platformEnabled === true;
  if (!platform) {
    return {
      enabled: false,
      platform: false,
      organization: false,
      property: false,
      unit: false,
      reason: 'platform_off',
    };
  }

  const organization = scope.organizationEnabled === true;
  if (!organization) {
    return {
      enabled: false,
      platform: true,
      organization: false,
      property: false,
      unit: false,
      reason: 'organization_off',
    };
  }

  const property = scope.propertyEnabled === true;
  if (!property) {
    return {
      enabled: false,
      platform: true,
      organization: true,
      property: false,
      unit: false,
      reason: 'property_off',
    };
  }

  const unit = scope.unitEnabled === true;
  if (!unit) {
    return {
      enabled: false,
      platform: true,
      organization: true,
      property: true,
      unit: false,
      reason: 'unit_off',
    };
  }

  return {
    enabled: true,
    platform: true,
    organization: true,
    property: true,
    unit: true,
    reason: 'enabled',
  };
}

/** Convenience: env platform + allowlist org, property/unit still require explicit true. */
export function resolveStaysEnabledFromEnv(
  input: {
    organizationId?: string | null;
    propertyEnabled?: boolean;
    unitEnabled?: boolean;
  } = {},
  source: NodeJS.ProcessEnv = process.env,
): StaysFlagResolution {
  const fromEnv = readStaysFlagsFromEnv(source);
  const orgId = input.organizationId?.trim().toLowerCase() ?? '';
  const organizationEnabled =
    Boolean(orgId) &&
    (fromEnv.organizationAllowlist.has('*') || fromEnv.organizationAllowlist.has(orgId));

  return resolveStaysEnabled({
    platformEnabled: fromEnv.platformEnabled,
    organizationId: input.organizationId,
    organizationEnabled,
    propertyEnabled: input.propertyEnabled,
    unitEnabled: input.unitEnabled,
  });
}

/** Public surface helpers — Phase 0 always false unless fully resolved. */
export function staysPublicSurfaceEnabled(resolution?: StaysFlagResolution): boolean {
  return (resolution ?? resolveStaysEnabledFromEnv()).enabled;
}

import { describe, expect, it } from 'vitest';
import {
  readStaysFlagsFromEnv,
  resolveStaysEnabled,
  resolveStaysEnabledFromEnv,
  staysPublicSurfaceEnabled,
} from '../src/feature-flags.js';

describe('stays feature flags (phase 0)', () => {
  it('defaults platform off with empty env', () => {
    const flags = readStaysFlagsFromEnv({});
    expect(flags.platformEnabled).toBe(false);
    expect(flags.organizationAllowlist.size).toBe(0);
  });

  it('resolveStaysEnabled is fail-closed at every layer', () => {
    expect(resolveStaysEnabled({}).reason).toBe('platform_off');
    expect(
      resolveStaysEnabled({ platformEnabled: true }).reason,
    ).toBe('organization_off');
    expect(
      resolveStaysEnabled({ platformEnabled: true, organizationEnabled: true }).reason,
    ).toBe('property_off');
    expect(
      resolveStaysEnabled({
        platformEnabled: true,
        organizationEnabled: true,
        propertyEnabled: true,
      }).reason,
    ).toBe('unit_off');
    expect(
      resolveStaysEnabled({
        platformEnabled: true,
        organizationEnabled: true,
        propertyEnabled: true,
        unitEnabled: true,
      }),
    ).toMatchObject({ enabled: true, reason: 'enabled' });
  });

  it('env allowlist does not enable public surface without property+unit', () => {
    const env = {
      STAYS_PLATFORM_ENABLED: 'true',
      STAYS_ORG_ALLOWLIST: '00000000-0000-4000-8000-000000000001',
    };
    const partial = resolveStaysEnabledFromEnv(
      { organizationId: '00000000-0000-4000-8000-000000000001' },
      env,
    );
    expect(partial.enabled).toBe(false);
    expect(partial.reason).toBe('property_off');
    expect(staysPublicSurfaceEnabled(partial)).toBe(false);
  });

  it('treats unknown boolean strings as default false', () => {
    expect(readStaysFlagsFromEnv({ STAYS_PLATFORM_ENABLED: 'maybe' }).platformEnabled).toBe(
      false,
    );
  });
});

