/**
 * Sign and POST a stay_booking payment webhook (staging / local Nest).
 *
 * Usage:
 *   PAYMENT_WEBHOOK_SECRET=... node scripts/simulate-stay-booking-webhook.mjs \
 *     --org <uuid> --intent <payment-intent-uuid> --amount 100000 --currency OMR
 *
 * Optional: NEST_ORIGIN (default https://bhd-r.onrender.com), --provider sandbox
 */
import { createHmac, randomUUID } from 'node:crypto';

function arg(name, fallback = '') {
  const idx = process.argv.indexOf(`--${name}`);
  if (idx >= 0 && process.argv[idx + 1]) return process.argv[idx + 1];
  return fallback;
}

const secret = process.env.PAYMENT_WEBHOOK_SECRET?.trim();
const origin = (process.env.NEST_ORIGIN ?? 'https://bhd-r.onrender.com').replace(/\/$/, '');
const organizationId = arg('org');
const paymentIntentId = arg('intent');
const amountMinor = arg('amount');
const currency = arg('currency', 'OMR');
const provider = arg('provider', 'sandbox');

if (!secret || secret.length < 16) {
  console.error('Set PAYMENT_WEBHOOK_SECRET (≥16).');
  process.exit(1);
}
if (!organizationId || !paymentIntentId || !/^\d+$/.test(amountMinor)) {
  console.error(
    'Required: --org <uuid> --intent <uuid> --amount <minor> [--currency OMR] [--provider sandbox]',
  );
  process.exit(1);
}

const body = JSON.stringify({
  kind: 'stay_booking',
  organizationId,
  paymentIntentId,
  amountMinor,
  currency,
  providerReference: `sim-stay-${randomUUID()}`,
  receivedAt: new Date().toISOString(),
  method: 'card',
});
const timestamp = Math.floor(Date.now() / 1000);
const signature = createHmac('sha256', secret).update(`${timestamp}.${body}`).digest('hex');
const eventId = `sim-stay-${randomUUID()}`;

const response = await fetch(`${origin}/v1/webhooks/payments/${encodeURIComponent(provider)}`, {
  method: 'POST',
  headers: {
    'content-type': 'application/json',
    'x-event-id': eventId,
    'x-bhd-signature': `t=${timestamp},v1=${signature}`,
  },
  body,
});
const text = await response.text();
console.log(response.status, text);
process.exit(response.ok ? 0 : 1);

import { randomUUID } from 'node:crypto';
import { eq, sql } from 'drizzle-orm';
import { describe, expect, it } from 'vitest';
import {
  addresses,
  createDatabase,
  organizations,
  properties,
  stayInventoryLocks,
  units,
} from '../src/index.js';

/**
 * Concurrent GiST exclusion against real Postgres.
 * Enable with TEST_DATABASE_URL (same pattern as rls.integration.test.ts).
 */
const runtimeDatabaseUrl = process.env.TEST_DATABASE_URL ?? process.env.STAYS_LOCK_DATABASE_URL;
const integration = runtimeDatabaseUrl ? describe : describe.skip;

integration('stay_inventory_locks GiST exclusion', () => {
  it('rejects a second overlapping active lock on the same unit', async () => {
    const { client, db } = createDatabase(runtimeDatabaseUrl!, { max: 5 });
    const suffix = randomUUID().slice(0, 8);
    try {
      const seeded = await db.transaction(async (transaction) => {
        await transaction.execute(sql`select set_config('app.platform_admin', 'true', true)`);
        const [org] = await transaction
          .insert(organizations)
          .values({
            type: 'company',
            slug: `stay-lock-${suffix}`,
            legalName: 'Stay Lock Co',
            displayNameAr: 'اختبار',
            displayNameEn: 'Stay Lock Co',
          })
          .returning();
        const [address] = await transaction
          .insert(addresses)
          .values({
            organizationId: org!.id,
            governorate: 'Muscat',
            wilayat: 'Bawshar',
            city: 'Muscat',
          })
          .returning();
        const [property] = await transaction
          .insert(properties)
          .values({
            organizationId: org!.id,
            addressId: address!.id,
            kind: 'single_unit',
            category: 'apartment',
            titleAr: 'وحدة اختبار',
            titleEn: 'Lock test unit',
            status: 'active',
          })
          .returning();
        const [unit] = await transaction
          .insert(units)
          .values({
            organizationId: org!.id,
            propertyId: property!.id,
            code: `U-${suffix}`,
            titleAr: 'وحدة',
            titleEn: 'Unit',
            listingPurpose: 'rent',
            status: 'vacant',
          })
          .returning();
        return { orgId: org!.id, unitId: unit!.id };
      });

      await db.transaction(async (transaction) => {
        await transaction.execute(sql`select set_config('app.platform_admin', 'true', true)`);
        await transaction.insert(stayInventoryLocks).values({
          organizationId: seeded.orgId,
          unitId: seeded.unitId,
          stayRange: '[2026-10-01,2026-10-05)',
          kind: 'booking',
          status: 'active',
        });
      });

      let rejected = false;
      try {
        await db.transaction(async (transaction) => {
          await transaction.execute(sql`select set_config('app.platform_admin', 'true', true)`);
          await transaction.insert(stayInventoryLocks).values({
            organizationId: seeded.orgId,
            unitId: seeded.unitId,
            stayRange: '[2026-10-03,2026-10-07)',
            kind: 'hold',
            status: 'active',
          });
        });
      } catch (error) {
        const message = error instanceof Error ? error.message : String(error);
        rejected =
          message.includes('stay_inventory_locks_no_overlap_active') ||
          message.includes('exclusion') ||
          message.includes('23P01');
      }
      expect(rejected).toBe(true);

      // Adjacent (touching) ranges must be allowed: checkout day free for next guest.
      await db.transaction(async (transaction) => {
        await transaction.execute(sql`select set_config('app.platform_admin', 'true', true)`);
        await transaction.insert(stayInventoryLocks).values({
          organizationId: seeded.orgId,
          unitId: seeded.unitId,
          stayRange: '[2026-10-05,2026-10-08)',
          kind: 'booking',
          status: 'active',
        });
      });

      await db.transaction(async (transaction) => {
        await transaction.execute(sql`select set_config('app.platform_admin', 'true', true)`);
        await transaction
          .delete(stayInventoryLocks)
          .where(eq(stayInventoryLocks.organizationId, seeded.orgId));
        await transaction.delete(units).where(eq(units.organizationId, seeded.orgId));
        await transaction.delete(properties).where(eq(properties.organizationId, seeded.orgId));
        await transaction.delete(addresses).where(eq(addresses.organizationId, seeded.orgId));
        await transaction.delete(organizations).where(eq(organizations.id, seeded.orgId));
      });
    } finally {
      await client.end();
    }
  });
});

