import { EmptyState } from '@bhd-r/ui';

export type StayPerformanceMetrics = {
  fromOn: string;
  toOn: string;
  currency: string | null;
  availableRoomNights: number;
  occupiedRoomNights: number;
  roomRevenueMinor: string;
  occupancyPercent: string | null;
  adrMinor: string | null;
  revparMinor: string | null;
  bookingCount: number;
};

export function StayPerformancePanel({
  locale,
  metrics,
}: {
  locale: string;
  metrics: StayPerformanceMetrics | null;
}) {
  const ar = locale === 'ar';

  if (!metrics) {
    return (
      <EmptyState
        title={ar ? 'لا بيانات أداء بعد' : 'No performance data yet'}
        description={
          ar
            ? 'يظهر Occupancy / ADR / RevPAR بعد تفعيل المخزون والحجوزات المؤكدة.'
            : 'Occupancy / ADR / RevPAR appear once inventory projection and confirmed stays exist.'
        }
      />
    );
  }

  const money = (minor: string | null) =>
    minor == null
      ? '—'
      : `${metrics.currency ?? ''} ${minor}`.trim();

  return (
    <div className="stays-performance">
      <p className="muted" dir="ltr">
        {metrics.fromOn} → {metrics.toOn}
      </p>
      <ul className="stays-portal__stats stays-performance__stats">
        <li>
          <span>{ar ? 'الإشغال' : 'Occupancy'}</span>
          <strong dir="ltr">
            {metrics.occupancyPercent != null ? `${metrics.occupancyPercent}%` : '—'}
          </strong>
        </li>
        <li>
          <span>ADR</span>
          <strong dir="ltr">{money(metrics.adrMinor)}</strong>
        </li>
        <li>
          <span>RevPAR</span>
          <strong dir="ltr">{money(metrics.revparMinor)}</strong>
        </li>
        <li>
          <span>{ar ? 'ليالي مشغولة' : 'Occupied nights'}</span>
          <strong dir="ltr">
            {metrics.occupiedRoomNights}/{metrics.availableRoomNights}
          </strong>
        </li>
        <li>
          <span>{ar ? 'إيراد الغرف' : 'Room revenue'}</span>
          <strong dir="ltr">{money(metrics.roomRevenueMinor)}</strong>
        </li>
        <li>
          <span>{ar ? 'حجوزات في النطاق' : 'Bookings in range'}</span>
          <strong dir="ltr">{metrics.bookingCount}</strong>
        </li>
      </ul>
    </div>
  );
}

import { notFound } from 'next/navigation';
import { StayPerformancePanel, type StayPerformanceMetrics } from '@/components/stays/stay-performance-panel';
import { StaysPortalPage } from '@/components/stays/stays-portal-page';
import { isStaysPlatformEnabled } from '@/lib/stays-flags';
import { apiFetch } from '@/lib/server-api';

function defaultRange(): { fromOn: string; toOn: string } {
  const to = new Date();
  const from = new Date(to);
  from.setUTCDate(from.getUTCDate() - 30);
  return {
    fromOn: from.toISOString().slice(0, 10),
    toOn: to.toISOString().slice(0, 10),
  };
}

export default async function Page({ params }: { params: Promise<{ locale: string }> }) {
  if (!isStaysPlatformEnabled()) notFound();
  const { locale } = await params;
  const { fromOn, toOn } = defaultRange();
  const health = await apiFetch<{ ok?: boolean }>('/v1/stays/inventory/health').catch(() => null);
  const metrics = await apiFetch<StayPerformanceMetrics>(
    `/v1/stays/reports/performance?fromOn=${encodeURIComponent(fromOn)}&toOn=${encodeURIComponent(toOn)}`,
  ).catch(() => null);

  return (
    <StaysPortalPage locale={locale} portal="owner" section="dashboard">
      <ul className="stays-portal__stats">
        <li>
          <span>{locale === 'ar' ? 'حالة الواجهة' : 'API status'}</span>
          <strong dir="ltr">{health ? 'reachable' : 'offline / gated'}</strong>
        </li>
      </ul>
      <h2 className="stays-performance__title">
        {locale === 'ar' ? 'أداء 30 يوماً' : 'Last 30 days performance'}
      </h2>
      <StayPerformancePanel locale={locale} metrics={metrics} />
    </StaysPortalPage>
  );
}

