      const dtStampUtc = new Date()
        .toISOString()
        .replace(/[-:]/g, '')
        .replace(/\.\d{3}Z$/, 'Z');

      return buildStayUnitIcs({
        calendarName: `BHD R stays · ${unitId.slice(0, 8)}`,
        dtStampUtc,
        events,
      });
