'use client';

import { useEffect, useId, useRef, useState } from 'react';
import { useRouter } from '@/i18n/navigation';

const GOVERNORATES = [
  'Muscat',
  'Dhofar',
  'Musandam',
  'Al Buraimi',
  'Ad Dakhiliyah',
  'North Al Batinah',
  'South Al Batinah',
  'North Ash Sharqiyah',
  'South Ash Sharqiyah',
  'Al Dhahirah',
  'Al Wusta',
] as const;

function defaultCheckIn(): string {
  const d = new Date();
  d.setDate(d.getDate() + 1);
  return d.toISOString().slice(0, 10);
}

function defaultCheckOut(checkIn: string): string {
  const d = new Date(`${checkIn}T12:00:00`);
  d.setDate(d.getDate() + 2);
  return d.toISOString().slice(0, 10);
}

function formatDateLabel(value: string, locale: string): string {
  if (!value) return '';
  try {
    return new Intl.DateTimeFormat(locale === 'ar' ? 'ar-OM' : 'en-OM', {
      weekday: 'short',
      day: 'numeric',
      month: 'short',
    }).format(new Date(`${value}T12:00:00`));
  } catch {
    return value;
  }
}

export function StaySearchBar({
  locale,
  variant = 'hero',
  defaults = {},
}: {
  locale: string;
  variant?: 'hero' | 'compact' | 'inline';
  defaults?: {
    destination?: string;
    checkInOn?: string;
    checkOutOn?: string;
    adults?: string;
    children?: string;
  };
}) {
  const ar = locale === 'ar';
  const router = useRouter();
  const guestsPanelId = useId();
  const guestsRef = useRef<HTMLDivElement>(null);

  const initialIn = defaults.checkInOn || defaultCheckIn();
  const [destination, setDestination] = useState(defaults.destination ?? '');
  const [checkInOn, setCheckInOn] = useState(initialIn);
  const [checkOutOn, setCheckOutOn] = useState(defaults.checkOutOn || defaultCheckOut(initialIn));
  const [adults, setAdults] = useState(defaults.adults ?? '2');
  const [children, setChildren] = useState(defaults.children ?? '0');
  const [guestsOpen, setGuestsOpen] = useState(false);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (!guestsOpen) return;
    function onPointer(event: MouseEvent) {
      if (guestsRef.current && !guestsRef.current.contains(event.target as Node)) {
        setGuestsOpen(false);
      }
    }
    document.addEventListener('mousedown', onPointer);
    return () => document.removeEventListener('mousedown', onPointer);
  }, [guestsOpen]);

  function guestSummary(): string {
    const a = Number.parseInt(adults, 10) || 1;
    const c = Number.parseInt(children, 10) || 0;
    if (ar) {
      const adultPart =
        a === 1 ? 'شخص بالغ واحد' : a === 2 ? 'شخصان بالغان' : `${a} بالغين`;
      const childPart = c === 0 ? 'بدون أطفال' : c === 1 ? 'طفل واحد' : `${c} أطفال`;
      return `${adultPart} · ${childPart}`;
    }
    return `${a} adult${a === 1 ? '' : 's'} · ${c} child${c === 1 ? '' : 'ren'}`;
  }

  function submit(event: React.FormEvent) {
    event.preventDefault();
    setError(null);
    if (!checkInOn || !checkOutOn) {
      setError(ar ? 'اختر تاريخ الوصول والمغادرة' : 'Select check-in and check-out dates');
      return;
    }
    if (checkOutOn <= checkInOn) {
      setError(ar ? 'تاريخ المغادرة يجب أن يكون بعد الوصول' : 'Check-out must be after check-in');
      return;
    }
    const params = new URLSearchParams();
    if (destination) params.set('destination', destination);
    params.set('checkInOn', checkInOn);
    params.set('checkOutOn', checkOutOn);
    params.set('adults', adults);
    params.set('children', children);
    router.push(`/stays?${params.toString()}`);
  }

  const dateSummary =
    checkInOn && checkOutOn
      ? `${formatDateLabel(checkInOn, locale)} — ${formatDateLabel(checkOutOn, locale)}`
      : ar
        ? 'تحديد التواريخ'
        : 'Select dates';

  return (
    <form
      className={`booking-bar booking-bar--${variant}`}
      onSubmit={submit}
      role="search"
      aria-label={ar ? 'ابحث عن إقامة يومية' : 'Search daily stays'}
    >
      <div className="booking-bar__segment booking-bar__segment--destination">
        <label className="booking-bar__label" htmlFor="booking-bar-dest">
          {ar ? 'الوجهة' : 'Destination'}
        </label>
        <select
          id="booking-bar-dest"
          className="booking-bar__control"
          value={destination}
          onChange={(event) => setDestination(event.target.value)}
        >
          <option value="">{ar ? 'كل المحافظات' : 'All governorates'}</option>
          {GOVERNORATES.map((name) => (
            <option key={name} value={name}>
              {name}
            </option>
          ))}
        </select>
      </div>

      <div className="booking-bar__segment booking-bar__segment--dates">
        <span className="booking-bar__label">{ar ? 'التواريخ' : 'Dates'}</span>
        <div className="booking-bar__dates" title={dateSummary}>
          <input
            className="booking-bar__date"
            type="date"
            aria-label={ar ? 'تاريخ الوصول' : 'Check-in'}
            value={checkInOn}
            min={new Date().toISOString().slice(0, 10)}
            onChange={(event) => {
              const next = event.target.value;
              setCheckInOn(next);
              if (checkOutOn <= next) setCheckOutOn(defaultCheckOut(next));
            }}
          />
          <span className="booking-bar__dates-sep" aria-hidden="true">
            —
          </span>
          <input
            className="booking-bar__date"
            type="date"
            aria-label={ar ? 'تاريخ المغادرة' : 'Check-out'}
            value={checkOutOn}
            min={checkInOn || new Date().toISOString().slice(0, 10)}
            onChange={(event) => setCheckOutOn(event.target.value)}
          />
        </div>
        <p className="booking-bar__dates-hint" aria-hidden="true">
          {dateSummary}
        </p>
      </div>

      <div className="booking-bar__segment booking-bar__segment--guests" ref={guestsRef}>
        <span className="booking-bar__label">{ar ? 'الضيوف' : 'Guests'}</span>
        <button
          type="button"
          className="booking-bar__guests-trigger"
          aria-expanded={guestsOpen}
          aria-controls={guestsPanelId}
          onClick={() => setGuestsOpen((open) => !open)}
        >
          {guestSummary()}
        </button>
        {guestsOpen ? (
          <div id={guestsPanelId} className="booking-bar__guests-panel" role="dialog">
            <div className="booking-bar__guests-row">
              <span>{ar ? 'بالغون' : 'Adults'}</span>
              <select
                className="select"
                value={adults}
                onChange={(event) => setAdults(event.target.value)}
              >
                {[1, 2, 3, 4, 5, 6, 8, 10].map((n) => (
                  <option key={n} value={n}>
                    {n}
                  </option>
                ))}
              </select>
            </div>
            <div className="booking-bar__guests-row">
              <span>{ar ? 'أطفال' : 'Children'}</span>
              <select
                className="select"
                value={children}
                onChange={(event) => setChildren(event.target.value)}
              >
                {[0, 1, 2, 3, 4, 5].map((n) => (
                  <option key={n} value={n}>
                    {n}
                  </option>
                ))}
              </select>
            </div>
            <button
              type="button"
              className="button button--quiet booking-bar__guests-done"
              onClick={() => setGuestsOpen(false)}
            >
              {ar ? 'تم' : 'Done'}
            </button>
          </div>
        ) : null}
      </div>

      <button type="submit" className="button button--primary booking-bar__submit">
        {ar ? 'بحث' : 'Search'}
      </button>

      {error ? (
        <p className="booking-bar__error" role="alert">
          {error}
        </p>
      ) : null}
    </form>
  );
}

import { StaySearchBar } from '@/components/stays/stay-search-bar';

export async function StaySearch({
  locale,
  defaults = {},
  compact = false,
  variant,
}: {
  locale: string;
  compact?: boolean;
  variant?: 'hero' | 'compact' | 'inline';
  defaults?: {
    destination?: string;
    checkInOn?: string;
    checkOutOn?: string;
    adults?: string;
    children?: string;
  };
}) {
  const resolvedVariant = variant ?? (compact ? 'compact' : 'hero');
  return <StaySearchBar locale={locale} variant={resolvedVariant} defaults={defaults} />;
}

'use client';

import { useState, useTransition } from 'react';
import { Link } from '@/i18n/navigation';
import { ApiError, browserPublicGet, browserPublicMutation } from '@/lib/api';
import { formatMoney } from '@/lib/format';

type QuoteResult = {
  id: string;
  nights: number;
  currency: string;
  subtotalMinor: string;
  feesMinor: string;
  taxMinor: string;
  totalMinor: string;
  expiresAt: string;
};

type HoldResult = {
  id: string;
  expiresAt: string;
  duplicate?: boolean;
};

type BookingResult = {
  bookingId: string;
  referenceCode: string;
  status: string;
  paymentIntentId: string;
  amountMinor: string;
  currency: string;
  duplicate?: boolean;
};

type AvailabilityResult = {
  available: boolean;
  reason?: string;
  nights?: number;
};

type Step = 'stay' | 'guest' | 'review' | 'payment';

function defaultCheckIn(): string {
  const d = new Date();
  d.setUTCDate(d.getUTCDate() + 7);
  return d.toISOString().slice(0, 10);
}

function defaultCheckOut(checkIn: string): string {
  const d = new Date(`${checkIn}T00:00:00.000Z`);
  d.setUTCDate(d.getUTCDate() + 2);
  return d.toISOString().slice(0, 10);
}

export function StayCheckout({
  locale,
  slug,
  title,
  defaults,
}: {
  locale: string;
  slug: string;
  title?: string;
  defaults?: {
    checkInOn?: string;
    checkOutOn?: string;
    adults?: string;
    children?: string;
  };
}) {
  const ar = locale === 'ar';
  const initialIn = defaults?.checkInOn || defaultCheckIn();
  const [step, setStep] = useState<Step>('stay');
  const [checkInOn, setCheckInOn] = useState(initialIn);
  const [checkOutOn, setCheckOutOn] = useState(
    defaults?.checkOutOn || defaultCheckOut(initialIn),
  );
  const [adults, setAdults] = useState(defaults?.adults ?? '2');
  const [children, setChildren] = useState(defaults?.children ?? '0');
  const [guestName, setGuestName] = useState('');
  const [guestPhone, setGuestPhone] = useState('');
  const [guestEmail, setGuestEmail] = useState('');
  const [quote, setQuote] = useState<QuoteResult | null>(null);
  const [booking, setBooking] = useState<BookingResult | null>(null);
  const [stepHint, setStepHint] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [payBusy, setPayBusy] = useState(false);
  const [pending, startTransition] = useTransition();

  const steps: { id: Step; label: string }[] = [
    { id: 'stay', label: ar ? 'الإقامة' : 'Your stay' },
    { id: 'guest', label: ar ? 'بياناتك' : 'Your details' },
    { id: 'review', label: ar ? 'المراجعة' : 'Review' },
    { id: 'payment', label: ar ? 'الدفع' : 'Payment' },
  ];

  function stepIndex(id: Step): number {
    return steps.findIndex((item) => item.id === id);
  }

  async function loadQuote(): Promise<QuoteResult> {
    const qs = new URLSearchParams({ checkInOn, checkOutOn, adults, children });
    const availability = await browserPublicGet<AvailabilityResult>(
      `/v1/public/stays/${encodeURIComponent(slug)}/availability?${qs.toString()}`,
    );
    if (!availability.available) {
      throw new Error(
        availability.reason === 'guests_exceed_max'
          ? ar
            ? 'عدد الضيوف يتجاوز الحد الأقصى'
            : 'Guest count exceeds the maximum'
          : availability.reason === 'nights_out_of_range'
            ? ar
              ? 'مدة الإقامة خارج النطاق المسموح'
              : 'Stay length is outside the allowed range'
            : ar
              ? 'التواريخ غير متاحة — جرّب تواريخاً أخرى'
              : 'Dates not available — try different dates',
      );
    }
    return browserPublicMutation<QuoteResult>(
      `/v1/public/stays/${encodeURIComponent(slug)}/quotes`,
      {
        checkInOn,
        checkOutOn,
        adults: Number(adults),
        children: Number(children),
      },
    );
  }

  function continueFromStay() {
    setError(null);
    if (!checkInOn || !checkOutOn || checkOutOn <= checkInOn) {
      setError(ar ? 'تحقق من التواريخ' : 'Check your dates');
      return;
    }
    setStep('guest');
  }

  function continueFromGuest() {
    setError(null);
    if (!guestName.trim() || guestName.trim().length < 2) {
      setError(ar ? 'أدخل اسم الضيف (حرفان على الأقل)' : 'Enter guest name (at least 2 characters)');
      return;
    }
    setStep('review');
    setQuote(null);
    startTransition(async () => {
      setStepHint(ar ? 'التحقق من التوافر وعرض السعر…' : 'Checking availability and pricing…');
      try {
        const nextQuote = await loadQuote();
        setQuote(nextQuote);
        setStepHint(null);
      } catch (caught) {
        setStepHint(null);
        setError(caught instanceof Error ? caught.message : 'quote_failed');
      }
    });
  }

  function confirmBooking() {
    if (!quote) return;
    startTransition(async () => {
      setError(null);
      setBooking(null);
      const holdKey = `stay-hold-${slug}-${crypto.randomUUID()}`;
      const bookKey = `stay-book-${slug}-${crypto.randomUUID()}`;
      setStepHint(ar ? 'حجز مؤقت…' : 'Holding inventory…');
      try {
        const hold = await browserPublicMutation<HoldResult>(
          '/v1/public/stays/holds',
          { quoteId: quote.id },
          { idempotencyKey: holdKey },
        );
        setStepHint(ar ? 'إنشاء الحجز…' : 'Creating booking…');
        const nextBooking = await browserPublicMutation<BookingResult>(
          '/v1/public/stays/bookings',
          {
            holdId: hold.id,
            guestDisplayName: guestName.trim(),
          },
          { idempotencyKey: bookKey },
        );
        setBooking(nextBooking);
        setStep('payment');
        setStepHint(null);
      } catch (caught) {
        setStepHint(null);
        if (caught instanceof ApiError && caught.status === 404) {
          setError(
            ar
              ? 'مسار الإقامات غير مفعّل حالياً.'
              : 'Stays booking is not enabled yet.',
          );
          return;
        }
        setError(caught instanceof Error ? caught.message : 'booking_failed');
      }
    });
  }

  function payNow() {
    if (!booking) return;
    setPayBusy(true);
    setError(null);
    void (async () => {
      try {
        const returnPath = `/${locale}/stays/booking/confirmed?ref=${encodeURIComponent(booking.referenceCode)}`;
        const session = await browserPublicMutation<{ redirectUrl: string }>(
          '/v1/public/stays/payment-sessions',
          {
            paymentIntentId: booking.paymentIntentId,
            locale: locale === 'en' ? 'en' : 'ar',
            returnPath,
          },
          { idempotencyKey: `stay-pay-${booking.paymentIntentId}` },
        );
        const target = new URL(session.redirectUrl);
        if (
          target.protocol !== 'https:' &&
          !(target.protocol === 'http:' && target.hostname === 'localhost')
        ) {
          throw new Error('invalid_payment_redirect');
        }
        window.location.assign(target.href);
      } catch (caught) {
        setError(
          caught instanceof ApiError && caught.status === 409
            ? ar
              ? 'بوابة الدفع غير مفعّلة في هذه البيئة.'
              : 'Payment gateway is not active in this environment.'
            : caught instanceof Error
              ? caught.message
              : 'payment_failed',
        );
        setPayBusy(false);
      }
    })();
  }

  return (
    <section className="stays-checkout stays-checkout--wizard" aria-labelledby="stays-checkout-title">
      <h2 id="stays-checkout-title">{ar ? 'احجز هذه الإقامة' : 'Book this stay'}</h2>
      {title ? <p className="stays-checkout__property muted">{title}</p> : null}

      <ol className="stays-checkout__steps" aria-label={ar ? 'خطوات الحجز' : 'Booking steps'}>
        {steps.map((item, index) => {
          const current = stepIndex(step);
          const done = index < current || (step === 'payment' && item.id !== 'payment');
          const active = item.id === step;
          return (
            <li
              key={item.id}
              className={
                active
                  ? 'stays-checkout__step is-active'
                  : done
                    ? 'stays-checkout__step is-done'
                    : 'stays-checkout__step'
              }
            >
              <span aria-hidden="true">{index + 1}</span>
              {item.label}
            </li>
          );
        })}
      </ol>

      {step === 'stay' ? (
        <div className="stays-checkout__panel">
          <h3>{ar ? 'تواريخ الإقامة' : 'Stay dates'}</h3>
          <div className="stays-checkout__grid">
            <div className="field">
              <label htmlFor="stay-book-in">{ar ? 'الوصول' : 'Check-in'}</label>
              <input
                className="input"
                id="stay-book-in"
                type="date"
                required
                value={checkInOn}
                onChange={(event) => setCheckInOn(event.target.value)}
              />
            </div>
            <div className="field">
              <label htmlFor="stay-book-out">{ar ? 'المغادرة' : 'Check-out'}</label>
              <input
                className="input"
                id="stay-book-out"
                type="date"
                required
                value={checkOutOn}
                onChange={(event) => setCheckOutOn(event.target.value)}
              />
            </div>
            <div className="field">
              <label htmlFor="stay-book-adults">{ar ? 'بالغون' : 'Adults'}</label>
              <select
                className="select"
                id="stay-book-adults"
                value={adults}
                onChange={(event) => setAdults(event.target.value)}
              >
                {[1, 2, 3, 4, 5, 6, 8, 10].map((count) => (
                  <option key={count} value={count}>
                    {count}
                  </option>
                ))}
              </select>
            </div>
            <div className="field">
              <label htmlFor="stay-book-children">{ar ? 'أطفال' : 'Children'}</label>
              <select
                className="select"
                id="stay-book-children"
                value={children}
                onChange={(event) => setChildren(event.target.value)}
              >
                {[0, 1, 2, 3, 4, 5].map((count) => (
                  <option key={count} value={count}>
                    {count}
                  </option>
                ))}
              </select>
            </div>
          </div>
          <button type="button" className="button button--primary" onClick={continueFromStay}>
            {ar ? 'متابعة' : 'Continue'}
          </button>
        </div>
      ) : null}

      {step === 'guest' ? (
        <div className="stays-checkout__panel">
          <h3>{ar ? 'بيانات الضيف' : 'Guest details'}</h3>
          <div className="stays-checkout__grid">
            <div className="field stays-checkout__name">
              <label htmlFor="stay-book-name">{ar ? 'الاسم الكامل' : 'Full name'}</label>
              <input
                className="input"
                id="stay-book-name"
                type="text"
                required
                minLength={2}
                maxLength={160}
                value={guestName}
                onChange={(event) => setGuestName(event.target.value)}
                autoComplete="name"
              />
            </div>
            <div className="field">
              <label htmlFor="stay-book-phone">{ar ? 'الهاتف (اختياري)' : 'Phone (optional)'}</label>
              <input
                className="input"
                id="stay-book-phone"
                type="tel"
                value={guestPhone}
                onChange={(event) => setGuestPhone(event.target.value)}
                autoComplete="tel"
                dir="ltr"
              />
            </div>
            <div className="field stays-checkout__name">
              <label htmlFor="stay-book-email">{ar ? 'البريد (اختياري)' : 'Email (optional)'}</label>
              <input
                className="input"
                id="stay-book-email"
                type="email"
                value={guestEmail}
                onChange={(event) => setGuestEmail(event.target.value)}
                autoComplete="email"
                dir="ltr"
              />
            </div>
          </div>
          <div className="stays-checkout__nav">
            <button type="button" className="button button--quiet" onClick={() => setStep('stay')}>
              {ar ? 'رجوع' : 'Back'}
            </button>
            <button
              type="button"
              className="button button--primary"
              disabled={pending}
              onClick={continueFromGuest}
            >
              {pending ? (ar ? 'جارٍ التحقق…' : 'Checking…') : ar ? 'متابعة' : 'Continue'}
            </button>
          </div>
        </div>
      ) : null}

      {step === 'review' ? (
        <div className="stays-checkout__panel">
          <h3>{ar ? 'مراجعة الحجز' : 'Review your booking'}</h3>
          <dl className="stays-checkout__summary">
            <div>
              <dt>{ar ? 'الضيف' : 'Guest'}</dt>
              <dd>{guestName}</dd>
            </div>
            <div>
              <dt>{ar ? 'الوصول' : 'Check-in'}</dt>
              <dd dir="ltr">{checkInOn}</dd>
            </div>
            <div>
              <dt>{ar ? 'المغادرة' : 'Check-out'}</dt>
              <dd dir="ltr">{checkOutOn}</dd>
            </div>
            <div>
              <dt>{ar ? 'الضيوف' : 'Guests'}</dt>
              <dd>
                {adults} {ar ? 'بالغ' : 'adults'}
                {Number(children) > 0 ? ` · ${children} ${ar ? 'أطفال' : 'children'}` : ''}
              </dd>
            </div>
          </dl>
          {quote ? (
            <div className="stays-checkout__quote card">
              <p>
                {quote.nights} {ar ? 'ليلة' : 'nights'}
              </p>
              <p>
                {ar ? 'المجموع' : 'Total'}:{' '}
                <strong dir="ltr">
                  {formatMoney(quote.totalMinor, quote.currency, locale)}
                </strong>
              </p>
              <p className="muted">
                {ar ? 'شامل الرسوم والضريبة حسب العرض' : 'Includes fees and tax per quote'}
              </p>
            </div>
          ) : null}
          <div className="stays-checkout__nav">
            <button type="button" className="button button--quiet" onClick={() => setStep('guest')}>
              {ar ? 'رجوع' : 'Back'}
            </button>
            <button
              type="button"
              className="button button--primary"
              disabled={pending || !quote}
              onClick={confirmBooking}
            >
              {pending
                ? ar
                  ? 'جارٍ الحجز…'
                  : 'Booking…'
                : ar
                  ? 'تأكيد الحجز'
                  : 'Confirm booking'}
            </button>
          </div>
        </div>
      ) : null}

      {step === 'payment' && booking ? (
        <div className="stays-checkout__panel stays-checkout__panel--payment">
          <h3>{ar ? 'الدفع' : 'Payment'}</h3>
          <div className="notice notice--success" role="status">
            <p>
              {ar ? 'تم إنشاء الحجز' : 'Booking created'}:{' '}
              <strong dir="ltr">{booking.referenceCode}</strong>
            </p>
            <p>
              {ar ? 'المبلغ' : 'Amount'}:{' '}
              <strong dir="ltr">
                {formatMoney(booking.amountMinor, booking.currency, locale)}
              </strong>
            </p>
          </div>
          <p className="muted">
            {ar
              ? 'أكمل الدفع لتأكيد الحجز. ستصلك صفحة التأكيد بعد الدفع.'
              : 'Complete payment to confirm. You will land on a confirmation page after payment.'}
          </p>
          <button
            type="button"
            className="button button--primary"
            disabled={payBusy}
            onClick={() => payNow()}
          >
            {payBusy ? (ar ? 'جارٍ التحويل…' : 'Redirecting…') : ar ? 'ادفع الآن' : 'Pay now'}
          </button>
          <p>
            <Link
              className="text-link"
              href={`/stays/booking/confirmed?ref=${encodeURIComponent(booking.referenceCode)}`}
            >
              {ar ? 'تخطّي الدفع الآن (عرض التأكيد)' : 'Skip payment for now (view confirmation)'}
            </Link>
          </p>
        </div>
      ) : null}

      {stepHint ? (
        <p className="notice notice--info" role="status">
          {stepHint}
        </p>
      ) : null}
      {error ? (
        <p className="field__error" role="alert">
          {error}
        </p>
      ) : null}
    </section>
  );
}

import { getTranslations, setRequestLocale } from 'next-intl/server';
import { notFound } from 'next/navigation';
import { Link } from '@/i18n/navigation';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { formatMoney } from '@/lib/format';
import { loadPublicStayBySlugOnNeon } from '@/lib/load-public-stays-neon';
import { isStaysPublicSurfaceEnabled } from '@/lib/stays-flags';
import { publicApiFetch } from '@/lib/server-api';
import { localizedName } from '@/lib/format';
import type { StayPublicDetail } from '@bhd-r/contracts';

type PublicBooking = {
  referenceCode: string;
  status: string;
  checkInOn?: string;
  checkOutOn?: string;
  currency?: string;
  totalMinor?: string;
  nights?: number;
  guestDisplayName?: string | null;
};

async function loadBooking(ref: string): Promise<PublicBooking | null> {
  return publicApiFetch<PublicBooking>(
    `/v1/public/stays/bookings/lookup?referenceCode=${encodeURIComponent(ref)}`,
    8,
  ).catch(() => null);
}

export default async function StayBookingConfirmedPage({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  if (!isStaysPublicSurfaceEnabled()) notFound();
  const { locale } = await params;
  const query = await searchParams;
  setRequestLocale(locale);
  const t = await getTranslations('Stays');
  const ar = locale === 'ar';

  const refRaw = query.ref;
  const ref =
    typeof refRaw === 'string' ? refRaw : Array.isArray(refRaw) ? refRaw[0] : undefined;
  if (!ref) notFound();

  const booking = await loadBooking(ref);
  if (!booking) notFound();

  return (
    <div className="container section stays-booking-confirmed">
      <div className="stays-booking-confirmed__card card">
        <span className="stays-booking-confirmed__icon" aria-hidden="true">
          ✓
        </span>
        <h1>{ar ? 'تم استلام حجزك' : 'Your booking is received'}</h1>
        <p className="muted">
          {booking.status === 'confirmed' || booking.status === 'paid'
            ? ar
              ? 'تم تأكيد الحجز والدفع.'
              : 'Booking and payment are confirmed.'
            : ar
              ? 'الحجز مسجّل. أكمل الدفع لتأكيد الإقامة.'
              : 'Booking is registered. Complete payment to confirm your stay.'}
        </p>

        <dl className="stays-booking-confirmed__meta">
          <div>
            <dt>{ar ? 'مرجع الحجز' : 'Booking reference'}</dt>
            <dd dir="ltr">
              <strong>{booking.referenceCode}</strong>
            </dd>
          </div>
          {booking.guestDisplayName ? (
            <div>
              <dt>{ar ? 'الضيف' : 'Guest'}</dt>
              <dd>{booking.guestDisplayName}</dd>
            </div>
          ) : null}
          {booking.checkInOn ? (
            <div>
              <dt>{ar ? 'الوصول' : 'Check-in'}</dt>
              <dd dir="ltr">{booking.checkInOn}</dd>
            </div>
          ) : null}
          {booking.checkOutOn ? (
            <div>
              <dt>{ar ? 'المغادرة' : 'Check-out'}</dt>
              <dd dir="ltr">{booking.checkOutOn}</dd>
            </div>
          ) : null}
          {booking.totalMinor && booking.currency ? (
            <div>
              <dt>{ar ? 'المجموع' : 'Total'}</dt>
              <dd dir="ltr">
                <strong>{formatMoney(booking.totalMinor, booking.currency, locale)}</strong>
              </dd>
            </div>
          ) : null}
          <div>
            <dt>{ar ? 'الحالة' : 'Status'}</dt>
            <dd dir="ltr">{booking.status}</dd>
          </div>
        </dl>

        <div className="stays-booking-confirmed__actions">
          <Link className="button button--primary" href="/stays">
            {ar ? 'ابحث عن إقامة أخرى' : 'Search another stay'}
          </Link>
          <Link className="button button--quiet" href={`/guest/stays?ref=${encodeURIComponent(ref)}`}>
            {ar ? 'متابعة رحلتي' : 'Track my trip'}
          </Link>
        </div>
      </div>
    </div>
  );
}

