/* Booking.com-style stays search bar */
.hero-search__booking-wrap {
  padding: 1.35rem;
  background: #fff;
  border: 1px solid rgb(9 45 36 / 0.1);
  border-radius: 1.15rem;
  box-shadow: 0 28px 70px rgb(9 45 36 / 0.16);
}
.booking-bar {
  display: grid;
  grid-template-columns: minmax(0, 1.1fr) minmax(0, 1.4fr) minmax(0, 1.2fr) auto;
  gap: 0;
  align-items: stretch;
  background: #fff;
  border: 2px solid #febb02;
  border-radius: 0.65rem;
  overflow: visible;
  position: relative;
}
.booking-bar--compact,
.booking-bar--inline {
  border-width: 1px;
  border-color: #d7e1db;
  border-radius: var(--radius);
  box-shadow: none;
}
.booking-bar--hero {
  box-shadow: 0 8px 28px rgb(9 45 36 / 0.12);
}
.booking-bar__segment {
