import type { Metadata } from 'next';
import { notFound } from 'next/navigation';
import { getTranslations, setRequestLocale } from 'next-intl/server';
import { PropertyDetailManager } from '@/components/property-detail-manager';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { localizedName } from '@/lib/format';
import { loadPublicPropertyShowcaseFromNeon } from '@/lib/load-public-property-neon';
import { loadPublicStayBySlugOnNeon } from '@/lib/load-public-stays-neon';
import { toPublicMediaSrc } from '@/lib/public-media-url';
import { isStaysPublicSurfaceEnabled } from '@/lib/stays-flags';
import { bilingualAlternates } from '@/lib/seo';
import { publicApiFetch } from '@/lib/server-api';
import { getViewer } from '@/lib/viewer';
import type { StayPublicDetail } from '@bhd-r/contracts';

async function loadStayDetail(slug: string): Promise<StayPublicDetail | null> {
  if (hasDatabaseUrl()) {
    try {
      const neon = await loadPublicStayBySlugOnNeon(slug);
      if (neon) return neon;
    } catch (error) {
      console.error('Neon public stay load failed', error);
    }
  }
  return publicApiFetch<StayPublicDetail>(
    `/v1/public/stays/${encodeURIComponent(slug)}`,
    8,
  ).catch(() => null);
}

export async function generateMetadata({
  params,
}: {
  params: Promise<{ locale: string; slug: string }>;
}): Promise<Metadata> {
  const { locale, slug } = await params;
  const detail = await loadStayDetail(slug).catch(() => null);
  if (!detail) {
    return {
      title: locale === 'ar' ? 'إقامة يومية' : 'Daily stay',
      robots: { index: false, follow: false },
      openGraph: { images: [] },
      twitter: { images: [] },
    };
  }
  const title = localizedName(locale, detail.titleAr, detail.titleEn);
  const description =
    localizedName(locale, detail.descriptionAr ?? '', detail.descriptionEn ?? '') ||
    detail.destination ||
    title;
  const image = toPublicMediaSrc(detail.coverImageUrl) ?? detail.coverImageUrl ?? undefined;
  return {
    title,
    description,
    alternates: bilingualAlternates(locale, `/stays/${slug}`),
    openGraph: {
      title,
      description,
      url: `/${locale}/stays/${slug}`,
      type: 'website',
      images: image ? [{ url: image }] : [],
    },
    twitter: { title, description, images: image ? [image] : [] },
  };
}

/** Public stay — same Property 360 layout as unit listings, with daily-stay booking sidebar. */
export default async function StayDetailPage({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string; slug: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  if (!isStaysPublicSurfaceEnabled()) notFound();
  const { locale: rawLocale, slug } = await params;
  const locale = rawLocale === 'en' ? 'en' : 'ar';
  const query = await searchParams;
  setRequestLocale(locale);
  const t = await getTranslations('Stays');
  const ar = locale === 'ar';

  const one = (value: string | string[] | undefined) =>
    typeof value === 'string' ? value : Array.isArray(value) ? value[0] : undefined;

  const checkInOn = one(query.checkInOn);
  const checkOutOn = one(query.checkOutOn);
  const adults = one(query.adults);
  const children = one(query.children);

  const dateDefaults = {
    ...(checkInOn ? { checkInOn } : {}),
    ...(checkOutOn ? { checkOutOn } : {}),
    ...(adults ? { adults } : {}),
    ...(children ? { children } : {}),
  };

  const detail = await loadStayDetail(slug);
  if (!detail?.propertyId || !hasDatabaseUrl()) {
    if (!detail) {
      return (
        <main className="section">
          <div className="container">
            <p className="notice notice--info" role="status">
              {t('comingOnline')}
            </p>
          </div>
        </main>
      );
    }
    notFound();
  }

  const [property, viewer] = await Promise.all([
    loadPublicPropertyShowcaseFromNeon(detail.propertyId).catch(() => null),
    getViewer().catch(() => null),
  ]);
  if (!property) notFound();

  const title = localizedName(locale, detail.titleAr, detail.titleEn);
  const focusUnitId = (() => {
    if (detail.unitId) {
      const linked = property.units.find((unit) => unit.id === detail.unitId);
      if (linked && (linked.bedrooms ?? 0) > 0) return detail.unitId;
    }
    const residential = [...property.units]
      .filter((unit) => (unit.bedrooms ?? 0) > 0)
      .sort((a, b) => a.code.localeCompare(b.code))[0];
    return residential?.id ?? detail.unitId;
  })();

  const propertyForDisplay = {
    ...property,
    descriptionAr: detail.descriptionAr || property.descriptionAr,
    descriptionEn: detail.descriptionEn || property.descriptionEn,
  };

  return (
    <main className="section">
      <div className="container">
        <PropertyDetailManager
          property={propertyForDisplay}
          locale={locale}
          portal="owner"
          variant="public"
          focusUnitId={focusUnitId}
          signedIn={Boolean(viewer)}
          stayBooking={{
            slug,
            title,
            nightlyMinor: detail.nightlyMinor,
            currency: detail.currency,
            maxGuests: detail.maxGuests,
            ...dateDefaults,
          }}
        />
      </div>
    </main>
  );
}

import type { Metadata } from 'next';
import { EmptyState } from '@bhd-r/ui';
import { getTranslations, setRequestLocale } from 'next-intl/server';
import { notFound } from 'next/navigation';
import { StayCard, type StayCardListing } from '@/components/stays/stay-card';
import { StaySearch } from '@/components/stays/stay-search';
import { hasDatabaseUrl } from '@/lib/bhd/identity-session';
import { searchPublicStaysOnNeon } from '@/lib/load-public-stays-neon';
import { isStaysPublicSurfaceEnabled } from '@/lib/stays-flags';
import { publicApiFetch } from '@/lib/server-api';
import type { StaySearchQuery } from '@bhd-r/contracts';

type SearchResult = {
  items?: StayCardListing[];
  nextCursor?: string | null;
};

export async function generateMetadata({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}): Promise<Metadata> {
  const query = await searchParams;
  const dated = typeof query.checkInOn === 'string' || typeof query.checkOutOn === 'string';
  return {
    robots: dated ? { index: false, follow: true } : { index: true, follow: true },
  };
}

export default async function StaysSearchPage({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string }>;
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  if (!isStaysPublicSurfaceEnabled()) notFound();
  const { locale: rawLocale } = await params;
  const locale = rawLocale === 'en' ? 'en' : 'ar';
  setRequestLocale(locale);
  const t = await getTranslations('Stays');
  const ar = locale === 'ar';
  const query = await searchParams;

  const pick = (key: string) => {
    const value = query[key];
    return typeof value === 'string' ? value : undefined;
  };

  const destination = pick('destination');
  const checkInOn = pick('checkInOn');
  const checkOutOn = pick('checkOutOn');
  const adults = pick('adults');
  const children = pick('children');

  const qs = new URLSearchParams();
  qs.set('locale', locale === 'en' ? 'en' : 'ar');
  if (destination) qs.set('governorate', destination);
  if (checkInOn) qs.set('checkInOn', checkInOn);
  if (checkOutOn) qs.set('checkOutOn', checkOutOn);
  if (adults) qs.set('adults', adults);
  if (children) qs.set('children', children);

  const searchQuery: StaySearchQuery = {
    countryCode: 'OM',
    locale: locale === 'en' ? 'en' : 'ar',
    limit: 24,
    adults: Number.parseInt(adults ?? '2', 10) || 2,
    children: Number.parseInt(children ?? '0', 10) || 0,
    ...(destination ? { governorate: destination } : {}),
    ...(checkInOn ? { checkInOn } : {}),
    ...(checkOutOn ? { checkOutOn } : {}),
  };

  let items: StayCardListing[] = [];
  if (hasDatabaseUrl()) {
    try {
      const neon = await searchPublicStaysOnNeon(searchQuery);
      items = neon.items as StayCardListing[];
    } catch (error) {
      console.error('Neon public stays search failed', error);
    }
  }
  if (!items.length) {
    const result = await publicApiFetch<SearchResult>(
      `/v1/public/stays/search?${qs.toString()}`,
      8,
    ).catch(() => ({ items: [] as StayCardListing[] }));
    items = result.items ?? [];
  }

  const resultsLine =
    checkInOn && checkOutOn
      ? ar
        ? `${items.length} إقامة متاحة للتواريخ المحددة`
        : `${items.length} stays available for your dates`
      : ar
        ? `${items.length} إقامة يومية`
        : `${items.length} daily stays`;

  return (
    <div className="stays-public stays-public--search">
      <section className="stays-hero" aria-labelledby="stays-search-heading">
        <div className="container stays-hero__inner">
          <header className="stays-hero__copy">
            <span className="section-kicker">BHD R</span>
            <h1 id="stays-search-heading">{t('searchTitle')}</h1>
            <p className="stays-hero__lede">{t('shellHint')}</p>
          </header>
          <div className="stays-hero__search">
            <StaySearch
              locale={locale}
              variant="inline"
              defaults={{
                ...(destination ? { destination } : {}),
                ...(checkInOn ? { checkInOn } : {}),
                ...(checkOutOn ? { checkOutOn } : {}),
                ...(adults ? { adults } : {}),
                ...(children ? { children } : {}),
              }}
            />
          </div>
        </div>
      </section>

      <div className="container stays-public__results">
        <p className="stays-public__results-meta" role="status">
          {resultsLine}
        </p>

        {items.length ? (
          <div className="stays-public__grid">
            {items.map((listing) => (
              <StayCard
                key={listing.slug}
                listing={listing}
                locale={locale}
                query={{
                  ...(checkInOn ? { checkInOn } : {}),
                  ...(checkOutOn ? { checkOutOn } : {}),
                  ...(adults ? { adults } : {}),
                  ...(children ? { children } : {}),
                }}
              />
            ))}
          </div>
        ) : (
          <EmptyState title={t('noResults')} description={t('comingOnline')} />
        )}
      </div>
    </div>
  );
}

