/** Compact mark shown inside each day cell. */
function statusMark(status: StayInventoryDay['availabilityStatus'], ar: boolean): string | null {
  switch (status) {
    case 'available':
      return ar ? 'شاغر' : 'Free';
    case 'booked':
      return ar ? 'محجوز' : 'Booked';
    case 'hold':
      return ar ? 'مؤقت' : 'Hold';
    case 'blocked':
    case 'maintenance':
    case 'lease':
      return ar ? 'مغلق' : 'Closed';
    default:
      return null;
  }
}

