    const profileRow = profileRows[0] as
      | {
          currency: string;
          minor_unit: number;
          base_nightly_minor: string | null;
        }
      | undefined;
    if (!profileRow) throw new Error('unit_not_found');

    const [existing] = await transaction
      .select()
