import { readFileSync } from 'node:fs';
import { createDatabase } from '@bhd-r/db';
import { sql } from 'drizzle-orm';

const env = readFileSync(new URL('./.env.neon', import.meta.url), 'utf8');
const url = env
  .split(/\r?\n/)
  .find((line) => line.startsWith('DATABASE_URL='[REDACTED-DATABASE-URL]
  ?.slice('DATABASE_URL='[REDACTED-DATABASE-URL]
  ?.trim();
if (!url) throw new Error('DATABASE_URL missing');

const { db, client } = createDatabase(url, { max: 1 });

function rowsOf(result) {
  return Array.isArray(result) ? result : (result?.rows ?? []);
}

try {
  await db.transaction(async (tx) => {
    await tx.execute(sql`select set_config('app.public', 'true', true)`);
    await tx.execute(sql`select set_config('app.platform_admin', 'false', true)`);
    const cfg = rowsOf(
      await tx.execute(sql`
        select current_user as usr,
               current_setting('app.public', true) as pub,
               current_setting('app.organization_id', true) as org,
               app_private.is_public() as is_pub,
               app_private.current_organization_id()::text as cur_org,
               app_private.is_platform_admin() as is_admin
      `),
    );
    console.log('CFG', cfg[0]);

    const policies = rowsOf(
      await tx.execute(sql`
        select tablename, policyname, cmd, qual, with_check
        from pg_policies
        where tablename in ('stay_quotes','stay_holds','stay_inventory_locks','outbox_events')
        order by tablename, policyname
      `),
    );
    console.log('POLICIES', policies);

    const force = rowsOf(
      await tx.execute(sql`
        select c.relname, c.relrowsecurity, c.relforcerowsecurity
        from pg_class c
        join pg_namespace n on n.oid = c.relnamespace
        where n.nspname = 'public'
          and c.relname in ('stay_quotes','stay_holds','stay_inventory_locks','outbox_events')
      `),
    );
    console.log('FORCE', force);
  });

  // Reproduce hold path against a fresh quote
  const quoteId = process.argv[2];
  if (!quoteId) {
    console.log('Pass quoteId to attempt lock insert');
    process.exit(0);
  }

  await db.transaction(async (tx) => {
    await tx.execute(sql`select set_config('app.public', 'true', true)`);
    await tx.execute(sql`select set_config('app.platform_admin', 'false', true)`);

    const quoteRows = rowsOf(
      await tx.execute(sql`
        select id::text, organization_id::text, unit_id::text, check_in_on::text, check_out_on::text
        from stay_quotes where id = ${quoteId}::uuid
      `),
    );
    console.log('QUOTE', quoteRows[0]);
    const q = quoteRows[0];
    if (!q) throw new Error('quote missing');

    try {
      const inserted = rowsOf(
        await tx.execute(sql`
          INSERT INTO stay_inventory_locks (
            organization_id, unit_id, stay_range, kind, status,
            source_type, source_id, expires_at, note
          ) VALUES (
            ${q.organization_id}::uuid,
            ${q.unit_id}::uuid,
            daterange(${q.check_in_on}::date, ${q.check_out_on}::date, '[)'),
            'hold',
            'active',
            'stay_quote',
            ${q.id}::uuid,
            now() + interval '15 minutes',
            'debug hold'
          )
          RETURNING id::text
        `),
      );
      console.log('LOCK OK', inserted[0]);
    } catch (error) {
      console.error('LOCK FAIL', error);
      throw error;
    }
  });
} finally {
  await client.end();
}

import { readFileSync } from 'node:fs';
import pg from 'pg';

const env = readFileSync(new URL('./.env.neon', import.meta.url), 'utf8');
const url = env
  .split(/\r?\n/)
  .find((line) => line.startsWith('DATABASE_URL='[REDACTED-DATABASE-URL]
  ?.slice('DATABASE_URL='[REDACTED-DATABASE-URL]
  ?.trim();
if (!url) throw new Error('DATABASE_URL missing');

const client = new pg.Client({ connectionString: url, ssl: { rejectUnauthorized: false } });
await client.connect();

try {
  await client.query('BEGIN');
  await client.query(`select set_config('app.public', 'true', true)`);
  await client.query(`select set_config('app.platform_admin', 'false', true)`);

  const cfg = await client.query(`
    select current_user as usr,
           current_setting('app.public', true) as pub,
           current_setting('app.organization_id', true) as org,
           app_private.is_public() as is_pub,
           app_private.current_organization_id()::text as cur_org,
           app_private.is_platform_admin() as is_admin
  `);
  console.log('CFG', cfg.rows[0]);

  const policies = await client.query(`
    select tablename, policyname, cmd, qual, with_check
    from pg_policies
    where tablename in ('stay_quotes','stay_holds','stay_inventory_locks','outbox_events')
    order by tablename, policyname
  `);
  console.log('POLICIES', JSON.stringify(policies.rows, null, 2));

  const force = await client.query(`
    select c.relname, c.relrowsecurity, c.relforcerowsecurity
    from pg_class c
    join pg_namespace n on n.oid = c.relnamespace
    where n.nspname = 'public'
      and c.relname in ('stay_quotes','stay_holds','stay_inventory_locks','outbox_events')
  `);
  console.log('FORCE', force.rows);

  const quoteId = process.argv[2];
  if (!quoteId) {
    await client.query('ROLLBACK');
    process.exit(0);
  }

  const quote = await client.query(
    `select id::text, organization_id::text, unit_id::text, check_in_on::text, check_out_on::text
     from stay_quotes where id = $1::uuid`,
    [quoteId],
  );
  console.log('QUOTE', quote.rows[0]);
  const q = quote.rows[0];
  if (!q) throw new Error('quote missing');

  try {
    const inserted = await client.query(
      `INSERT INTO stay_inventory_locks (
        organization_id, unit_id, stay_range, kind, status,
        source_type, source_id, expires_at, note
      ) VALUES (
        $1::uuid, $2::uuid,
        daterange($3::date, $4::date, '[)'),
        'hold', 'active', 'stay_quote', $5::uuid,
        now() + interval '15 minutes', 'debug hold'
      ) RETURNING id::text`,
      [q.organization_id, q.unit_id, q.check_in_on, q.check_out_on, q.id],
    );
    console.log('LOCK OK', inserted.rows[0]);
  } catch (error) {
    console.error('LOCK FAIL', error.message);
  }

  try {
    const hold = await client.query(
      `INSERT INTO stay_holds (
        organization_id, quote_id, inventory_lock_id, status, expires_at, idempotency_key
      ) VALUES (
        $1::uuid, $2::uuid,
        (select id from stay_inventory_locks where source_id = $2::uuid order by created_at desc limit 1),
        'active', now() + interval '15 minutes', $3
      ) RETURNING id::text`,
      [q.organization_id, q.id, `debug-${Date.now()}`],
    );
    console.log('HOLD OK', hold.rows[0]);
  } catch (error) {
    console.error('HOLD FAIL', error.message);
  }

  await client.query('ROLLBACK');
} finally {
  await client.end();
}

