import { readFileSync } from 'node:fs';
import { createDatabase, stayHolds, stayQuotes } from './dist/index.js';
import { and, eq, sql } from 'drizzle-orm';
import { formatDaterangeLiteral } from '../../packages/domain/dist/index.js';

const env = readFileSync(new URL('../../.env.neon', import.meta.url), 'utf8');
const url = env
  .split(/\r?\n/)
  .find((line) => line.startsWith('DATABASE_URL='[REDACTED-DATABASE-URL]
  ?.slice('DATABASE_URL='[REDACTED-DATABASE-URL]
  ?.trim();
if (!url) throw new Error('DATABASE_URL missing');

const { db, client } = createDatabase(url, { max: 1 });
const quoteId = process.argv[2];
const idempotencyKey = `local-hold-fixed-${Date.now()}`;

try {
  const result = await db.transaction(async (transaction) => {
    await transaction.execute(sql`select set_config('app.public', 'true', true)`);
    await transaction.execute(sql`select set_config('app.platform_admin', 'false', true)`);

    const quote = await transaction.query.stayQuotes.findFirst({
      where: eq(stayQuotes.id, quoteId),
    });
    if (!quote) throw new Error('no quote');
    if (quote.expiresAt.getTime() <= Date.now()) throw new Error('quote expired');

    const stayRange = formatDaterangeLiteral({
      checkInOn: quote.checkInOn,
      checkOutOn: quote.checkOutOn,
    });
    const expiresAt = new Date(Date.now() + 15 * 60_000);

    await transaction.execute(sql`select pg_advisory_xact_lock(hashtext(${quote.unitId}::text))`);

    const inserted = await transaction.execute(sql`
      INSERT INTO stay_inventory_locks (
        organization_id, unit_id, stay_range, kind, status,
        source_type, source_id, expires_at, note
      ) VALUES (
        ${quote.organizationId}::uuid,
        ${quote.unitId}::uuid,
        ${stayRange}::daterange,
        'hold',
        'active',
        'stay_quote',
        ${quote.id}::uuid,
        ${expiresAt.toISOString()},
        'Public stay hold'
      )
      RETURNING id
    `);
    const rows = Array.isArray(inserted) ? inserted : (inserted?.rows ?? []);
    console.log('LOCK', rows[0]);

    const [hold] = await transaction
      .insert(stayHolds)
      .values({
        organizationId: quote.organizationId,
        quoteId: quote.id,
        inventoryLockId: rows[0].id,
        status: 'active',
        expiresAt,
        idempotencyKey,
      })
      .returning();
    console.log('HOLD', hold?.id);
    throw new Error('rollback_debug');
  });
  console.log(result);
} catch (error) {
  if (error.message !== 'rollback_debug') console.error('FAIL', error);
  else console.log('OK fixed path');
} finally {
  await client.end({ timeout: 1 });
}

