/** Client helpers for recent stay booking alerts (header bell + guest trips). */

export type StayTripAlert = {
  id: string;
  referenceCode: string;
  status: string;
  checkInOn: string;
  checkOutOn: string;
  currency?: string;
  totalMinor?: string;
  updatedAt: string;
};

const STORAGE_KEY = 'bhd-r-stay-trip-alerts';
const MAX_ITEMS = 12;

export function readStayTripAlerts(): StayTripAlert[] {
  if (typeof window === 'undefined') return [];
  try {
    const raw = window.localStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw) as StayTripAlert[];
    if (!Array.isArray(parsed)) return [];
    return parsed.filter(
      (item) =>
        item &&
        typeof item.id === 'string' &&
        typeof item.referenceCode === 'string' &&
        typeof item.status === 'string',
    );
  } catch {
    return [];
  }
}

export function rememberStayTripAlert(alert: Omit<StayTripAlert, 'updatedAt'> & { updatedAt?: string }) {
  if (typeof window === 'undefined') return;
  const next: StayTripAlert = {
    ...alert,
    updatedAt: alert.updatedAt ?? new Date().toISOString(),
  };
  const existing = readStayTripAlerts().filter(
    (item) => item.id !== next.id && item.referenceCode !== next.referenceCode,
  );
  const merged = [next, ...existing].slice(0, MAX_ITEMS);
  try {
    window.localStorage.setItem(STORAGE_KEY, JSON.stringify(merged));
    window.dispatchEvent(new CustomEvent('bhd-r-stay-alerts'));
  } catch {
    // ignore quota / private mode
  }
}

export function stayAlertNeedsAction(status: string): boolean {
  return (
    status === 'payment_pending' ||
    status === 'request_pending' ||
    status === 'payment_failed'
  );
}

export function stayStatusLabel(status: string, ar: boolean): string {
  switch (status) {
    case 'payment_pending':
    case 'request_pending':
      return ar ? 'بانتظار الدفع' : 'Awaiting payment';
    case 'confirmed':
    case 'paid':
    case 'pre_arrival':
      return ar ? 'مؤكّد' : 'Confirmed';
    case 'checked_in':
      return ar ? 'تم تسجيل الوصول' : 'Checked in';
    case 'checked_out':
    case 'closed':
      return ar ? 'مكتمل' : 'Completed';
    case 'cancelled':
    case 'expired':
      return ar ? 'ملغى / منتهٍ' : 'Cancelled / expired';
    case 'payment_failed':
      return ar ? 'فشل الدفع' : 'Payment failed';
    default:
      return status;
  }
}

'use client';

import { useEffect, useMemo, useRef, useState, useTransition } from 'react';
import { Link } from '@/i18n/navigation';
import {
  readStayTripAlerts,
  rememberStayTripAlert,
  stayAlertNeedsAction,
  stayStatusLabel,
  type StayTripAlert,
} from '@/lib/stay-trip-alerts';

type MineResponse = { items?: StayTripAlertLike[] };
type StayTripAlertLike = {
  id: string;
  referenceCode: string;
  status: string;
  checkInOn: string;
  checkOutOn: string;
  currency?: string;
  totalMinor?: string;
};

function mergeAlerts(local: StayTripAlert[], remote: StayTripAlertLike[]): StayTripAlert[] {
  const map = new Map<string, StayTripAlert>();
  for (const item of local) {
    map.set(item.referenceCode, item);
  }
  for (const item of remote) {
    map.set(item.referenceCode, {
      id: item.id,
      referenceCode: item.referenceCode,
      status: item.status,
      checkInOn: item.checkInOn,
      checkOutOn: item.checkOutOn,
      ...(item.currency ? { currency: item.currency } : {}),
      ...(item.totalMinor ? { totalMinor: item.totalMinor } : {}),
      updatedAt: new Date().toISOString(),
    });
  }
  return Array.from(map.values()).sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));
}

export function HeaderStayAlerts({
  locale,
  signedIn,
}: {
  locale: string;
  signedIn: boolean;
}) {
  const ar = locale === 'ar';
  const [open, setOpen] = useState(false);
  const [items, setItems] = useState<StayTripAlert[]>([]);
  const [pending, startTransition] = useTransition();
  const rootRef = useRef<HTMLDivElement>(null);

  function refreshLocal() {
    setItems((prev) => mergeAlerts(readStayTripAlerts(), prev));
  }

  useEffect(() => {
    setItems(readStayTripAlerts());
    const onStorage = () => setItems(readStayTripAlerts());
    window.addEventListener('storage', onStorage);
    window.addEventListener('bhd-r-stay-alerts', onStorage);
    return () => {
      window.removeEventListener('storage', onStorage);
      window.removeEventListener('bhd-r-stay-alerts', onStorage);
    };
  }, []);

  useEffect(() => {
    if (!signedIn) return;
    startTransition(async () => {
      try {
        const response = await fetch('/api/public/stays/bookings/mine', {
          credentials: 'same-origin',
          headers: { accept: 'application/json' },
          cache: 'no-store',
          signal: AbortSignal.timeout(12_000),
        });
        if (!response.ok) return;
        const payload = (await response.json()) as MineResponse;
        const remote = payload.items ?? [];
        for (const item of remote) {
          rememberStayTripAlert(item);
        }
        setItems(mergeAlerts(readStayTripAlerts(), remote));
      } catch {
        refreshLocal();
      }
    });
  }, [signedIn]);

  useEffect(() => {
    if (!open) return;
    function onPointer(event: MouseEvent) {
      if (!rootRef.current?.contains(event.target as Node)) setOpen(false);
    }
    function onKey(event: KeyboardEvent) {
      if (event.key === 'Escape') setOpen(false);
    }
    document.addEventListener('mousedown', onPointer);
    document.addEventListener('keydown', onKey);
    return () => {
      document.removeEventListener('mousedown', onPointer);
      document.removeEventListener('keydown', onKey);
    };
  }, [open]);

  const actionable = useMemo(
    () => items.filter((item) => stayAlertNeedsAction(item.status)).length,
    [items],
  );

  return (
    <div className="header-stay-alerts" ref={rootRef}>
      <button
        type="button"
        className="header-stay-alerts__bell"
        aria-expanded={open}
        aria-haspopup="dialog"
        aria-controls="header-stay-alerts-panel"
        onClick={() => setOpen((value) => !value)}
        title={ar ? 'الحجوزات والتنبيهات' : 'Bookings and alerts'}
      >
        <span aria-hidden="true">🔔</span>
        <span className="sr-only">{ar ? 'الحجوزات والتنبيهات' : 'Bookings and alerts'}</span>
        {actionable > 0 ? (
          <span className="header-stay-alerts__badge" aria-hidden="true">
            {actionable > 9 ? '9+' : actionable}
          </span>
        ) : null}
      </button>

      {open ? (
        <div
          id="header-stay-alerts-panel"
          className="header-stay-alerts__panel"
          role="dialog"
          aria-label={ar ? 'تنبيهات الحجوزات' : 'Booking alerts'}
        >
          <div className="header-stay-alerts__head">
            <strong>{ar ? 'حجوزاتي وتنبيهاتها' : 'My bookings & alerts'}</strong>
            {pending ? <span className="muted">{ar ? 'تحديث…' : 'Updating…'}</span> : null}
          </div>
          {items.length === 0 ? (
            <p className="muted header-stay-alerts__empty">
              {ar
                ? 'لا حجوزات بعد. بعد الحجز ستظهر هنا حالة الدفع والتذكيرات.'
                : 'No bookings yet. After you book, payment status and reminders appear here.'}
            </p>
          ) : (
            <ul className="header-stay-alerts__list">
              {items.slice(0, 8).map((item) => (
                <li key={item.referenceCode}>
                  <Link
                    href={`/guest/stays?ref=${encodeURIComponent(item.referenceCode)}`}
                    className="header-stay-alerts__item"
                    onClick={() => setOpen(false)}
                  >
                    <span className="header-stay-alerts__ref" dir="ltr">
                      {item.referenceCode}
                    </span>
                    <span className="header-stay-alerts__meta">
                      {item.checkInOn} → {item.checkOutOn}
                    </span>
                    <span
                      className={
                        stayAlertNeedsAction(item.status)
                          ? 'header-stay-alerts__status is-action'
                          : 'header-stay-alerts__status'
                      }
                    >
                      {stayStatusLabel(item.status, ar)}
                    </span>
                  </Link>
                </li>
              ))}
            </ul>
          )}
          <Link
            href="/guest/stays"
            className="header-stay-alerts__all"
            onClick={() => setOpen(false)}
          >
            {ar ? 'فتح صفحة الرحلات' : 'Open trips page'}
          </Link>
        </div>
      ) : null}
    </div>
  );
}

'use client';

import { useEffect, useState, useTransition } from 'react';
import { ApiError, browserNextMutation, fetchBrowserCsrfToken, humanizeBrowserError } from '@/lib/api';
import { Link } from '@/i18n/navigation';
import { rememberStayTripAlert, stayStatusLabel } from '@/lib/stay-trip-alerts';
import { formatMoney } from '@/lib/format';

type GuestBooking = {
  id: string;
  referenceCode: string;
  checkInOn: string;
  checkOutOn: string;
  status: string;
  currency: string;
  totalMinor: string;
  nights?: number;
};

export function GuestStayLookup({
  locale,
  initialReference,
  canClaim,
}: {
  locale: string;
  initialReference?: string;
  canClaim: boolean;
}) {
  const ar = locale === 'ar';
  const [referenceCode, setReferenceCode] = useState(initialReference ?? '');
  const [result, setResult] = useState<GuestBooking | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [hint, setHint] = useState<string | null>(null);
  const [pending, startTransition] = useTransition();
  const [autoTried, setAutoTried] = useState(false);

  async function runLookup(codeRaw: string) {
    setError(null);
    setHint(null);
    setResult(null);
    const code = codeRaw.trim().toUpperCase();
    if (code.length < 4) {
      setError(ar ? 'أدخل مرجع حجز صالحاً' : 'Enter a valid booking reference');
      return;
    }
    try {
      const response = await fetch(
        `/api/public/stays/bookings/lookup?referenceCode=${encodeURIComponent(code)}`,
        {
          method: 'GET',
          credentials: 'same-origin',
          headers: { accept: 'application/json' },
          cache: 'no-store',
          signal: AbortSignal.timeout(20_000),
        },
      );
      const payload = (await response.json().catch(() => null)) as
        | GuestBooking
        | { error?: { code?: string; messageAr?: string; message?: string } }
        | null;
      if (!response.ok) {
        const err = payload && 'error' in payload ? payload.error : null;
        throw new ApiError(
          response.status,
          err?.code ?? 'api_error',
          err?.messageAr ?? err?.message ?? (ar ? 'تعذر البحث عن الحجز.' : 'Could not look up booking.'),
        );
      }
      const booking = payload as GuestBooking;
      setResult(booking);
      rememberStayTripAlert({
        id: booking.id,
        referenceCode: booking.referenceCode,
        status: booking.status,
        checkInOn: booking.checkInOn,
        checkOutOn: booking.checkOutOn,
        currency: booking.currency,
        totalMinor: booking.totalMinor,
      });
    } catch (caught) {
      if (caught instanceof ApiError && caught.status === 404) {
        setError(
          ar
            ? 'لم يُعثر على الحجز أو المسار غير مفعّل.'
            : 'Booking not found or stays surface is disabled.',
        );
        return;
      }
      setError(humanizeBrowserError(caught, ar));
    }
  }

  function lookup() {
    startTransition(async () => {
      await runLookup(referenceCode);
    });
  }

  useEffect(() => {
    if (!initialReference || autoTried) return;
    setAutoTried(true);
    startTransition(async () => {
      await runLookup(initialReference);
    });
    // Auto-run once when arriving from confirmation with ?ref=
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [initialReference, autoTried]);

  function claim() {
    if (!result) return;
    startTransition(async () => {
      setError(null);
      setHint(null);
      try {
        const csrf = await fetchBrowserCsrfToken();
        await browserNextMutation('/api/public/stays/bookings/claim', {
          method: 'POST',
          headers: csrf ? { 'x-csrf-token': csrf } : undefined,
          body: JSON.stringify({ referenceCode: result.referenceCode }),
        });
        setHint(ar ? 'تم ربط الحجز بحسابك.' : 'Booking linked to your account.');
      } catch (caught) {
        if (caught instanceof ApiError && caught.status === 401) {
          setError(ar ? 'سجّل الدخول لربط الحجز بحسابك.' : 'Sign in to claim this booking.');
          return;
        }
        setError(humanizeBrowserError(caught, ar));
      }
    });
  }

  return (
    <section className="guest-stays-lookup" aria-labelledby="guest-lookup-title">
      <h2 id="guest-lookup-title">{ar ? 'ابحث بمرجع الحجز' : 'Look up by reference'}</h2>
      <form
        className="guest-stays-lookup__form"
        onSubmit={(event) => {
          event.preventDefault();
          lookup();
        }}
      >
        <div className="field">
          <label htmlFor="guest-ref">{ar ? 'مرجع الحجز' : 'Booking reference'}</label>
          <input
            className="input"
            id="guest-ref"
            dir="ltr"
            value={referenceCode}
            onChange={(event) => setReferenceCode(event.target.value)}
            placeholder="ST-…"
            disabled={pending}
            autoComplete="off"
          />
        </div>
        <button type="submit" className="button button--primary" disabled={pending}>
          {pending ? (ar ? 'جارٍ البحث…' : 'Looking up…') : ar ? 'بحث' : 'Look up'}
        </button>
      </form>

      {error ? (
        <p className="field__error" role="alert">
          {error}
        </p>
      ) : null}
      {hint ? (
        <p className="notice notice--info" role="status">
          {hint}
        </p>
      ) : null}

      {result ? (
        <article className="ops-panel guest-stays-lookup__result">
          <p>
            {ar ? 'المرجع' : 'Reference'}: <strong dir="ltr">{result.referenceCode}</strong>
          </p>
          <p>
            {ar ? 'الحالة' : 'Status'}: <strong>{stayStatusLabel(result.status, ar)}</strong>
          </p>
          <p>
            {result.checkInOn} → {result.checkOutOn}
            {result.nights != null ? ` · ${result.nights} ${ar ? 'ليلة' : 'nights'}` : ''}
          </p>
          <p dir="ltr">
            {formatMoney(result.totalMinor, result.currency, locale)}
          </p>
          <p>
            <Link
              className="text-link"
              href={`/guest/stays/${result.id}?ref=${encodeURIComponent(result.referenceCode)}`}
            >
              {ar ? 'تفاصيل الحجز' : 'Booking details'}
            </Link>
          </p>
          {canClaim ? (
            <button type="button" className="button" disabled={pending} onClick={() => claim()}>
              {ar ? 'اربط بحسابي' : 'Claim to my account'}
            </button>
          ) : (
            <p className="muted">
              {ar
                ? 'سجّل الدخول لربط الحجز بقائمة رحلاتك.'
                : 'Sign in to link this booking to your trips list.'}
            </p>
          )}
        </article>
      ) : null}
    </section>
  );
}

