    }
    if (row.overnightOnlyRate.trim() && !overnightOnlyMinor) {
      throw new Error(locale === 'ar' ? 'سعر المبيت فقط غير صالح' : 'Invalid overnight-only rate');
    }
    const depositMinor = row.depositAmount.trim()
