  switch (status) {
    case 'succeeded':
      return ar ? 'مدفوع' : 'Paid';
    case 'pending':
      return ar ? 'بانتظار الدفع' : 'Awaiting payment';
    case 'failed':
      return ar ? 'فشل الدفع' : 'Payment failed';
    case 'cancelled':
      return ar ? 'ملغى' : 'Cancelled';
    default:
      return status;
  }
}

