      if (caught instanceof ApiError && caught.status === 404) {
        setError(ar ? 'مسار الإقامات غير مفعّل حالياً.' : 'Stays booking is not enabled yet.');
        return;
      }
      setError(humanizeBrowserError(caught, ar));
