export async function isRangeAvailableInTransaction(
  transaction: Tx,
  organizationId: string,
  unitId: string,
  checkInOn: string,
  checkOutOn: string,
  stayType: 'overnight_stay' | 'day_use' | 'overnight_only' = 'overnight_stay',
  excludeBookingId?: string,
): Promise<boolean> {
  await releaseExpiredHoldsInTransaction(transaction, organizationId);

  const lockSlot =
    stayType === 'day_use' ? 'morning' : stayType === 'overnight_only' ? 'evening' : 'full';

  // When confirming payment, ignore this booking's own hold lock — otherwise every pay fails.
  let excludeLockIds: string[] = [];
  if (excludeBookingId) {
    const ownLocks = await transaction.execute(sql`
      SELECT DISTINCT lock_id
      FROM (
        SELECT b.inventory_lock_id::text AS lock_id
        FROM stay_bookings b
        WHERE b.id = ${excludeBookingId}::uuid
          AND b.inventory_lock_id IS NOT NULL
        UNION ALL
        SELECT h.inventory_lock_id::text AS lock_id
        FROM stay_bookings b
        INNER JOIN stay_holds h ON h.id = b.hold_id
        WHERE b.id = ${excludeBookingId}::uuid
          AND h.inventory_lock_id IS NOT NULL
      ) own
    `);
    const rows = Array.isArray(ownLocks)
      ? ownLocks
      : ((ownLocks as { rows?: Array<{ lock_id: string }> }).rows ?? []);
    excludeLockIds = (rows as Array<{ lock_id: string }>)
      .map((row) => row.lock_id)
      .filter(Boolean);
  }

  const slotReady = await hasLockSlotColumn(transaction);
  const excludeLockClause =
    excludeLockIds.length > 0
      ? sql`AND id NOT IN (${sql.join(
          excludeLockIds.map((id) => sql`${id}::uuid`),
          sql`, `,
        )})`
      : sql``;
  const conflicts = slotReady
    ? await transaction.execute(sql`
        SELECT count(*)::text AS count
        FROM stay_inventory_locks
        WHERE organization_id = ${organizationId}::uuid
          AND unit_id = ${unitId}::uuid
          AND status = 'active'
          AND stay_range && daterange(${checkInOn}::date, ${checkOutOn}::date, '[)')
          AND (
            lock_slot = 'full'
            OR ${lockSlot} = 'full'
            OR lock_slot = ${lockSlot}
          )
          ${excludeLockClause}
      `)
    : await transaction.execute(sql`
        SELECT count(*)::text AS count
        FROM stay_inventory_locks
        WHERE organization_id = ${organizationId}::uuid
          AND unit_id = ${unitId}::uuid
          AND status = 'active'
          AND stay_range && daterange(${checkInOn}::date, ${checkOutOn}::date, '[)')
          ${excludeLockClause}
      `);
  const conflictRows = Array.isArray(conflicts)
    ? conflicts
    : ((conflicts as { rows?: Array<{ count: string }> }).rows ?? []);
  if ((conflictRows[0]?.count ?? '0') !== '0') return false;

  // Confirmed stays always block; unpaid drafts only while their hold is still active.
  const bookingRows = await transaction.execute(sql`
    SELECT b.id::text AS id, b.pricing_snapshot_json
    FROM stay_bookings b
    LEFT JOIN stay_holds h ON h.id = b.hold_id
    WHERE b.organization_id = ${organizationId}::uuid
      AND b.unit_id = ${unitId}::uuid
      AND daterange(b.check_in_on, b.check_out_on, '[)')
        && daterange(${checkInOn}::date, ${checkOutOn}::date, '[)')
      AND (
        b.status IN ('confirmed', 'pre_arrival', 'checked_in')
        OR (
          b.status = 'payment_pending'
          AND h.status = 'active'
          AND h.expires_at > now()
        )
      )
      ${excludeBookingId ? sql`AND b.id <> ${excludeBookingId}::uuid` : sql``}
  `);

