async function resolvePaymentIntentId(
  transaction: Tx,
  organizationId: string,
  bookingId: string,
): Promise<string | null> {
  const intent = await transaction.query.stayPaymentIntents.findFirst({
    where: and(
      eq(stayPaymentIntents.organizationId, organizationId),
      eq(stayPaymentIntents.bookingId, bookingId),
      eq(stayPaymentIntents.status, 'pending'),
    ),
    columns: { id: true },
    orderBy: [desc(stayPaymentIntents.createdAt)],
  });
  return intent?.id ?? null;
}

